#!/usr/bin/env bash
# Nano Panel v4.7 — Reconstrucción independiente basada en NanoVPSScript-v4.6.sh
# Banner: ASCII original inspirado en Katoolin; degradado TRON: Legacy (cian, blanco y ámbar).
# Interfaz: Proot-Distro / Debian Edition; temas: Debian, Cyber Magenta + Cyan, Matrix, Blue & Gold e Inferno.
# Uso: Bash por SSH/Termius; diseño adaptable a terminal móvil, tablet y escritorio.
# Compatibilidad multidistro: Debian, Ubuntu, AlmaLinux, Rocky, Fedora, CentOS, Oracle, Arch, openSUSE y Alpine.
# Seguridad: confirmación explícita antes de acciones; elevación sudo opcional; no instala nada al iniciar.
# Integridad: payload embebido conservado y verificado; el archivo v4.6 original permanece intacto.
set -u
umask 077

APP_NAME="Nano Panel"
APP_VERSION="4.7"
IS_TERMUX=0
[[ -n "${PREFIX:-}" && "${PREFIX:-}" == *com.termux* ]] && IS_TERMUX=1
[[ -d /data/data/com.termux/files/usr ]] && IS_TERMUX=1

CONFIG_DIR="${XDG_CONFIG_HOME:-${HOME:-/tmp}/.config}/nanoscript"
LANGUAGE_FILE="$CONFIG_DIR/language"
LANGUAGE=""
declare -A T=()
NANO_MIN_BASH="4.0"
NANO_MIN_SYSTEMD="219"
NANO_PM_REFRESHED=0

# Adaptación interna multidistro (auto-detección)
NANO_PM=""; NANO_INIT=""; NANO_OS=""; NANO_DISTRO=""
# Panel VPS adaptativo (recursos reales, independiente de distro)
PANEL_BG="#080D18"; PANEL_CYAN="#22D3EE"; PANEL_MAGENTA="#FF35C8"; PANEL_OK="#A3E635"; PANEL_WARN="#E5B52B"; PANEL_ERR="#E04444"
VPS_RES_CPU=""; VPS_RES_RAM=""; VPS_RES_DISK=""; VPS_RES_NET=""; VPS_RES_STATE=""
detect_resources() { VPS_RES_CPU=$(grep 'cpu ' /proc/stat 2>/dev/null | awk '{print $2}'); VPS_RES_RAM=$(free -m 2>/dev/null | awk '/Mem:/{print $2}'); VPS_RES_DISK=$(df -h / 2>/dev/null | awk 'NR==2{print $4}'); VPS_RES_NET=$(cat /sys/class/net/eth0/operstate 2>/dev/null || echo "unknown"); VPS_RES_STATE="active"; }

detect_distro() { [[ -r /etc/os-release ]] && NANO_DISTRO=$(grep '^ID=' /etc/os-release | cut -d= -f2 | tr -d '"'); }

load_i18n() {
  local key es en pt fr
  while IFS='|' read -r key es en pt fr; do
    [[ -z "$key" ]] && continue
    T["es:$key"]="$es"
    T["en:$key"]="$en"
    T["pt:$key"]="$pt"
    T["fr:$key"]="$fr"
  done <<'I18N'
