I18N
}

t() {
  local key="$1" value
  value="${T[${LANGUAGE}:${key}]-}"
  [[ -n "$value" ]] || value="${T[en:${key}]-$key}"
  printf '%s' "$value"
}

ui_message_color() {
  case "$1" in
    invalid|*fail*|*failed*|*error*|*denied*|*exceeded*|*integrity*)
      printf '%s' "$UI_RED"
      ;;
    *warn*|*cancel*)
      printf '%s' "$UI_MAGENTA"
      ;;
    *done*|*saved*|*created*|*deleted*|*success*|*ready*|*_ok|ok)
      printf '%s' "$UI_LIME"
      ;;
    *)
      printf '%s' "$UI_WHITE"
      ;;
  esac
}

say() {
  local key="$1" color
  color="$(ui_message_color "$key")"
  ui_text "$(t "$key")" "  " "$color"
}
sayf() {
  local key="$1" color
  shift
  color="$(ui_message_color "$key")"
  ui_text "$(printf "$(t "$key")" "$@")" "  " "$color"
}

ui_fill() {
  local char="${1:- }" count="${2:-0}" out
  (( count < 0 )) && count=0
  printf -v out '%*s' "$count" ''
  printf '%s' "${out// /$char}"
}

ui_panel_width() {
  local width=$(( UI_COLS - 4 ))
  (( width > 96 )) && width=96
  (( width < 16 )) && width=16
  printf '%s' "$width"
}

line() {
  ui_init
  local width
  width="$(ui_panel_width)"
  printf '  %s+%s+%s\n' "$UI_BORDER" "$(ui_fill '-' "$width")" "$UI_RESET"
}

UI_READY=0
UI_TTY=0
UI_COLS=80
UI_LINES=24
UI_LAST_COLS=0
UI_LAST_LINES=0
UI_RESIZED=0
UI_COLOR_MODE="none"
UI_BANNER_SHOWN=0

UI_FULL_MIN=77
UI_COMPACT_MIN=50
UI_BREAK_FULL="${NANO_BREAK_FULL:-78}"
UI_BREAK_TABLET="${NANO_BREAK_TABLET:-54}"
[[ "$UI_BREAK_FULL" =~ ^[0-9]+$ ]] || UI_BREAK_FULL=78
[[ "$UI_BREAK_TABLET" =~ ^[0-9]+$ ]] || UI_BREAK_TABLET=54
(( UI_BREAK_FULL < UI_FULL_MIN )) && UI_BREAK_FULL=$UI_FULL_MIN
(( UI_BREAK_TABLET < UI_COMPACT_MIN )) && UI_BREAK_TABLET=$UI_COMPACT_MIN
(( UI_BREAK_TABLET >= UI_BREAK_FULL )) && UI_BREAK_TABLET=$(( UI_BREAK_FULL - 1 ))
(( UI_BREAK_TABLET < UI_COMPACT_MIN )) && UI_BREAK_TABLET=$UI_COMPACT_MIN
UI_RESET=""
UI_BOLD=""
UI_PANEL=""
UI_BORDER=""
UI_CYAN=""
UI_MAGENTA=""
UI_LIME=""
UI_DIM=""
UI_RED=""
UI_ORANGE=""
UI_WHITE=""
UI_ON=""
UI_OFF=""
UI_SELECT=""
UI_STTY_SAVED=""
UI_MENU_ACTIVE=0
UI_MENU_SELECTED=0
UI_MENU_ROWS=0
UI_MENU_COLS=1
UI_MENU_NUMW=1
UI_MENU_MAXW=0
UI_MENU_INDENT=2
UI_MENU_GAP=2
UI_MENU_COUNT=0
UI_MENU_ITEMS=()
UI_THEME="${NANO_THEME:-}"
UI_THEME_LOADED=0
UI_THEME_FILE="$CONFIG_DIR/theme"

ui_init() {
  local was_ready="${UI_READY:-0}"
  UI_TTY=0
  [[ -t 1 ]] && UI_TTY=1

  local cols="" lines="" stty_out="" stty_rows="" stty_cols="" requested="${NANO_COLOR:-auto}" n="" t
  if (( UI_TTY )) && command -v stty >/dev/null 2>&1; then
    stty_out="$(stty size 2>/dev/null || true)"
    if [[ "$stty_out" =~ ^[0-9]+[[:space:]]+[0-9]+$ ]]; then
      stty_rows="${stty_out%%[[:space:]]*}"
      stty_cols="${stty_out##*[[:space:]]}"
      cols="$stty_cols"
      lines="$stty_rows"
    fi
  fi
  if [[ ! "$cols" =~ ^[0-9]+$ ]] || (( cols <= 0 )); then
    cols="${COLUMNS:-}"
  fi
  if [[ ! "$lines" =~ ^[0-9]+$ ]] || (( lines <= 0 )); then
    lines="${LINES:-}"
  fi
  if { [[ ! "$cols" =~ ^[0-9]+$ ]] || (( cols <= 0 )); } && (( UI_TTY )) && command -v tput >/dev/null 2>&1; then
    cols="$(tput cols 2>/dev/null || true)"
  fi
  if { [[ ! "$lines" =~ ^[0-9]+$ ]] || (( lines <= 0 )); } && (( UI_TTY )) && command -v tput >/dev/null 2>&1; then
    lines="$(tput lines 2>/dev/null || true)"
  fi
  if [[ ! "$cols" =~ ^[0-9]+$ ]] || (( cols <= 0 )); then
    cols=80
  fi
  if [[ ! "$lines" =~ ^[0-9]+$ ]] || (( lines <= 0 )); then
    lines=24
  fi
  (( cols < 20 )) && cols=20
  (( lines < 1 )) && lines=1
  if [[ "$UI_LAST_COLS" != "$cols" || "$UI_LAST_LINES" != "$lines" ]]; then
    (( UI_LAST_COLS > 0 )) && UI_RESIZED=1
    UI_LAST_COLS="$cols"
    UI_LAST_LINES="$lines"
  fi
  UI_COLS="$cols"
  UI_LINES="$lines"
  if (( was_ready )); then return 0; fi
  UI_READY=1

  case "$requested" in
    24|truecolor|true) UI_COLOR_MODE=24 ;;
    256|8bit|8-bit) UI_COLOR_MODE=256 ;;
    16|ansi) UI_COLOR_MODE=16 ;;
    none|no|off|0) UI_COLOR_MODE=none ;;
    *) UI_COLOR_MODE=auto ;;
  esac
  if [[ -n "${NO_COLOR+x}" || "${CLICOLOR:-}" == "0" || "${TERM:-}" == "dumb" ]]; then
    UI_COLOR_MODE=none
  fi
  if [[ "$UI_COLOR_MODE" == "auto" ]]; then
    if (( ! UI_TTY )); then
      UI_COLOR_MODE=none
    elif [[ "${COLORTERM:-}" == "truecolor" || "${COLORTERM:-}" == "24bit" || "${TERM:-}" == *direct* ]]; then
      UI_COLOR_MODE=24
    elif [[ "${TERM:-}" == *256* ]]; then
      UI_COLOR_MODE=256
    else
      n=""
      if command -v tput >/dev/null 2>&1; then
        n="$(tput colors 2>/dev/null || true)"
      fi
      if [[ "$n" =~ ^[0-9]+$ ]] && (( n >= 256 )); then
        UI_COLOR_MODE=256
      else
        UI_COLOR_MODE=16
      fi
    fi
  fi

  case "$UI_COLOR_MODE" in
    24|256|16)
      UI_RESET=$'\033[0m'
      UI_BOLD=$'\033[1m'
      ;;
    *)
      UI_COLOR_MODE="none"
      UI_RESET=""
      UI_BOLD=""
      ;;
  esac
  (( UI_THEME_LOADED )) || theme_load
  ui_apply_theme
}

theme_load() {
  local file_theme=""
  if [[ -z "${UI_THEME:-}" ]]; then
    if [[ -r "$UI_THEME_FILE" ]]; then
      IFS= read -r file_theme < "$UI_THEME_FILE" || file_theme=""
    fi
    UI_THEME="${file_theme:-debian}"
  fi
  case "$UI_THEME" in
    debian|cyberpunk|matrix|bluegold|inferno) ;;
    boca) UI_THEME="bluegold" ;;       # migrate v4.6 preference
    classic|ice|midnight|ocean|forest|sunset) UI_THEME="debian" ;; # legacy themes
    *) UI_THEME="debian" ;;
  esac
  UI_THEME_LOADED=1
}

theme_save() {
  install -d -m 0700 -- "$CONFIG_DIR" 2>/dev/null || return 1
  printf '%s\n' "$UI_THEME" > "$UI_THEME_FILE" 2>/dev/null || return 1
  chmod 0600 -- "$UI_THEME_FILE" 2>/dev/null || true
}

ui_palette_reset() {
  UI_PANEL=""
  UI_BORDER=""
  UI_CYAN=""
  UI_MAGENTA=""
  UI_LIME=""
  UI_DIM=""
  UI_RED=""
  UI_ORANGE=""
  UI_WHITE=""
  UI_ON=""
  UI_OFF=""
  UI_SELECT=""
}

ui_apply_theme() {
  ui_palette_reset
