ui_cleanup() {
  if [[ -n "${UI_STTY_SAVED:-}" ]]; then
    stty "$UI_STTY_SAVED" 2>/dev/null || true
    UI_STTY_SAVED=""
  fi
  [[ -n "${UI_RESET:-}" ]] && printf '%s' "$UI_RESET" 2>/dev/null || true
  if (( UI_TTY )); then
    printf '\033[?25h' 2>/dev/null || true
  fi
}

ui_raw_begin() {
  UI_STTY_SAVED="$(stty -g 2>/dev/null)" || return 1
  stty -icanon -echo min 1 time 0 2>/dev/null || {
    stty "$UI_STTY_SAVED" 2>/dev/null || true
    UI_STTY_SAVED=""
    return 1
  }
  return 0
}

ui_raw_end() {
  if [[ -n "${UI_STTY_SAVED:-}" ]]; then
    stty "$UI_STTY_SAVED" 2>/dev/null || true
    UI_STTY_SAVED=""
  fi
}

ui_install_resize_trap() {
  trap 'UI_RESIZED=1' WINCH 2>/dev/null || true
  trap 'ui_cleanup; exit 130' INT 2>/dev/null || true
  trap 'ui_cleanup; exit 143' TERM 2>/dev/null || true
  trap 'ui_cleanup' EXIT 2>/dev/null || true
}

ui_frame_begin() {
  ui_init
  UI_RESIZED=0
}

ui_profile() {
  ui_init
  if (( UI_COLS >= UI_BREAK_FULL )); then
    printf 'pc'
  elif (( UI_COLS >= UI_BREAK_TABLET )); then
    printf 'tablet'
  else
    printf 'mobile'
  fi
}

ui_text() {
  ui_init
  local text="$1" indent="${2:-}" color="${3:-}" avail chunk rest line panel
  panel="$(ui_panel_width)"
  avail=$(( panel + 2 - ${#indent} ))
  (( avail < 8 )) && avail=8
  while IFS= read -r line || [[ -n "$line" ]]; do
    rest="$line"
    if [[ -z "$rest" ]]; then
      printf '%s\n' "$indent"
      continue
    fi
    while (( ${#rest} > avail )); do
      chunk="${rest:0:avail}"
      if [[ "$chunk" == *" "* ]]; then
        chunk="${chunk% *}"
      fi
      printf '%s%s%s%s\n' "$indent" "$color" "$chunk" "$UI_RESET"
      rest="${rest:${#chunk}}"
      while [[ "$rest" == " "* ]]; do
        rest="${rest# }"
      done
    done
    printf '%s%s%s%s\n' "$indent" "$color" "$rest" "$UI_RESET"
  done <<< "$text"
}

ui_prompt() {
  ui_init
  local text="$1"
  if (( ${#text} >= UI_COLS - 2 )); then
    ui_text "$text" "  " "$UI_CYAN"
    printf '  %s> %s' "$UI_MAGENTA" "$UI_RESET"
    return
  fi
  printf '  %s%s%s' "$UI_CYAN" "$text" "$UI_RESET"
  [[ "$text" == *" " ]] || printf ' '
}

ui_fold() {
  ui_init
  local panel
  panel="$(ui_panel_width)"
  if command -v fold >/dev/null 2>&1; then
    fold -s -w "$(( panel + 2 ))" 2>/dev/null || cat
  else
    cat
  fi
}

ui_fit() {
  local text="$1" width="$2"
  (( width < 1 )) && width=1
  if (( ${#text} > width )); then
    if (( width > 3 )); then
      printf '%s' "${text:0:width-3}..."
    else
      printf '%s' "${text:0:width}"
    fi
  else
    printf '%s' "$text"
  fi
}

ui_menu() {
  ui_init
  local -a items=("$@")
  local n=${#items[@]} item num label maxw=0 numw=1 cell=0 cols=1 gap=2 indent=2 avail panel spread=0
  UI_MENU_ACTIVE=0
  (( n == 0 )) && return 0
  panel="$(ui_panel_width)"
  for item in "${items[@]}"; do
    num="${item%%|*}"
    label="${item#*|}"
    (( ${#num} > numw )) && numw=${#num}
    (( ${#label} > maxw )) && maxw=${#label}
  done
  cell=$(( 1 + numw + 2 + maxw ))
  avail=$(( panel + 2 - indent ))
  if (( UI_COLS >= UI_BREAK_TABLET )); then
    if (( cell * 2 + 2 <= avail )); then
      cols=2
      gap=2
    elif (( cell * 2 + 1 <= avail )); then
      cols=2
      gap=1
    fi
  fi
  if (( UI_COLS >= 96 && cols == 2 )) && (( cell * 3 + gap * 2 <= avail )); then
    cols=3
  fi
  if (( cols > 1 )); then
    spread=$(( (avail - cell * cols) / (cols - 1) ))
    (( spread > 6 )) && spread=6
    (( spread < 1 )) && spread=1
    gap=$spread
  fi
  UI_MENU_ITEMS=("${items[@]}")
  UI_MENU_COUNT=$n
  UI_MENU_COLS=$cols
  UI_MENU_GAP=$gap
  UI_MENU_NUMW=$numw
  UI_MENU_MAXW=$maxw
  UI_MENU_INDENT=$indent
  UI_MENU_ROWS=$(( (n + cols - 1) / cols ))
  UI_MENU_SELECTED=0
  UI_MENU_ACTIVE=1
}

ui_menu_draw() {
  local selected="${1:--1}" i j idx item num label marker pad cell labelw
  (( UI_MENU_COUNT > 0 )) || return 0
  for (( i = 0; i < UI_MENU_ROWS; i++ )); do
    if (( UI_TTY )); then
      printf '\r\033[2K'
    fi
    for (( j = 0; j < UI_MENU_COLS; j++ )); do
      idx=$(( i * UI_MENU_COLS + j ))
      if (( idx < UI_MENU_COUNT )); then
        item="${UI_MENU_ITEMS[$idx]}"
        num="${item%%|*}"
        label="${item#*|}"
        if (( idx == selected )); then marker='>'; else marker=' '; fi
        if (( UI_MENU_COLS == 1 )); then
          labelw=$(( UI_COLS - UI_MENU_INDENT - 1 - UI_MENU_NUMW - 2 ))
          (( labelw < 1 )) && labelw=1
          label="$(ui_fit "$label" "$labelw")"
          pad=$(( labelw - ${#label} ))
          (( pad < 0 )) && pad=0
          if (( idx == selected )); then
            printf '%*s%s%s%s%*s) %s%s%*s%s' \
              "$UI_MENU_INDENT" '' "$UI_SELECT" "$UI_MAGENTA" "$marker" "$UI_MENU_NUMW" "$num" \
              "$UI_CYAN" "$label" "$pad" '' "$UI_RESET"
          else
            printf '%*s%s%s%*s) %s%s%s%*s' \
              "$UI_MENU_INDENT" '' "$UI_MAGENTA" "$marker" "$UI_MENU_NUMW" "$num" \
              "$UI_WHITE" "$label" "$UI_RESET" "$pad" ''
          fi
        else
          cell=$(( 1 + UI_MENU_NUMW + 2 + UI_MENU_MAXW ))
          label="$(ui_fit "$label" "$UI_MENU_MAXW")"
          pad=$(( UI_MENU_MAXW - ${#label} ))
          (( pad < 0 )) && pad=0
          if (( idx == selected )); then
            printf '%s%s%s%*s) %s%s%*s%s' \
              "$UI_SELECT" "$UI_MAGENTA" "$marker" "$UI_MENU_NUMW" "$num" \
              "$UI_CYAN" "$label" "$pad" '' "$UI_RESET"
          else
            printf '%s%s%*s) %s%s%s%*s' \
              "$UI_MAGENTA" "$marker" "$UI_MENU_NUMW" "$num" \
              "$UI_WHITE" "$label" "$UI_RESET" "$pad" ''
          fi
        fi
      else
        cell=$(( 1 + UI_MENU_NUMW + 2 + UI_MENU_MAXW ))
        printf '%*s' "$cell" ''
      fi
      if (( j < UI_MENU_COLS - 1 )); then
        printf '%*s' "$UI_MENU_GAP" ''
      fi
    done
    printf '\n'
  done
}


ui_center() {
  local text="$1" width="$2" n left right
  n=$(( width - ${#text} ))
  (( n < 0 )) && n=0
  left=$(( n / 2 ))
  right=$(( n - left ))
  printf '%*s%s%*s' "$left" "" "$text" "$right" ""
}

ui_header() {
  local title="${1:-}" width shown fill
  ui_init
  width="$(ui_panel_width)"
  shown="$(ui_fit "$title" $(( width - 8 )))"
  fill=$(( width - ${#shown} - 6 ))
  (( fill < 0 )) && fill=0
  printf '\n'
  printf '  %s+--[ %s%s%s ]%s%s+%s\n' \
    "$UI_BORDER" "$UI_BOLD$UI_CYAN" "$shown" "$UI_BORDER" \
    "$(ui_fill '-' "$fill")" "$UI_BORDER" "$UI_RESET"
}

ui_rule() {
  local width="${1:-}"
  [[ -n "$width" ]] || width="$(ui_panel_width)"
  printf '  %s+%s+%s\n' "$UI_BORDER" "$(ui_fill '=' "$width")" "$UI_RESET"
}

ui_full_row() {
  local left mid right text_color
  left="$(ui_center "$1" 20)"
  mid="$(ui_center "$2" 21)"
  right="$(ui_center "$3" 32)"
  case "$4" in
    bold) text_color="$UI_BOLD$UI_CYAN" ;;
    lime) text_color="$UI_LIME" ;;
    magenta) text_color="$UI_MAGENTA" ;;
    dim) text_color="$UI_DIM" ;;
    *) text_color="$UI_CYAN" ;;
  esac
  printf '  %s%s|%s%s%s%s%s%s%s|%s\n' \
    "$UI_PANEL" "$UI_BORDER" \
    "$UI_CYAN" "$left" \
    "$UI_MAGENTA" "$mid" \
    "$text_color" "$right" \
    "$UI_BORDER" "$UI_RESET"
}

ui_compact_row() {
  local left right text_color
  left="$(ui_center "$1" 12)"
  right="$(ui_center "$2" 34)"
  case "$3" in
    bold) text_color="$UI_BOLD$UI_CYAN" ;;
    lime) text_color="$UI_LIME" ;;
    magenta) text_color="$UI_MAGENTA" ;;
    dim) text_color="$UI_DIM" ;;
    *) text_color="$UI_CYAN" ;;
  esac
  printf '  %s%s|%s%s%s%s%s|%s\n' \
    "$UI_PANEL" "$UI_BORDER" \
    "$UI_CYAN" "$left" \
    "$text_color" "$right" \
    "$UI_BORDER" "$UI_RESET"
}

banner_gradient_line() {
  local line="$1" n=${#1} i ch pos den r g b
  if [[ "$UI_COLOR_MODE" != "24" ]]; then
    local third=$(( n / 3 ))
    (( third < 1 )) && third=1
    printf '%s%s%s%s%s%s%s\n' \
      "$UI_CYAN" "${line:0:third}" \
      "$UI_WHITE" "${line:third:third}" \
      "$UI_ORANGE" "${line:$((third * 2))}" "$UI_RESET"
    return 0
  fi
  den=$(( n > 1 ? n - 1 : 1 ))
  for (( i=0; i<n; i++ )); do
    ch="${line:i:1}"
    if (( i * 2 <= den )); then
      pos=$(( i * 2000 / den ))
      (( pos > 1000 )) && pos=1000
      r=$(( 34 + (255 - 34) * pos / 1000 ))
      g=$(( 211 + (255 - 211) * pos / 1000 ))
      b=$(( 238 + (255 - 238) * pos / 1000 ))
    else
      pos=$(( (i * 2 - den) * 1000 / den ))
      (( pos > 1000 )) && pos=1000
      r=255
      g=$(( 255 + (155 - 255) * pos / 1000 ))
      b=$(( 255 + (53 - 255) * pos / 1000 ))
    fi
    printf '\033[38;2;%d;%d;%dm%s' "$r" "$g" "$b" "$ch"
  done
  printf '%s\n' "$UI_RESET"
}

banner_ascii() {
  if (( UI_COLS < 38 )); then
    printf '  %sNANO PANEL%s  %sv%s%s\n' "$UI_BOLD$UI_CYAN" "$UI_RESET" "$UI_LIME" "$APP_VERSION" "$UI_RESET"
    printf '  %sNanit0x%s\n' "$UI_DIM" "$UI_RESET"
    return 0
  fi
  printf '\n'
  banner_gradient_line '#   #  ###  #   #  ### '
  banner_gradient_line '##  # #   # ##  # #   #'
  banner_gradient_line '# # # ##### # # # #   #'
  banner_gradient_line '#  ## #   # #  ## #   #'
  banner_gradient_line '#   # #   # #   #  ### '
  printf '\n'
  banner_gradient_line '#####  ###  #   # #####  #    #####'
  banner_gradient_line '#     #   # ##  # #      #    #'
  banner_gradient_line '##### ##### # # # ####   #    #### '
  banner_gradient_line '#     #   # #  ## #      #    #'
  banner_gradient_line '#     #   # #   # #####  ##### #####'
  printf '%s v%s  |  Nanit0x%s\n' "$UI_DIM" "$APP_VERSION" "$UI_RESET"
  printf '\n'
}

banner_full() { banner_ascii; }
banner_compact() { banner_ascii; }
banner_mini() { banner_ascii; }
ui_mobile_banner() { banner_ascii; }


title() {
  ui_init
  if (( UI_TTY )); then
    clear 2>/dev/null || true
  fi

  local layout
  if (( UI_COLS < 50 )); then
    layout="mobile"
  elif (( UI_LINES < 12 )); then
    layout="mini"
  elif (( UI_LINES < 22 )); then
    layout="compact"
  elif (( UI_LINES >= 30 && UI_COLS >= UI_BREAK_FULL )); then
    layout="full"
  else
    layout="compact"
  fi

  if (( UI_TTY || ! UI_BANNER_SHOWN || UI_RESIZED )); then
    case "$layout" in
      full) banner_full ;;
      compact) banner_compact ;;
      mini) banner_mini ;;
      mobile) ui_mobile_banner ;;
    esac
    UI_BANNER_SHOWN=1
  fi
  UI_LAST_LAYOUT="$layout"
  UI_RESIZED=0
}

ui_read_done() {
  [[ -t 0 ]] || printf '\n'
}

ui_read_line() {
  local var="$1" rc
  while true; do
    IFS= read -r -t 1 "$var"
    rc=$?
    ui_init
    if (( UI_RESIZED )); then
      UI_RESIZED=0
      return 2
    fi
    if (( rc == 0 )); then
      return 0
    fi
    if (( rc > 128 )); then
      continue
    fi
    return 1
  done
}

pause() {
  local rc
  while true; do
    ui_init
    if (( UI_RESIZED )); then
      UI_RESIZED=0
    fi
    printf '\n'
    ui_prompt "$(t press_enter)"
    ui_read_line _
    rc=$?
    (( rc == 2 )) && continue
    ui_read_done
    return 0
  done
}

ui_menu_select() {
  local choice
  UI_MENU_SELECTED=0
  ui_menu_draw -1
  while true; do
    ui_prompt "$(t choice)"
    if ! IFS= read -r choice; then
      REPLY="0"
      return 0
    fi
    choice="${choice//$'\r'/}"
    choice="${choice#"${choice%%[![:space:]]*}"}"
    choice="${choice%"${choice##*[![:space:]]}"}"
    # Ignore an empty line: a duplicate ENTER must never select an item.
    [[ -n "$choice" ]] && break
  done
  REPLY="$choice"
  return 0
}


ask() {
  local rc
  ui_init
  if (( UI_RESIZED )); then
    UI_RESIZED=0
    printf '\n'
    return 2
  fi
  if (( UI_MENU_ACTIVE )); then
    if (( UI_TTY )) && [[ -t 0 ]] && [[ "${NANO_NO_KEYS:-0}" != "1" ]]; then
      ui_menu_select
      rc=$?
      UI_MENU_ACTIVE=0
      if (( rc == 2 )); then
        printf '\n'
        return 2
      fi
      if (( rc == 0 )); then
        return 0
      fi
      ui_menu_draw -1
    else
      ui_menu_draw -1
      UI_MENU_ACTIVE=0
    fi
  fi
  ui_prompt "$(t choice)"
  ui_read_line REPLY
  rc=$?
  if (( rc == 2 )); then
    printf '\n'
    return 2
  fi
  (( rc == 1 )) && REPLY="0"
  ui_read_done
  return 0
}

confirm() {
  local answer rc
  [[ "${NANO_ASSUME_YES:-0}" == "1" ]] && return 0
  while true; do
    ui_init
    if (( UI_RESIZED )); then
      UI_RESIZED=0
    fi
    ui_prompt "$1 $(t confirm_hint)"
    ui_read_line answer
    rc=$?
    (( rc == 2 )) && continue
    ui_read_done
    case "$answer" in
      y|Y|s|S|o|O) return 0 ;;
      *) return 1 ;;
    esac
  done
}

have() { command -v "$1" >/dev/null 2>&1; }
is_root() { [[ "${EUID:-$(id -u)}" -eq 0 ]]; }


NANO_ORIGINAL_ARGS=()

root_relaunch() {
  if is_root; then
    say root_already
    pause
    return 0
  fi
  if ! have sudo; then
    say root_no_sudo
    pause
    return 1
  fi
  say root_relaunch_note
  if ! confirm "$(t root_relaunch_confirm)"; then
    say cancelled
    return 1
  fi
  if ! sudo -n -E true; then
    say root_sudo_failed
    pause
    return 1
  fi
  exec sudo -n -E -- "${BASH:-/bin/bash}" "$0" "${NANO_ORIGINAL_ARGS[@]}"
  say root_sudo_failed
  pause
  return 1
}

detect_lang() {
  case "${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}" in
    en*) printf 'en' ;;
    pt*) printf 'pt' ;;
    fr*) printf 'fr' ;;
    *) printf 'es' ;;
  esac
}

load_language() {
  local saved=""
  if [[ -r "$LANGUAGE_FILE" ]]; then
    IFS= read -r saved < "$LANGUAGE_FILE" || saved=""
    case "$saved" in
      es|en|pt|fr) LANGUAGE="$saved" ;;
    esac
  fi
}

save_language() {
  if mkdir -p -- "$CONFIG_DIR" 2>/dev/null &&
     printf '%s\n' "$LANGUAGE" > "$LANGUAGE_FILE" 2>/dev/null; then
    chmod 600 "$LANGUAGE_FILE" 2>/dev/null || true
    return 0
  fi
  say language_save_fail
  return 1
}

choose_language() {
  local current_name
  while true; do
    case "$LANGUAGE" in
      es) current_name="Español" ;;
      en) current_name="English" ;;
      pt) current_name="Português" ;;
      fr) current_name="Français" ;;
      *) current_name="$LANGUAGE" ;;
    esac
    title
    ui_header "$(t language_title)"
    sayf language_current "$current_name"
    ui_menu "1|Español" "2|English" "3|Português" "4|Français" "0|$(t language_cancel)"
    ask || continue
    case "$REPLY" in
      1) LANGUAGE=es ;;
      2) LANGUAGE=en ;;
      3) LANGUAGE=pt ;;
      4) LANGUAGE=fr ;;
      0) return 1 ;;
      *) say invalid; sleep 1; continue ;;
    esac
    save_language
    say language_set
    sleep 1
    return 0
  done
}

expand_path() {
  local path="$1"
  case "$path" in
    "~") printf '%s' "${HOME:-/tmp}" ;;
    "~/"*) printf '%s/%s' "${HOME:-/tmp}" "${path#\~/}" ;;
    *) printf '%s' "$path" ;;
  esac
}

abspath() {
  local path="$1"
  if have realpath; then
    realpath -- "$path" 2>/dev/null && return 0
  fi
  if have readlink; then
    readlink -f -- "$path" 2>/dev/null && return 0
  fi
  printf '%s' "$path"
}

valid_username() {
  [[ "$1" =~ ^[a-z_][a-z0-9_-]{0,31}$ ]]
}

valid_service_name() {
  [[ "$1" =~ ^[A-Za-z0-9_.@:-]+$ ]]
}

print_diag() {
  local env_name os_name kernel arch host uptime_str dt root_state shell_str cpu cores load pm_name
  local dns route ssh_state tools c

  if (( IS_TERMUX )); then
    env_name="$(t env_termux)"
  else
    env_name="$(t env_linux)"
  fi
  sayf diag_env "$env_name"

  if [[ -r /etc/os-release ]]; then
    os_name="$(. /etc/os-release 2>/dev/null; printf '%s' "${PRETTY_NAME:-Linux}")"
  elif (( IS_TERMUX )); then
    os_name="Android / Termux"
  else
    os_name="$(uname -s 2>/dev/null || true)"
  fi
  [[ -n "$os_name" ]] || os_name="$(t diag_os_unknown)"
  sayf diag_os "$os_name"

  kernel="$(uname -r 2>/dev/null || true)"
  arch="$(uname -m 2>/dev/null || true)"
  host="$(uname -n 2>/dev/null || true)"
  sayf diag_kernel "${kernel:-$(t unknown)}"
  sayf diag_arch "${arch:-$(t unknown)}"
  sayf diag_host "${host:-$(t unknown)}"

  uptime_str="$(uptime -p 2>/dev/null || uptime 2>/dev/null || true)"
  uptime_str="${uptime_str#up }"
  sayf diag_uptime "${uptime_str:-$(t unknown)}"
  dt="$(date '+%Y-%m-%d %H:%M:%S %Z' 2>/dev/null || true)"
  sayf diag_datetime "${dt:-$(t unknown)}"
  sayf diag_user "$(id -un 2>/dev/null || t unknown)"
  if is_root; then root_state="$(t yes)"; else root_state="$(t no)"; fi
  sayf diag_root "$root_state"
  local _shell_info; _shell_info="${SHELL:-unknown}"; shell_str="${_shell_info} bash-${BASH_VERSION:-?}"
  sayf diag_shell "$shell_str"

  say compat_title
  sayf compat_bash "$NANO_MIN_BASH" "${BASH_VERSION:-$(t unknown)}"
  pm_name="$(detect_pm)"
  [[ -n "$pm_name" ]] || pm_name="$(t not_detected)"
  sayf compat_pm "$pm_name"
  if systemd_available; then
    sayf compat_systemd "$(t yes)"
  else
    sayf compat_systemd "$(t no)"
  fi
  sayf compat_verdict "$(compat_verdict_text)"
  sayf compat_min "$NANO_MIN_BASH" "$NANO_MIN_SYSTEMD"

  cpu="$(awk -F: '/^[[:space:]]*(model name|Hardware|Processor)/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $2); if ($2 != "") {print $2; exit}}' /proc/cpuinfo 2>/dev/null)"
  [[ -n "$cpu" ]] || cpu="$(uname -m 2>/dev/null || true)"
  sayf diag_cpu "${cpu:-$(t unknown)}"

  cores="$(getconf _NPROCESSORS_ONLN 2>/dev/null || nproc 2>/dev/null || true)"
  sayf diag_cores "${cores:-$(t unknown)}"
  load="$(awk '{print $1", "$2", "$3}' /proc/loadavg 2>/dev/null || true)"
  if [[ -z "$load" ]]; then
    load="$(uptime 2>/dev/null | sed -n 's/.*load average[s]*:[[:space:]]*//p')"
  fi
  sayf diag_load "${load:-$(t unknown)}"

  say diag_memory
  if have free; then
    free -h 2>/dev/null | sed 's/^/  /' | ui_fold
  elif [[ -r /proc/meminfo ]]; then
    sed -n '1,3p' /proc/meminfo 2>/dev/null | sed 's/^/  /' | ui_fold
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_swap
  if have free; then
    free -h 2>/dev/null | awk 'NR == 1 || $1 == "Swap:" {print "  " $0}' | ui_fold
  elif [[ -r /proc/meminfo ]]; then
    awk '/^(SwapTotal|SwapFree):/ {print "  " $0}' /proc/meminfo 2>/dev/null | ui_fold
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_disk
  if have df; then
    df -h "${HOME:-/}" 2>/dev/null | sed 's/^/  /' | ui_fold || printf '  %s\n' "$(t diag_no_data)"
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_inodes
  if have df; then
    df -i "${HOME:-/}" 2>/dev/null | sed 's/^/  /' | ui_fold || printf '  %s\n' "$(t diag_no_data)"
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_net
  say diag_ip
  local net_out=""
  if have ip; then
    net_out="$(ip -brief address 2>/dev/null || true)"
  elif have ifconfig; then
    net_out="$(ifconfig 2>/dev/null | sed -n '1,20p' || true)"
  fi
  if [[ -n "$net_out" ]]; then
    printf '%s\n' "$net_out" | sed 's/^/  /' | ui_fold
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_route
  route=""
  if have ip; then
    route="$(ip route show default 2>/dev/null || true)"
  elif have route; then
    route="$(route -n 2>/dev/null | awk 'NR == 1 || $2 == "0.0.0.0"' || true)"
  fi
  if [[ -n "$route" ]]; then
    printf '%s\n' "$route" | sed 's/^/  /' | ui_fold
  else
    printf '  %s\n' "$(t diag_no_data)"
  fi

  say diag_dns
  dns="$(awk '/^[[:space:]]*nameserver[[:space:]]/ {print $2}' /etc/resolv.conf 2>/dev/null | tr '\n' ' ' | sed 's/[[:space:]]*$//')"
  printf '  %s\n' "${dns:-$(t diag_no_data)}"

  if have systemctl; then
    if systemctl is-active --quiet ssh 2>/dev/null || systemctl is-active --quiet sshd 2>/dev/null; then
      ssh_state="$(t diag_active)"
    else
      ssh_state="$(t diag_inactive)"
    fi
  elif have pgrep; then
    if pgrep -x sshd >/dev/null 2>&1; then ssh_state="$(t diag_active)"; else ssh_state="$(t diag_inactive)"; fi
  elif have ps; then
    if ps -A 2>/dev/null | grep -q '[s]shd'; then ssh_state="$(t diag_active)"; else ssh_state="$(t diag_inactive)"; fi
  else
    ssh_state="$(t unknown)"
  fi
  sayf diag_ssh "$ssh_state"

  tools=""
  for c in ss netstat ip ifconfig lsof dig ping curl wget git tar gzip nano htop ssh systemctl ufw firewall-cmd; do
    have "$c" && tools+="$c "
  done
  tools="${tools% }"
  sayf diag_tools "${tools:-$(t none)}"
}

system_summary() {
  local report dir file
  title
  ui_header "$(t diag_title)"
  report="$(print_diag)"
  printf '%s\n' "$report" | ui_fold

  if confirm "$(t diag_save_q)"; then
    dir="${XDG_DATA_HOME:-${HOME:-/tmp}/.local/share}/nanoscript/reports"
    file="$dir/diagnostico-$(date +%Y%m%d-%H%M%S).txt"
    if mkdir -p -- "$dir" 2>/dev/null && printf '%s\n' "$report" > "$file" 2>/dev/null; then
      chmod 600 "$file" 2>/dev/null || true
      sayf diag_saved "$file"
    else
      say diag_save_fail
    fi
  fi
  pause
}

show_listening() {
  local out=""
  if have ss; then
    out="$(ss -lntup 2>&1 || ss -lntu 2>&1 || true)"
  elif have netstat; then
    out="$(netstat -lntup 2>&1 || netstat -lntu 2>&1 || true)"
  elif have lsof; then
    out="$(lsof -nP -iTCP -sTCP:LISTEN 2>&1 || true)"
  else
    say ports_tool_missing
    return 1
  fi
  if printf '%s\n' "$out" | grep -qE 'LISTEN|UNCONN'; then
    printf '%s\n' "$out" | grep -vE '^(Cannot open|Netid|Active Internet|Proto |[[:space:]]*$)' | sed 's/^/  /' | ui_fold
  else
    say ports_empty
  fi
}

ports_menu() {
  local port matches
  while true; do
    title
    ui_header "$(t ports_title)"
    ui_menu "1|$(t ports_list)" "2|$(t ports_search)" \
      "3|$(t ports_firewall)" "4|$(t ports_planner)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1)
        say ports_listening
        line
        show_listening || true
        say ports_note
        pause
        ;;
      2)
        ui_prompt "$(t ports_search_prompt)"
        IFS= read -r port || port=""
        if [[ ! "$port" =~ ^[0-9]+$ ]] || (( port < 1 || port > 65535 )); then
          say ports_invalid_port
          pause
          continue
        fi
        matches=""
        if have ss; then
          matches="$(ss -lntup 2>/dev/null | grep -E "[:.]${port}([[:space:]]|$)" || true)"
        elif have netstat; then
          matches="$(netstat -lntup 2>/dev/null | grep -E "[:.]${port}([[:space:]]|$)" || true)"
        elif have lsof; then
          matches="$(lsof -nP -iTCP:"$port" -sTCP:LISTEN 2>/dev/null || true)"
        else
          say ports_tool_missing
          pause
          continue
        fi
        if [[ -n "$matches" ]]; then
          printf '%s\n' "$matches" | ui_fold
        else
          say ports_no_matches
        fi
        pause
        ;;
      4) port_planner ;;
      3)
        ui_header "$(t ports_fw_title)"
        local found=0
        if have ufw; then
          found=1
          printf 'ufw:\n'
          ufw status verbose 2>&1 | sed 's/^/  /' | ui_fold
        fi
        if have firewall-cmd; then
          found=1
          printf 'firewalld:\n'
          firewall-cmd --state 2>&1 | sed 's/^/  /' | ui_fold
          firewall-cmd --list-all 2>&1 | sed 's/^/  /' | ui_fold
        fi
        if have nft; then
          found=1
          printf 'nftables:\n'
          nft list ruleset 2>&1 | head -n 40 | sed 's/^/  /' | ui_fold
        fi
        (( found )) || say ports_fw_none
        say ports_fw_readonly
        pause
        ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

systemd_available() {
  local version
  have systemctl || return 1
  [[ -d /run/systemd/system ]] || return 1
  version="$(systemctl --version 2>/dev/null | awk 'NR == 1 {print $2}')"
  [[ "$version" =~ ^[0-9]+$ ]] && (( version >= NANO_MIN_SYSTEMD ))
}

show_processes() {
  say services_processes
  if have ps; then
    if (( IS_TERMUX )); then
      ps -A 2>/dev/null | head -n 40 | sed 's/^/  /' | ui_fold
    else
      ps aux 2>/dev/null | head -n 40 | sed 's/^/  /' | ui_fold
    fi
  else
    say diag_no_data
  fi
}

services_menu() {
  local svc out action label
  while true; do
    title
    ui_header "$(t services_title)"
    ui_menu "1|$(t services_running)" "2|$(t services_failed)" \
      "3|$(t services_detail)" "4|$(t services_manage)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1)
        if systemd_available; then
          say services_running
          line
          out="$(systemctl --no-pager list-units --type=service --state=running --no-legend 2>/dev/null || true)"
          if [[ -n "$out" ]]; then printf '%s\n' "$out" | head -n 60 | sed 's/^/  /' | ui_fold; else say services_none; fi
        else
          say services_no_systemd
          show_processes
        fi
        pause
        ;;
      2)
        if systemd_available; then
          say services_failed
          line
          out="$(systemctl --no-pager --failed --no-legend 2>/dev/null || true)"
          if [[ -n "$out" ]]; then printf '%s\n' "$out" | head -n 60 | sed 's/^/  /' | ui_fold; else say services_none; fi
        else
          say services_no_systemd
          show_processes
        fi
        pause
        ;;
      3)
        if ! systemd_available; then
          say services_no_systemd
          show_processes
          pause
          continue
        fi
        ui_prompt "$(t services_enter)"
        IFS= read -r svc || svc=""
        if ! valid_service_name "$svc"; then
          say services_invalid_name
          pause
          continue
        fi
        say services_status
        line
        systemctl --no-pager status "$svc" 2>&1 | head -n 40 | sed 's/^/  /' | ui_fold
        if have journalctl; then
          say services_logs
          journalctl -u "$svc" -n 30 --no-pager 2>&1 | tail -n 30 | sed 's/^/  /' | ui_fold
        else
          say services_no_logs
        fi
        pause
        ;;
      4)
        if ! systemd_available; then
          say services_no_systemd
          pause
          continue
        fi
        if ! is_root; then
          say services_manage_root
          pause
          continue
        fi
        ui_prompt "$(t services_enter)"
        IFS= read -r svc || svc=""
        if ! valid_service_name "$svc"; then
          say services_invalid_name
          pause
          continue
        fi
        ui_header "$(t services_manage_title)"
        ui_menu "1|$(t services_action_start)" "2|$(t services_action_stop)" \
          "3|$(t services_action_restart)" "0|$(t back)"
        ask || continue
        case "$REPLY" in
          1) action="start"; label="$(t services_action_start)" ;;
          2) action="stop"; label="$(t services_action_stop)" ;;
          3) action="restart"; label="$(t services_action_restart)" ;;
          0) continue ;;
          *) say invalid; sleep 1; continue ;;
        esac
        if confirm "$(printf "$(t services_confirm_action)" "$label" "$svc")"; then
          if systemctl "$action" "$svc" 2>&1; then
            say services_action_done
          else
            say services_action_failed
          fi
        else
          say cancelled
        fi
        pause
        ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

list_human_users() {
  local u _ uid gid _ home shell groups keys auth found=0 shellw=0
  ui_init
  if (( UI_COLS >= 70 )); then
    shellw=$(( UI_COLS - 53 ))
    (( shellw < 6 )) && shellw=6
    printf '%-20s %-8s %-22s %s\n' \
      "$(ui_fit "$(t ssh_col_user)" 20)" "$(ui_fit "$(t ssh_col_uid)" 8)" \
      "$(ui_fit "$(t ssh_col_home)" 22)" "$(t ssh_col_shell)"
  fi
  if [[ ! -r /etc/passwd ]]; then
    say ssh_no_users
    return
  fi
  while IFS=: read -r u _ uid gid _ home shell; do
    [[ "$uid" =~ ^[0-9]+$ ]] || continue
    (( uid >= 1000 && uid < 60000 )) || continue
    found=1
    groups="$(id -nG "$u" 2>/dev/null || true)"
    auth="$home/.ssh/authorized_keys"
    keys=0
    if [[ -r "$auth" ]]; then
      keys="$(awk 'NF && $1 !~ /^#/ {n++} END {print n+0}' "$auth" 2>/dev/null || printf '0')"
    fi
    if (( UI_COLS >= 70 )); then
      printf '%-20s %-8s %-22s %s\n' \
        "$(ui_fit "$u" 20)" "$(ui_fit "$uid" 8)" \
        "$(ui_fit "${home:-?}" 22)" "$(ui_fit "${shell:-?}" "$shellw")"
    else
      ui_text "$(t ssh_col_user): $u" "  "
      ui_text "$(t ssh_col_uid): $uid" "  "
      ui_text "$(t ssh_col_home): ${home:-?}" "  "
      ui_text "$(t ssh_col_shell): ${shell:-?}" "  "
    fi
    ui_text "$(printf "$(t ssh_groups)" "${groups:-$(t none)}")" "  "
    ui_text "$(printf "$(t ssh_keys)" "$keys")" "  "
    (( UI_COLS < 70 )) && printf '\n'
  done < /etc/passwd
  (( found )) || say ssh_no_users
}

ssh_add_key_for() {
  local user="$1" home group key type auth
  home="$(getent passwd "$user" 2>/dev/null | cut -d: -f6)"
  if [[ -z "$home" || ! -d "$home" ]]; then
    say ssh_not_exists
    return 1
  fi
  group="$(id -gn "$user" 2>/dev/null || true)"
  ui_prompt "$(t ssh_key_prompt)"
  IFS= read -r key || key=""
  type="${key%% *}"
  case "$type" in
    ssh-rsa|ssh-ed25519|ssh-dss|ecdsa-sha2-nistp256|ecdsa-sha2-nistp384|ecdsa-sha2-nistp521|sk-ssh-ed25519@openssh.com|sk-ecdsa-sha2-nistp256@openssh.com) ;;
    *) say ssh_key_bad; return 1 ;;
  esac
  if [[ "$key" != *" "* ]]; then
    say ssh_key_bad
    return 1
  fi
  if ! confirm "$(printf "$(t ssh_key_confirm)" "$user")"; then
    say cancelled
    return 1
  fi
  auth="$home/.ssh/authorized_keys"
  if ! mkdir -p -- "$home/.ssh" 2>/dev/null; then
    say ssh_key_fail
    return 1
  fi
  chmod 700 "$home/.ssh" 2>/dev/null || true
  touch "$auth" 2>/dev/null || true
  chmod 600 "$auth" 2>/dev/null || true
  if [[ -n "$group" ]]; then
    chown "$user:$group" "$home/.ssh" "$auth" 2>/dev/null || true
  else
    chown "$user" "$home/.ssh" "$auth" 2>/dev/null || true
  fi
  if grep -Fqx -- "$key" "$auth" 2>/dev/null; then
    say ssh_key_exists
    return 0
  fi
  if printf '%s\n' "$key" >> "$auth" 2>/dev/null; then
    sayf ssh_key_added "$user"
  else
    say ssh_key_fail
    return 1
  fi
}

ssh_create_user() {
  local username shell
  say ssh_create_info
  ui_prompt "$(t ssh_name_prompt)"
  IFS= read -r username || username=""
  if ! valid_username "$username"; then say ssh_bad_name; return; fi
  if getent passwd "$username" >/dev/null 2>&1; then say ssh_exists; return; fi
  if ! confirm "$(printf "$(t ssh_confirm_create)" "$username")"; then say cancelled; return; fi
  if [[ -x /bin/bash ]]; then shell="/bin/bash"; else shell="/bin/sh"; fi
  if useradd -m -s "$shell" "$username"; then
    sayf ssh_created "$username"
    if confirm "$(t ssh_set_password)"; then
      if passwd "$username"; then say ssh_password_done; else say ssh_password_fail; fi
    fi
    if confirm "$(t ssh_add_key_now)"; then
      ssh_add_key_for "$username" || true
    fi
  else
    say ssh_create_fail
  fi
}

ssh_delete_user() {
  local target uid remove_home=0
  ui_prompt "$(t ssh_delete_prompt)"
  IFS= read -r target || target=""
  if ! valid_username "$target"; then say ssh_protected; return; fi
  if [[ "$target" == "$(id -un 2>/dev/null)" ]]; then say ssh_current; return; fi
  if ! getent passwd "$target" >/dev/null 2>&1; then say ssh_not_exists; return; fi
  uid="$(id -u "$target" 2>/dev/null || true)"
  if [[ -z "$uid" || "$uid" -lt 1000 || "$uid" -ge 60000 ]]; then say ssh_protected; return; fi
  say ssh_delete_info
  if confirm "$(t ssh_delete_home)"; then remove_home=1; fi
  if ! confirm "$(printf "$(t ssh_confirm_delete)" "$target")"; then say cancelled; return; fi
  if (( remove_home )); then userdel -r "$target"; else userdel "$target"; fi
  if getent passwd "$target" >/dev/null 2>&1; then
    say ssh_delete_fail
  else
    sayf ssh_deleted "$target"
  fi
}

ssh_lock_user() {
  local target uid
  ui_prompt "$(t ssh_lock_prompt)"
  IFS= read -r target || target=""
  if ! valid_username "$target"; then say ssh_protected; return; fi
  if [[ "$target" == "$(id -un 2>/dev/null)" ]]; then say ssh_current; return; fi
  if ! getent passwd "$target" >/dev/null 2>&1; then say ssh_not_exists; return; fi
  uid="$(id -u "$target" 2>/dev/null || true)"
  if [[ -z "$uid" || "$uid" -lt 1000 || "$uid" -ge 60000 ]]; then say ssh_protected; return; fi
  say ssh_lock_action
  ask || return 1
  case "$REPLY" in
    1)
      if confirm "$(printf "$(t ssh_confirm_lock)" "$target")"; then
        if usermod -L "$target"; then sayf ssh_locked "$target"; say ssh_lock_note; else say ssh_lock_fail; fi
      else
        say cancelled
      fi
      ;;
    2)
      if confirm "$(printf "$(t ssh_confirm_unlock)" "$target")"; then
        if usermod -U "$target"; then sayf ssh_unlocked "$target"; else say ssh_lock_fail; fi
      else
        say cancelled
      fi
      ;;
    0) return ;;
    *) say invalid ;;
  esac
}

ssh_show_config() {
  local cfg="/etc/ssh/sshd_config" out
  if (( IS_TERMUX )); then cfg="${PREFIX:-}/etc/ssh/sshd_config"; fi
  ui_header "$(t ssh_config_title)"
  if [[ ! -r "$cfg" ]]; then say ssh_config_missing; return; fi
  out="$(grep -E '^[[:space:]]*(Port|PermitRootLogin|PasswordAuthentication|PubkeyAuthentication|AllowUsers|AllowGroups|MaxAuthTries|LoginGraceTime)[[:space:]]' "$cfg" 2>/dev/null || true)"
  if [[ -n "$out" ]]; then printf '%s\n' "$out" | sed 's/^/  /' | ui_fold; else say ssh_config_defaults; fi
  say ssh_config_note
}

ssh_users_menu() {
  if (( IS_TERMUX )); then
    title
    ui_header "$(t ssh_title)"
    say ssh_termux
    pause
    return
  fi
  while true; do
    title
    ui_header "$(t ssh_title)"
    ui_menu "1|$(t ssh_list)" "2|$(t ssh_create)" "3|$(t ssh_delete)" \
      "4|$(t ssh_lock)" "5|$(t ssh_key)" "6|$(t ssh_config)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) ui_header "$(t ssh_list_title)"; list_human_users; pause ;;
      2)
        if ! is_root; then say ssh_root; pause; continue; fi
        if ! have useradd || ! have passwd || ! have getent; then say ssh_tools; pause; continue; fi
        ssh_create_user; pause
        ;;
      3)
        if ! is_root; then say ssh_root; pause; continue; fi
        if ! have userdel || ! have getent; then say ssh_tools; pause; continue; fi
        ssh_delete_user; pause
        ;;
      4)
        if ! is_root; then say ssh_root; pause; continue; fi
        if ! have usermod || ! have getent; then say ssh_tools; pause; continue; fi
        ssh_lock_user; pause
        ;;
      5)
        if ! is_root; then say ssh_root; pause; continue; fi
        if ! have getent; then say ssh_tools; pause; continue; fi
        ui_prompt "$(t ssh_key_user)"
        IFS= read -r target || target=""
        if ! valid_username "$target"; then say ssh_protected; pause; continue; fi
        if ! getent passwd "$target" >/dev/null 2>&1; then say ssh_not_exists; pause; continue; fi
        ssh_add_key_for "$target"; pause
        ;;
      6) ssh_show_config; pause ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

verify_backup() {
  local file="$1" manifest
  if [[ ! -f "$file" || "$file" != *.tar.gz ]]; then
    say backup_pick_invalid
    return 1
  fi
  if ! tar -tzf "$file" >/dev/null 2>&1; then
    say backup_verify_fail
    return 1
  fi
  say backup_verified
  manifest="${file}.sha256"
  if [[ -f "$manifest" ]] && have sha256sum; then
    if (cd "$(dirname "$file")" && sha256sum -c "$(basename "$manifest")" >/dev/null 2>&1); then
      say backup_checksum_ok
    else
      say backup_checksum_fail
      return 1
    fi
  else
    say backup_no_checksum
  fi
  return 0
}

backup_create() {
  local source dest default base stamp output
  default="${HOME:-/tmp}/nanoscript-backups"
  ui_prompt "$(t backup_source)"
  IFS= read -r source || source=""
  source="$(expand_path "$source")"
  if [[ -z "$source" ]]; then say cancelled; return; fi
  while [[ "$source" == */ && "$source" != "/" ]]; do source="${source%/}"; done
  case "$source" in
    /|/proc|/sys|/dev) say backup_src_forbidden; return ;;
  esac
  if [[ ! -e "$source" || ! -r "$source" ]]; then say backup_src_missing; return; fi
  source="$(abspath "$source")"
  say backup_readonly_note

  ui_prompt "$(printf '%s [%s]:' "$(t backup_dest)" "$default")"
  IFS= read -r dest || dest=""
  dest="$(expand_path "$dest")"
  [[ -n "$dest" ]] || dest="$default"
  if [[ -e "$dest" && ! -d "$dest" ]]; then say backup_dest_missing; return; fi
  if [[ ! -d "$dest" ]]; then
    if ! confirm "$(t backup_create_dest)"; then say cancelled; return; fi
    if mkdir -p -- "$dest" 2>/dev/null; then
      sayf backup_dest_created "$dest"
    else
      say backup_dest_fail
      return
    fi
  fi

  base="$(basename "$source")"
  base="$(printf '%s' "$base" | tr -c 'A-Za-z0-9._-' '_')"
  [[ -n "$base" ]] || base="backup"
  stamp="$(date +%Y%m%d-%H%M%S)"
  output="${dest%/}/${base}-${stamp}.tar.gz"
  while [[ -e "$output" ]]; do
    output="${dest%/}/${base}-${stamp}-$RANDOM.tar.gz"
  done

  if ! confirm "$(printf "$(t backup_confirm)" "$source" "$output")"; then say cancelled; return; fi
  if tar -czf "$output" -C "$(dirname "$source")" "$base" 2>/dev/null; then
    chmod 600 "$output" 2>/dev/null || true
    sayf backup_created "$output"
    sayf backup_size "$(du -h "$output" 2>/dev/null | awk '{print $1}')"
    if have sha256sum; then
      (cd "$dest" && sha256sum "$(basename "$output")" > "$(basename "$output").sha256" 2>/dev/null) || true
      chmod 600 "${output}.sha256" 2>/dev/null || true
    fi
  else
    say backup_failed
    rm -f -- "$output" 2>/dev/null || true
  fi
}

backup_list() {
  local dest default f
  ui_init
  default="${HOME:-/tmp}/nanoscript-backups"
  ui_prompt "$(printf '%s [%s]:' "$(t backup_dest)" "$default")"
  IFS= read -r dest || dest=""
  dest="$(expand_path "$dest")"
  [[ -n "$dest" ]] || dest="$default"
  if [[ ! -d "$dest" ]]; then say backup_dest_missing; return; fi
  sayf backup_list_title "$dest"
  line
  local -a files=()
  shopt -s nullglob
  files=("$dest"/*.tar.gz)
  shopt -u nullglob
  if (( ${#files[@]} == 0 )); then say backup_none; return; fi
  for f in "${files[@]}"; do
    local fdate fsize
    fdate="$(date -r "$f" '+%Y-%m-%d %H:%M' 2>/dev/null || printf '?')"
    fsize="$(du -h "$f" 2>/dev/null | awk '{print $1}')"
    if (( UI_COLS >= 60 )); then
      printf '  %s  %8s  %s\n' "$fdate" "$fsize" "$f" | ui_fold
    elif (( UI_COLS >= 40 )); then
      printf '  %s  %8s\n' "$fdate" "$fsize"
      ui_text "$f" "    "
    else
      ui_text "$fdate" "  "
      ui_text "$fsize" "  "
      ui_text "$f" "    "
    fi
  done
}

backup_verify_action() {
  local file
  ui_prompt "$(t backup_pick)"
  IFS= read -r file || file=""
  file="$(expand_path "$file")"
  verify_backup "$file"
}

backup_restore() {
  local file target default
  ui_prompt "$(t backup_pick)"
  IFS= read -r file || file=""
  file="$(expand_path "$file")"
  verify_backup "$file" || return
  if tar -tzf "$file" 2>/dev/null | grep -Eq '(^/|(^|/)\.\.(/|$))'; then
    say backup_unsafe
    return
  fi
  default="${HOME:-/tmp}/nanoscript-restore-$(date +%Y%m%d-%H%M%S)"
  while [[ -e "$default" ]]; do default="${default}-$RANDOM"; done
  ui_prompt "$(printf '%s [%s]:' "$(t backup_restore_target)" "$default")"
  IFS= read -r target || target=""
  target="$(expand_path "$target")"
  [[ -n "$target" ]] || target="$default"
  case "$target" in
    /|/proc|/sys|/dev) say backup_target_forbidden; return ;;
  esac
  if [[ -e "$target" && ! -d "$target" ]]; then say backup_dest_missing; return; fi
  if [[ -d "$target" && -n "$(ls -A "$target" 2>/dev/null)" ]]; then
    say backup_target_notempty
    if ! confirm "$(t backup_restore_overwrite)"; then say cancelled; return; fi
  fi
  if ! confirm "$(printf "$(t backup_restore_confirm)" "$target")"; then say cancelled; return; fi
  if ! mkdir -p -- "$target" 2>/dev/null; then say backup_dest_fail; return; fi
  if tar -xzf "$file" -C "$target" 2>/dev/null; then
    sayf backup_restored "$target"
  else
    say backup_restore_fail
  fi
}

backup_delete() {
  local file
  ui_prompt "$(t backup_pick)"
  IFS= read -r file || file=""
  file="$(expand_path "$file")"
  if [[ ! -f "$file" || "$file" != *.tar.gz ]]; then say backup_pick_invalid; return; fi
  if ! confirm "$(printf "$(t backup_delete_confirm)" "$file")"; then say cancelled; return; fi
  if rm -f -- "$file" "${file}.sha256" 2>/dev/null; then
    sayf backup_deleted "$file"
  else
    say backup_delete_fail
  fi
}

backup_menu() {
  while true; do
    title
    ui_header "$(t backup_title)"
    ui_menu "1|$(t backup_create)" "2|$(t backup_list)" "3|$(t backup_verify)" \
      "4|$(t backup_restore)" "5|$(t backup_delete)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) backup_create; pause ;;
      2) backup_list; pause ;;
      3) backup_verify_action; pause ;;
      4) backup_restore; pause ;;
      5) backup_delete; pause ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

detect_pm() {
  if (( IS_TERMUX )); then
    printf 'pkg'
  elif have apt-get; then
    printf 'apt'
  elif have dnf; then
    printf 'dnf'
  elif have yum; then
    printf 'yum'
  elif have pacman; then
    printf 'pacman'
  elif have zypper; then
    printf 'zypper'
  elif have apk; then
    printf 'apk'
  fi
}

pm_map_package() {
  local pm="$1" pkg="$2"
  case "$pm:$pkg" in
    pacman:python3) printf 'python' ;;
    pacman:openssh-server) printf 'openssh' ;;
    pacman:stunnel4) printf 'stunnel' ;;
    apt:dropbear) printf 'dropbear-bin' ;;
    dnf:stunnel4|yum:stunnel4) printf 'stunnel' ;;
    zypper:openssh-server) printf 'openssh' ;;
    zypper:stunnel4) printf 'stunnel' ;;
    apk:openssh-server) printf 'openssh' ;;
    apk:stunnel4) printf 'stunnel' ;;
    dnf:procps|yum:procps) printf 'procps-ng' ;;
    pacman:procps) printf 'procps-ng' ;;
    apk:procps) printf 'procps' ;;
    zypper:procps) printf 'procps' ;;
    dnf:iproute2|yum:iproute2) printf 'iproute' ;;
    dnf:openssh-server|yum:openssh-server) printf 'openssh-server' ;;
    *) printf '%s' "$pkg" ;;
  esac
}

pm_refresh_metadata() {
  local pm="${1:-$(detect_pm)}"
  local -a cmd=()
  [[ -n "$pm" ]] || return 1
  [[ "${NANO_PM_REFRESHED:-0}" == "1" ]] && return 0

  case "$pm" in
    apt) cmd=(apt-get update) ;;
    dnf) cmd=(dnf -y makecache) ;;
    yum) cmd=(yum -y makecache) ;;
    pacman) NANO_PM_REFRESHED=1; return 0 ;;
    zypper) cmd=(zypper --non-interactive refresh) ;;
    apk) cmd=(apk update) ;;
    pkg) cmd=(pkg update -y) ;;
    *) return 1 ;;
  esac

  if ! (( IS_TERMUX )) && ! is_root; then
    if have sudo; then
      cmd=(sudo "${cmd[@]}")
    else
      return 1
    fi
  fi

  say install_refreshing
  if "${cmd[@]}" >/dev/null 2>&1; then
    NANO_PM_REFRESHED=1
  else
    NANO_PM_REFRESHED=1
    say install_refresh_fail
  fi
  return 0
}

compat_verdict_text() {
  if (( IS_TERMUX )); then
    t compat_panel
    return
  fi
  if [[ "$(uname -s 2>/dev/null)" != "Linux" ]]; then
    t compat_no
    return
  fi
  if (( BASH_VERSINFO[0] < 4 )); then
    t compat_no
    return
  fi
  if [[ -z "$(detect_pm)" ]]; then
    t compat_panel
    return
  fi
  if systemd_available && is_root; then
    t compat_ok
  else
    t compat_panel
  fi
}

pm_group_packages() {
  local pm="$1" group="$2"
  case "$pm:$group" in
    apt:basic|dnf:basic|yum:basic|pacman:basic|zypper:basic|apk:basic|pkg:basic)
      echo "curl wget git tar gzip nano" ;;
    apt:network) echo "iproute2 net-tools dnsutils lsof iputils-ping" ;;
    dnf:network|yum:network) echo "iproute net-tools bind-utils lsof iputils" ;;
    pacman:network) echo "iproute2 net-tools bind lsof iputils" ;;
    zypper:network) echo "iproute2 net-tools bind-utils lsof iputils" ;;
    apk:network) echo "iproute2 net-tools bind-tools lsof iputils" ;;
    pkg:network) echo "iproute2 net-tools dnsutils lsof iputils" ;;
    apt:ssh) echo "openssh-client openssh-server" ;;
    dnf:ssh|yum:ssh) echo "openssh-clients openssh-server" ;;
    pacman:ssh|zypper:ssh|apk:ssh|pkg:ssh) echo "openssh" ;;
  esac
}

group_tools() {
  case "$1" in
    basic) echo "curl wget git tar gzip nano" ;;
    network) echo "ss netstat dig lsof ping" ;;
    ssh) echo "ssh sshd scp" ;;
  esac
}

install_group() {
  local pm="$1" group="$2" pkgs_str tools_str tool plan i
  local -a pkgs=() tools=() cmd=()
  local missing=0

  pkgs_str="$(pm_group_packages "$pm" "$group")"
  if [[ -z "$pkgs_str" ]]; then say install_no_packages; return; fi
  read -r -a pkgs <<< "$pkgs_str"
  for i in "${!pkgs[@]}"; do
    pkgs[$i]="$(pm_map_package "$pm" "${pkgs[$i]}")"
  done
  tools_str="$(group_tools "$group")"
  read -r -a tools <<< "$tools_str"

  say install_status
  for tool in "${tools[@]}"; do
    if have "$tool"; then
      printf '  [%s] %s\n' "$(t install_present)" "$tool"
    else
      printf '  [%s] %s\n' "$(t install_missing)" "$tool"
      missing=1
    fi
  done
  (( missing )) || { say install_none_missing; return; }

  case "$pm" in
    apt) cmd=(apt-get install -y) ;;
    dnf) cmd=(dnf install -y) ;;
    yum) cmd=(yum install -y) ;;
    pacman) cmd=(pacman -S --needed --noconfirm) ;;
    zypper) cmd=(zypper --non-interactive install) ;;
    apk) cmd=(apk add) ;;
    pkg) cmd=(pkg install -y) ;;
  esac
  cmd+=("${pkgs[@]}")
  plan="${cmd[*]}"
  if ! (( IS_TERMUX )) && ! is_root && have sudo; then plan="sudo $plan"; fi
  ui_text "$(t install_plan) $plan" ""

  if ! (( IS_TERMUX )) && ! is_root && ! have sudo; then
    say install_sudo
    return
  fi
  if [[ "${NANO_ASSUME_YES:-0}" != "1" ]]; then
    if ! confirm "$(t install_confirm)"; then say cancelled; return; fi
  fi

  pm_refresh_metadata "$pm" || true
  say install_running
  if (( IS_TERMUX )) || is_root; then
    "${cmd[@]}"
  else
    sudo "${cmd[@]}"
  fi
  if (( $? == 0 )); then say install_done; else say install_fail; fi
}

install_menu() {
  local pm
  while true; do
    title
    ui_header "$(t install_title)"
    pm="$(detect_pm)"
    if [[ -z "$pm" ]]; then
      say install_no_manager
      pause
      return
    fi
    sayf install_manager "$pm"
    if (( IS_TERMUX )); then say install_termux_note; fi
    say install_readonly_note
    say install_need_confirm
    line
    ui_menu "1|$(t install_group_basic)" "2|$(t install_group_network)" \
      "3|$(t install_group_ssh)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) install_group "$pm" basic; pause ;;
      2) install_group "$pm" network; pause ;;
      3) install_group "$pm" ssh; pause ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

