nano_script_dir() {
  dirname -- "$(abspath "${BASH_SOURCE[0]:-$0}")"
}

nano_source_dir() {
  local candidate
  for candidate in "${NANO_SOURCE_DIR:-}" \
    "$NANO_PAYLOAD_DIR/SCRIPTMOD-LACASITA" \
    "${HOME:-/tmp}/nano-vps-sources/SCRIPTMOD-LACASITA" \
    "$(nano_script_dir)/nano-vps-sources/SCRIPTMOD-LACASITA"; do
    [[ -n "$candidate" && -d "$candidate" ]] || continue
    printf '%s' "$candidate"
    return 0
  done
  printf '%s' "${NANO_SOURCE_DIR:-${HOME:-/tmp}/nano-vps-sources/SCRIPTMOD-LACASITA}"
}

b64_decode() {
  if have base64; then
    base64 -d
  elif have openssl; then
    openssl base64 -d -A
  elif have python3; then
    python3 -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))'
  else
    return 1
  fi
}

payload_ensure() {
  local root="$NANO_PAYLOAD_DIR" target="$NANO_PAYLOAD_DIR/SCRIPTMOD-LACASITA"
  local tmp actual
  if [[ -f "$target/install.sh" && -f "$target/hcr-server" &&
        -f "$target/SLOWDNS/dns-server" && -f "$target/test/badvpn-master.zip" ]]; then
    return 0
  fi
  is_root || { say modules_need_root; return 1; }
  if ! have tar; then
    sayf proto_dep_missing "tar"
    return 1
  fi
  install -d -m 0755 -- "$root" || { say proto_payload_fail; return 1; }
  tmp="$(mktemp "$root/.payload.XXXXXX")" || { say proto_payload_fail; return 1; }
  if ! nano_payload_b64 | b64_decode > "$tmp"; then
    rm -f -- "$tmp"
    say proto_payload_decode_fail
    return 1
  fi
  actual="$(sha256_file "$tmp" 2>/dev/null || true)"
  if [[ "${actual,,}" != "${NANO_PAYLOAD_SHA256,,}" ]]; then
    rm -f -- "$tmp"
    say proto_payload_integrity
    return 1
  fi
  if ! tar -xzf "$tmp" -C "$root" >/dev/null 2>&1; then
    rm -f -- "$tmp"
    say proto_payload_fail
    return 1
  fi
  rm -f -- "$tmp"
  chown -R root:root "$target" 2>/dev/null || true
  chmod 0755 "$target/install.sh" "$target/hcr-server" "$target/SLOWDNS/dns-server" 2>/dev/null || true
  chmod 0644 "$target/README.md" "$target/test/badvpn-master.zip" 2>/dev/null || true
  sayf proto_payload_ready "$target"
  return 0
}

host_arch() {
  uname -m 2>/dev/null || printf 'unknown'
}

host_arch_family() {
  case "$(host_arch)" in
    x86_64|amd64) printf 'x86-64' ;;
    aarch64|arm64) printf 'arm64' ;;
    armv7*|armv6*|armhf) printf 'arm' ;;
    i386|i486|i586|i686) printf 'x86' ;;
    *) host_arch ;;
  esac
}

elf_machine_num() {
  local file_path="$1" magic lo hi
  [[ -f "$file_path" ]] || return 1
  have od || return 1
  magic="$(od -An -tx1 -N4 -- "$file_path" 2>/dev/null | tr -d ' \n')"
  [[ "$magic" == "7f454c46" ]] || return 1
  lo="$(od -An -tu1 -j18 -N1 -- "$file_path" 2>/dev/null | tr -d ' ')"
  hi="$(od -An -tu1 -j19 -N1 -- "$file_path" 2>/dev/null | tr -d ' ')"
  [[ "$lo" =~ ^[0-9]+$ && "$hi" =~ ^[0-9]+$ ]] || return 1
  printf '%s' "$(( lo + 256 * hi ))"
}

elf_machine_name() {
  case "$1" in
    62) printf 'x86-64' ;;
    183) printf 'arm64' ;;
    40) printf 'arm' ;;
    3) printf 'x86' ;;
    *) printf 'machine-%s' "$1" ;;
  esac
}

binary_arch() {
  local file_path="$1" machine description
  [[ -f "$file_path" ]] || return 1
  machine="$(elf_machine_num "$file_path" 2>/dev/null)" && {
    elf_machine_name "$machine"
    return 0
  }
  if have file; then
    description="$(file -b -- "$file_path" 2>/dev/null)"
    case "$description" in
      *x86-64*|*x86_64*) printf 'x86-64' ;;
      *aarch64*|*ARM64*|*ARM\ aarch64*) printf 'arm64' ;;
      *ARM*) printf 'arm' ;;
      *80386*|*i386*) printf 'x86' ;;
      *) printf 'unknown' ;;
    esac
    return 0
  fi
  printf 'unknown'
}

sha256_file() {
  local file_path="$1"
  [[ -f "$file_path" ]] || return 1
  if have sha256sum; then
    sha256sum -- "$file_path" 2>/dev/null | awk '{print $1; exit}'
  elif have shasum; then
    shasum -a 256 -- "$file_path" 2>/dev/null | awk '{print $1; exit}'
  elif have openssl; then
    openssl dgst -sha256 -- "$file_path" 2>/dev/null | awk '{print $NF; exit}'
  else
    return 1
  fi
}

verify_hash() {
  local file_path="$1" expected="$2" actual
  actual="$(sha256_file "$file_path" 2>/dev/null)" || {
    say proto_hash_mismatch
    return 1
  }
  if [[ "${actual,,}" != "${expected,,}" ]]; then
    say proto_hash_mismatch
    sayf proto_hash_expected "$expected"
    printf '  sha256: %s\n' "$actual"
    return 1
  fi
  printf '  sha256: %s\n' "$actual"
  return 0
}

valid_port() {
  [[ "$1" =~ ^[0-9]{1,5}$ ]] && (( 10#$1 >= 1 && 10#$1 <= 65535 ))
}

valid_target() {
  local value="$1" host port
  if [[ "$value" == \[*\]:* ]]; then
    host="${value%%]*}"; host="${host#[}"
    port="${value##*:}"
  elif [[ "$value" == *:* ]]; then
    host="${value%:*}"
    port="${value##*:}"
  else
    return 1
  fi
  [[ -n "$host" ]] && valid_port "$port"
}

valid_domain() {
  [[ "$1" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$ ]] &&
    [[ "$1" == *.* ]] && [[ "$1" != *..* ]]
}

valid_udp_range() {
  local value="$1" start end
  [[ "$value" =~ ^([0-9]{1,5})-([0-9]{1,5})$ ]] || return 1
  start=$((10#${BASH_REMATCH[1]}))
  end=$((10#${BASH_REMATCH[2]}))
  (( start >= 1 && end <= 65535 && start <= end ))
}

range_start() {
  local value="$1"
  [[ "$value" == *-* ]] && printf '%s' "$((10#${value%%-*}))" || printf '%s' "$((10#$value))"
}

range_end() {
  local value="$1"
  [[ "$value" == *-* ]] && printf '%s' "$((10#${value##*-}))" || printf '%s' "$((10#$value))"
}

range_span() {
  local start end
  start="$(range_start "$1")"
  end="$(range_end "$1")"
  printf '%s' "$(( end - start + 1 ))"
}

port_state() {
  local proto="$1" port="$2" hex state file_path found=0
  valid_port "$port" || { printf 'unknown'; return 0; }
  case "$proto" in
    tcp) state=0A ;;
    udp) state=07 ;;
    *) printf 'unknown'; return 0 ;;
  esac
  hex="$(printf '%04X' "$((10#$port))")"

  if [[ -r /proc/net/tcp ]]; then
    local -a files=()
    [[ "$proto" == tcp ]] && files=(/proc/net/tcp /proc/net/tcp6)
    [[ "$proto" == udp ]] && files=(/proc/net/udp /proc/net/udp6)
    for file_path in "${files[@]}"; do
      [[ -r "$file_path" ]] || continue
      if awk -v want="$hex" -v st="$state" '
        FNR > 1 {
          n = split($2, a, ":")
          if (toupper(a[n]) == want && toupper($4) == st) { found = 1; exit }
        }
        END { exit found ? 0 : 1 }
      ' "$file_path" 2>/dev/null; then
        printf 'yes'
        return 0
      fi
    done
    printf 'no'
    return 0
  fi

  if have ss; then
    case "$proto" in
      tcp) ss -H -lnt 2>/dev/null | awk -v p=":$((10#$port))" '$4 ~ p"$" { found = 1 } END { exit found ? 0 : 1 }' ;;
      udp) ss -H -lnu 2>/dev/null | awk -v p=":$((10#$port))" '$4 ~ p"$" { found = 1 } END { exit found ? 0 : 1 }' ;;
    esac
    if (( $? == 0 )); then printf 'yes'; else printf 'no'; fi
    return 0
  fi
  printf 'unknown'
}

port_word() {
  case "$1" in
    yes) printf '%s' "$(t proto_listening)" ;;
    no) printf '%s' "$(t proto_not_listening)" ;;
    *) printf '%s' "$(t proto_unknown_state)" ;;
  esac
}

service_unit_exists() {
  [[ -n "$1" ]] && systemctl cat "$1" >/dev/null 2>&1
}

service_active() {
  [[ -n "$1" ]] && systemctl is-active --quiet "$1" 2>/dev/null
}

service_load_state() {
  systemctl show -p LoadState --value "$1" 2>/dev/null || true
}

env_get() {
  local file_path="$1" key="$2"
  [[ -r "$file_path" ]] || return 1
  awk -F= -v key="$key" '$1 == key { sub(/^[^=]*=/, ""); print; exit }' "$file_path" 2>/dev/null
}

write_config_file() {
  local path="$1" mode="$2" content="$3" dir tmp
  dir="$(dirname -- "$path")"
  install -d -m 0755 -- "$dir" || return 1
  tmp="$(mktemp "$dir/.nano.XXXXXX")" || return 1
  if ! printf '%s\n' "$content" > "$tmp"; then
    rm -f -- "$tmp"
    return 1
  fi
  chmod "$mode" -- "$tmp" 2>/dev/null || true
  mv -f -- "$tmp" "$path" || return 1
}

backup_file() {
  local file_path="$1" stamp
  [[ -e "$file_path" ]] || return 0
  stamp="$(date +%Y%m%d-%H%M%S).$$"
  if cp -a -- "$file_path" "${file_path}.bak.${stamp}" 2>/dev/null; then
    sayf proto_config_backup "${file_path}.bak.${stamp}"
    return 0
  fi
  return 1
}

install_unit_content() {
  local name="$1" content="$2" tmp
  is_root || { say modules_need_root; return 1; }
  install -d -m 0755 -- "$NANO_SYSTEMD_DIR" || return 1
  if [[ -e "$NANO_SYSTEMD_DIR/$name" ]]; then backup_file "$NANO_SYSTEMD_DIR/$name" || return 1; fi
  tmp="$NANO_SYSTEMD_DIR/.${name}.$$.tmp"
  if ! printf '%s\n' "$content" > "$tmp"; then
    rm -f -- "$tmp"
    return 1
  fi
  chmod 0644 -- "$tmp" 2>/dev/null || true
  mv -f -- "$tmp" "$NANO_SYSTEMD_DIR/$name" || return 1
  systemctl daemon-reload
}

remove_units() {
  local unit
  for unit in "$@"; do
    systemctl disable --now "$unit" >/dev/null 2>&1 || true
  done
  systemctl daemon-reload >/dev/null 2>&1 || true
  for unit in "$@"; do
    rm -f -- "$NANO_SYSTEMD_DIR/$unit"
  done
  systemctl daemon-reload >/dev/null 2>&1 || true
}

require_vps_root_systemd() {
  if (( IS_TERMUX )) || [[ "$(uname -s 2>/dev/null)" != "Linux" ]]; then
    say modules_linux_root
    return 1
  fi
  if ! is_root; then
    say modules_need_root
    return 1
  fi
  if ! systemd_available; then
    say services_no_systemd
    return 1
  fi
  return 0
}

pm_install_packages() {
  local pm pkg
  pm="$(detect_pm)"
  [[ -n "$pm" ]] || { say install_no_manager; return 1; }
  local -a cmd=() packages=()
  for pkg in "$@"; do
    packages+=("$(pm_map_package "$pm" "$pkg")")
  done
  case "$pm" in
    apt) cmd=(apt-get install -y) ;;
    dnf) cmd=(dnf install -y) ;;
    yum) cmd=(yum install -y) ;;
    pacman) cmd=(pacman -S --needed --noconfirm) ;;
    zypper) cmd=(zypper --non-interactive install) ;;
    apk) cmd=(apk add) ;;
    pkg) cmd=(pkg install -y) ;;
  esac
  cmd+=("${packages[@]}")
  if ! (( IS_TERMUX )) && ! is_root; then
    if have sudo; then
      cmd=(sudo "${cmd[@]}")
    else
      say modules_need_root
      return 1
    fi
  fi
  pm_refresh_metadata "$pm" || true
  sayf proto_install_plan_generic "${cmd[*]}"
  "${cmd[@]}"
}

# Dependencias instaladas bajo demanda: solo cuando se elige un protocolo.
proto_dependency_packages() {
  local id="$1" pm
  pm="$(detect_pm)"
  case "$id:$pm" in
    ssh:apt) printf 'openssh-server' ;;
    ssh:dnf|ssh:yum) printf 'openssh-server' ;;
    ssh:pacman|ssh:zypper|ssh:apk) printf 'openssh-server' ;;
    ws:*) printf 'python3' ;;
    slowdns:*) printf 'python3 ca-certificates' ;;
    ssl:apt) printf 'stunnel4 openssl' ;;
    ssl:dnf|ssl:yum|ssl:zypper|ssl:apk) printf 'stunnel4 openssl' ;;
    ssl:pacman) printf 'stunnel openssl' ;;
    hcr:*) printf 'openssl python3 ca-certificates' ;;
    bhttp:*) printf 'python3' ;;
    badvpn:apt) printf 'build-essential cmake unzip' ;;
    badvpn:dnf|badvpn:yum|badvpn:zypper) printf 'gcc make cmake unzip' ;;
    badvpn:pacman) printf 'base-devel cmake unzip' ;;
    badvpn:apk) printf 'build-base cmake unzip' ;;
    udp_custom:*) printf 'python3' ;;
    hysteria:*) printf 'ca-certificates openssl' ;;
    xray:*) printf 'curl unzip openssl ca-certificates' ;;
    dropbear:apt) printf 'dropbear' ;;
    dropbear:dnf|dropbear:yum|dropbear:pacman|dropbear:zypper|dropbear:apk) printf 'dropbear' ;;
    *) printf '' ;;
  esac
}

proto_dependency_commands_ready() {
  case "$1" in
    ssh) have sshd ;;
    ws|bhttp|udp_custom) have python3 ;;
    slowdns) have base64 || have openssl || have python3 ;;
    ssl) { have stunnel || have stunnel4; } && have openssl ;;
    hcr) have openssl && { have base64 || have python3 || have openssl; } && { [[ -r /etc/ssl/certs/ca-certificates.crt ]] || [[ -r /etc/pki/tls/certs/ca-bundle.crt ]] || have curl || have wget; } ;;
    badvpn) have gcc && have make && have cmake && have unzip ;;
    hysteria) { have curl || have wget; } && have openssl ;;
    xray) have curl && have unzip && have openssl && have useradd && have groupadd && have getent ;;
    dropbear) have dropbear ;;
    *) return 0 ;;
  esac
}

proto_selected_dependencies_ensure() {
  local id="$1" pm packages pkg command_missing=0
  local -a pkgs=()
  proto_dependency_commands_ready "$id" && { say proto_preflight_deps_ready; return 0; }
  pm="$(detect_pm)"
  if [[ -z "$pm" || "$pm" == pkg ]]; then
    say proto_deps_no_pm
    return 1
  fi
  packages="$(proto_dependency_packages "$id")"
  if [[ "$id" == hysteria ]] && ! have curl && ! have wget; then
    packages="${packages:+$packages }curl"
  fi
  if [[ -z "$packages" ]]; then
    say proto_deps_ready
    return 0
  fi
  read -r -a pkgs <<< "$packages"
  sayf proto_preflight_deps "$packages"
  confirm "$(printf "$(t proto_dep_install_q)" "$pm")" || { say proto_preflight_cancel; return 1; }
  if ! pm_install_packages "${pkgs[@]}"; then
    say proto_deps_missing
    return 1
  fi
  if ! proto_dependency_commands_ready "$id"; then
    say proto_deps_missing
    return 1
  fi
  say proto_deps_ready
  return 0
}

proto_preflight_port_owned() {
  local id="$1" port="$2" unit
  case "$id" in
    ssh) unit="$(ssh_unit_name).service"; service_active "$unit" ;;
    ws) service_active nano-ws.service ;;
    slowdns) service_active "nano-slowdns@${port}.service" ;;
    ssl) service_active nano-ssl.service ;;
    hcr) service_active hcr-server.service ;;
    bhttp) service_active nano-bhttp.service ;;
    badvpn) service_active "nano-udpgw@${port}.service" ;;
    udp_custom) service_active nano-udp-custom.service ;;
    hysteria) service_active "$NANO_HYSTERIA_UNIT" ;;
    xray) service_active "$NANO_XRAY_UNIT" ;;
    dropbear) service_active "$NANO_DROPBEAR_UNIT" ;;
    *) return 1 ;;
  esac
}

proto_preflight_port_check() {
  local id="$1" transport="$2" port="$3" suggested
  valid_port "$port" || return 0
  if proto_preflight_port_owned "$id" "$port"; then
    sayf proto_preflight_port_owned "$port" "$transport"
    return 0
  fi
  case "$(port_state "$transport" "$port")" in
    no)
      if port_registry_has "$transport" "$port"; then
        suggested="$(port_suggest_free "$transport" "$port" 2>/dev/null || true)"
        if [[ -n "$suggested" ]]; then sayf proto_preflight_port_busy "$port" "$transport" "$suggested"; else say proto_preflight_no_port; fi
      else
        sayf proto_preflight_port_free "$port" "$transport"
      fi
      ;;
    yes)
      suggested="$(port_suggest_free "$transport" "$port" 2>/dev/null || true)"
      if [[ -n "$suggested" ]]; then sayf proto_preflight_port_busy "$port" "$transport" "$suggested"; else say proto_preflight_no_port; fi
      ;;
    *) sayf proto_preflight_port_unknown "$port" "$transport" ;;
  esac
}

proto_preflight_ports() {
  local id="$1" port
  case "$id" in
    ssh) port="$(proto_port_value ssh)"; proto_preflight_port_check "$id" tcp "${port:-22}" ;;
    ws) port="$(proto_port_value ws)"; proto_preflight_port_check "$id" tcp "${port:-80}" ;;
    slowdns) for port in $(slowdns_ports); do proto_preflight_port_check "$id" udp "$port"; done ;;
    ssl) port="$(proto_port_value ssl)"; proto_preflight_port_check "$id" tcp "${port:-443}" ;;
    hcr) port="$(proto_port_value hcr)"; proto_preflight_port_check "$id" tcp "${port:-8080}" ;;
    bhttp) port="$(proto_port_value bhttp)"; proto_preflight_port_check "$id" tcp "${port:-8880}" ;;
    badvpn) for port in 7200 7300 7400; do proto_preflight_port_check "$id" tcp "$port"; done ;;
    udp_custom) proto_preflight_port_check "$id" udp 7400 ;;
    hysteria) port="$(proto_port_value hysteria)"; proto_preflight_port_check "$id" udp "${port:-8443}" ;;
    xray)
      proto_preflight_port_check "$id" tcp "$(xray_port_value XRAY_VMESS_PORT 10086)"
      proto_preflight_port_check "$id" tcp "$(xray_port_value XRAY_VLESS_PORT 10087)"
      proto_preflight_port_check "$id" tcp "$(xray_port_value XRAY_TROJAN_PORT 10088)"
      ;;
    dropbear) port="$(proto_port_value dropbear)"; proto_preflight_port_check "$id" tcp "${port:-2222}" ;;
  esac
}

proto_install_preflight() {
  local id="$1" status class active=0 recommended available running_id
  local ram cpu disk
  profile_load
  class="$(profile_capacity_class)"
  ram="${PROFILE_RAM_MB:-0}"; cpu="${PROFILE_CPU:-0}"; disk="${PROFILE_DISK_MB:-0}"
  ui_header "$(t proto_preflight_title)"
  sayf proto_preflight_capacity "$(t "profile_size_$class")" "$ram" "$cpu" "$disk"
  if [[ "$class" == small ]]; then say proto_preflight_small_warn; fi
  available="$(profile_available_count)"
  recommended="$(profile_recommended_count "$available" "$class")"
  for running_id in ssh ws slowdns ssl hcr bhttp badvpn udp_custom hysteria xray dropbear; do
    if dash_proto_on "$running_id"; then active=$((active + 1)); fi
  done
  if (( recommended > 0 && active >= recommended && active > 0 )); then sayf proto_preflight_active_warn "$active" "$recommended"; fi
  status="$(profile_status "$id")"
  if [[ "$status" != ok ]]; then
    case "$status" in
      arch:*) sayf profile_reason_arch "${status#arch:}" ;;
      ram:*) sayf profile_reason_ram "${status#ram:}" ;;
      disk:*) sayf profile_reason_disk "${status#disk:}" ;;
    esac
    say proto_preflight_blocked
    return 1
  fi
  proto_preflight_ports "$id"
  return 0
}

tcp_probe() {
  local host="$1" port="$2" timeout="${3:-3}"
  if have python3; then
    python3 - "$host" "$port" "$timeout" <<'NANO_PROBE_PY'
import socket, sys
host, port, timeout = sys.argv[1], int(sys.argv[2]), float(sys.argv[3])
try:
    with socket.create_connection((host, port), timeout=timeout):
        pass
except OSError:
    sys.exit(1)
NANO_PROBE_PY
  elif have timeout; then
    timeout "$timeout" bash -c 'exec 3<>"/dev/tcp/${1}/${2}"' _ "$host" "$port" 2>/dev/null
  else
    return 2
  fi
}

http_probe() {
  local host="$1" port="$2"
  have python3 || return 2
  python3 - "$host" "$port" <<'NANO_PROBE_PY'
import socket, sys
host, port = sys.argv[1], int(sys.argv[2])
try:
    with socket.create_connection((host, port), timeout=3) as sock:
        sock.settimeout(3)
        sock.sendall(b"GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n")
        data = sock.recv(64)
    sys.exit(0 if data.startswith(b"HTTP/") else 1)
except OSError:
    sys.exit(1)
NANO_PROBE_PY
}

tls_probe() {
  local host="$1" port="$2"
  have openssl || return 2
  openssl s_client -connect "${host}:${port}" -servername "$host" </dev/null 2>/dev/null |
    grep -q 'BEGIN CERTIFICATE'
}

dns_probe() {
  local host="$1" port="$2" domain="$3"
  have python3 || return 2
  python3 - "$host" "$port" "$domain" <<'NANO_PROBE_PY'
import os, socket, struct, sys
host, port, domain = sys.argv[1], int(sys.argv[2]), sys.argv[3]
query_id = os.urandom(2)
labels = b"".join(bytes([len(part)]) + part.encode("ascii") for part in domain.split(".") if part)
packet = query_id + b"\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00" + labels + b"\x00\x00\x10\x00\x01"
try:
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(3)
    sock.sendto(packet, (host, port))
    data, _ = sock.recvfrom(4096)
    sys.exit(0 if len(data) >= 12 and data[:2] == query_id else 1)
except OSError:
    sys.exit(1)
finally:
    try:
        sock.close()
    except Exception:
        pass
NANO_PROBE_PY
}

udp_payload_probe() {
  local host="$1" port="$2" payload="${3:-nano-vps-probe}"
  have python3 || return 2
  python3 - "$host" "$port" "$payload" <<'NANO_PROBE_PY'
import socket, sys
host, port, payload = sys.argv[1], int(sys.argv[2]), sys.argv[3].encode()
try:
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(2)
    sock.sendto(payload, (host, port))
    sock.recvfrom(4096)
    sys.exit(0)
except OSError:
    sys.exit(1)
finally:
    try:
        sock.close()
    except Exception:
        pass
NANO_PROBE_PY
}

ssh_unit_name() {
  local unit
  for unit in ssh sshd; do
    if systemctl cat "${unit}.service" >/dev/null 2>&1; then
      printf '%s' "$unit"
      return 0
    fi
  done
  printf 'ssh'
}

slowdns_ports() {
  local ports="53 5300" value
  value="$(env_get "$NANO_ETC_DIR/slowdns.env" SLOWDNS_PORTS 2>/dev/null || true)"
  [[ -n "$value" ]] && ports="$value"
  printf '%s' "$ports"
}

udp_custom_range() {
  local value
  value="$(env_get "$NANO_ETC_DIR/udp-custom.env" NANO_UDP_RANGE 2>/dev/null || true)"
  printf '%s' "$value"
}

xray_port_value() {
  local key="$1" fallback="$2" value
  value="$(env_get "$NANO_XRAY_ENV" "$key" 2>/dev/null || true)"
  printf '%s' "${value:-$fallback}"
}

proto_port_value() {
  local id="$1" value
  case "$id" in
    ssh)
      value="$(sshd -T 2>/dev/null | awk '$1 == "port" { print $2; exit }')"
      printf '%s' "${value:-22}"
      ;;
    ws)
      value="$(env_get "$NANO_ETC_DIR/ws.env" NANO_WS_LISTEN 2>/dev/null || true)"
      printf '%s' "${value:+${value##*:}}"
      [[ -n "$value" ]] || printf '80'
      ;;
    slowdns)
      slowdns_ports
      ;;
    ssl)
      value="$(awk -F= '/^[[:space:]]*accept[[:space:]]*=/{gsub(/[[:space:]]/, "", $2); print $2; exit}' "$NANO_ETC_DIR/stunnel.conf" 2>/dev/null || true)"
      if [[ -n "$value" ]]; then printf '%s' "${value##*:}"; else printf '443'; fi
      ;;
    hcr)
      value="$(systemctl cat hcr-server.service 2>/dev/null | sed -n -e 's/.*--listen[ =]*:\([0-9][0-9]*\).*/\1/p' -e 's/.*--port[ =][[:space:]]*\([0-9][0-9]*\).*/\1/p' | sed -n '1p')"
      printf '%s' "${value:-8080}"
      ;;
    bhttp)
      value="$(env_get "$NANO_ETC_DIR/bhttp.env" NANO_BHTTP_LISTEN 2>/dev/null || true)"
      if [[ -n "$value" ]]; then printf '%s' "${value##*:}"; else printf '8880'; fi
      ;;
    hysteria)
      value="$(env_get "$NANO_HYSTERIA_ENV" NANO_HYSTERIA_PORT 2>/dev/null || true)"
      printf '%s' "${value:-8443}"
      ;;
    xray) xray_port_value XRAY_VMESS_PORT 10086 ;;
    dropbear) value="$(env_get "$NANO_DROPBEAR_ENV" DROPBEAR_PORT 2>/dev/null || true)"; printf '%s' "${value:-2222}" ;;
    udp_custom)
      udp_custom_range
      ;;
  esac
}

proto_ports_label() {
  local port sep=""
  case "$1" in
    ssh) printf '%s/TCP' "$(proto_port_value ssh)" ;;
    ws) printf '%s/TCP' "$(proto_port_value ws)" ;;
    slowdns)
      for port in $(slowdns_ports); do
        printf '%s%s/UDP' "$sep" "$port"
        sep=", "
      done
      ;;
    ssl) printf '%s/TCP' "$(proto_port_value ssl)" ;;
    hcr) printf '%s/TCP' "$(proto_port_value hcr)" ;;
    bhttp) printf '%s/TCP' "$(proto_port_value bhttp)" ;;
    hysteria) printf '%s/UDP' "$(proto_port_value hysteria)" ;;
    xray) printf '%s/TCP VMess, %s/TCP VLESS, %s/TCP Trojan' "$(xray_port_value XRAY_VMESS_PORT 10086)" "$(xray_port_value XRAY_VLESS_PORT 10087)" "$(xray_port_value XRAY_TROJAN_PORT 10088)" ;;
    dropbear) printf '%s/TCP' "$(proto_port_value dropbear)" ;;
    badvpn) printf '7200/TCP, 7300/TCP, 7400/TCP' ;;
    udp_custom)
      local range
      range="$(udp_custom_range)"
      if [[ -n "$range" ]]; then printf '%s/UDP' "$range"; else printf '%s' "$(t proto_not_configured)"; fi
      ;;
  esac
}

proto_port_specs() {
  local port
  case "$1" in
    ssh) printf '%s/tcp' "$(proto_port_value ssh)" ;;
    ws) printf '%s/tcp' "$(proto_port_value ws)" ;;
    slowdns)
      for port in $(slowdns_ports); do printf '%s/udp ' "$port"; done
      ;;
    ssl) printf '%s/tcp' "$(proto_port_value ssl)" ;;
    hcr) printf '%s/tcp' "$(proto_port_value hcr)" ;;
    bhttp) printf '%s/tcp' "$(proto_port_value bhttp)" ;;
    hysteria) printf '%s/udp' "$(proto_port_value hysteria)" ;;
    xray) printf '%s/tcp %s/tcp %s/tcp' "$(xray_port_value XRAY_VMESS_PORT 10086)" "$(xray_port_value XRAY_VLESS_PORT 10087)" "$(xray_port_value XRAY_TROJAN_PORT 10088)" ;;
    dropbear) printf '%s/tcp' "$(proto_port_value dropbear)" ;;
    badvpn) printf '7200/tcp 7300/tcp 7400/tcp' ;;
    udp_custom)
      local range
      range="$(udp_custom_range)"
      [[ -n "$range" ]] && printf '%s/udp' "$range"
      ;;
  esac
}

proto_units() {
  local unit port
  case "$1" in
    ssh) printf '%s.service' "$(ssh_unit_name)" ;;
    ws) printf 'nano-ws.service' ;;
    slowdns)
      for port in $(slowdns_ports); do printf 'nano-slowdns@%s.service ' "$port"; done
      ;;
    ssl) printf 'nano-ssl.service' ;;
    hcr) printf 'hcr-server.service' ;;
    bhttp) printf 'nano-bhttp.service' ;;
    hysteria) printf '%s' "$NANO_HYSTERIA_UNIT" ;;
    xray) printf '%s' "$NANO_XRAY_UNIT" ;;
    dropbear) printf '%s' "$NANO_DROPBEAR_UNIT" ;;
    badvpn) printf 'nano-udpgw@7200.service nano-udpgw@7300.service nano-udpgw@7400.service' ;;
    udp_custom) printf 'nano-udp-custom.service' ;;
  esac
}

proto_config_path() {
  case "$1" in
    ssh) printf '/etc/ssh/sshd_config' ;;
    ws) printf '%s/ws.env' "$NANO_ETC_DIR" ;;
    slowdns) printf '%s/slowdns.env' "$NANO_ETC_DIR" ;;
    ssl) printf '%s/stunnel.conf' "$NANO_ETC_DIR" ;;
    hcr) printf '%s' "$NANO_HCR_BUNDLE_DIR" ;;
    bhttp) printf '%s/bhttp.env' "$NANO_ETC_DIR" ;;
    hysteria) printf '%s' "$NANO_HYSTERIA_CONFIG" ;;
    xray) printf '%s' "$NANO_XRAY_CONFIG" ;;
    dropbear) printf '%s' "$NANO_DROPBEAR_ENV" ;;
    badvpn) printf '%s/nano-udpgw@.service' "$NANO_SYSTEMD_DIR" ;;
    udp_custom) printf '%s/udp-custom.env' "$NANO_ETC_DIR" ;;
  esac
}

proto_binary_path() {
  case "$1" in
    ssh) command -v sshd 2>/dev/null || printf '%s' "$(t proto_not_installed)" ;;
    ws) printf '%s/ws/ws_tunnel.py' "$NANO_OPT_DIR" ;;
    slowdns) printf '%s/slowdns/dns-server' "$NANO_OPT_DIR" ;;
    ssl) command -v stunnel 2>/dev/null || command -v stunnel4 2>/dev/null || printf '%s' "$(t proto_not_installed)" ;;
    hcr) printf '%s' "$NANO_HCR_BUNDLE_DIR/hcr-server" ;;
    bhttp) printf '%s/bhttp/bhttp_proxy.py' "$NANO_OPT_DIR" ;;
    hysteria) printf '%s' "$NANO_HYSTERIA_BIN" ;;
    xray) printf '%s' "$NANO_XRAY_BIN" ;;
    dropbear) command -v dropbear 2>/dev/null || printf '%s' "$(t proto_not_installed)" ;;
    badvpn) printf '%s/badvpn/udpgw' "$NANO_OPT_DIR" ;;
    udp_custom) printf '%s/udp/udp_forwarder.py' "$NANO_OPT_DIR" ;;
  esac
}

proto_overview() {
  local id="$1" spec port proto state unit load running
  sayf proto_ports "$(proto_ports_label "$id")"
  local -a specs=()
  specs=($(proto_port_specs "$id"))
  for spec in "${specs[@]}"; do
    port="${spec%/*}"
    proto="${spec#*/}"
    if [[ "$port" == *-* ]]; then
      state="$(port_state "$proto" "$(range_start "$port")")"
      printf '  %s/%s: %s\n' "$port" "$proto" "$(port_word "$state")"
    else
      state="$(port_state "$proto" "$port")"
      printf '  %s/%s: %s\n' "$port" "$proto" "$(port_word "$state")"
    fi
  done
  for unit in $(proto_units "$id"); do
    load="$(service_load_state "$unit")"
    if [[ -z "$load" || "$load" == "not-found" ]]; then
      printf '  %s: %s\n' "$unit" "$(t proto_not_installed)"
    elif service_active "$unit"; then
      printf '  %s: %s\n' "$unit" "$(t proto_active)"
    else
      printf '  %s: %s\n' "$unit" "$(t proto_inactive)"
    fi
  done
}

proto_status() {
  local id="$1" unit spec
  title
  ui_header "$(t "proto_$id")"
  say "proto_${id}_desc"
  line
  proto_overview "$id"
  line
  sayf proto_config "$(proto_config_path "$id")"
  sayf proto_binary "$(proto_binary_path "$id")"
  case "$id" in
    slowdns)
      if [[ -r "$NANO_OPT_DIR/slowdns/server.pub" ]]; then
        sayf proto_public_key "$(tr -d '\n' < "$NANO_OPT_DIR/slowdns/server.pub" 2>/dev/null)"
      fi
      ;;
    ssl)
      if [[ -f "$NANO_ETC_DIR/ssl/fullchain.pem" ]]; then
        printf '  cert: %s\n' "$NANO_ETC_DIR/ssl/fullchain.pem"
      fi
      ;;
    badvpn)
      say proto_badvpn_tcp_note
      ;;
  esac
  line
  for unit in $(proto_units "$id"); do
    if service_unit_exists "$unit"; then
      printf '\n[%s]\n' "$unit"
      systemctl status --no-pager --full "$unit" 2>&1 | sed 's/^/  /' | ui_fold
    fi
  done
  pause
}

proto_service_action() {
  local id="$1" action="$2" unit failed=0
  require_vps_root_systemd || { pause; return; }
  if [[ ( "$id" == ssh || "$id" == dropbear ) && ( "$action" == stop || "$action" == restart ) ]]; then
    say proto_ssh_service_warn
    confirm "$(t proto_ssh_remote_confirm)" || { say cancelled; pause; return; }
  fi
  local -a units=()
  for unit in $(proto_units "$id"); do units+=("$unit"); done
  if (( ${#units[@]} == 0 )); then
    say proto_not_installed
    pause
    return
  fi
  for unit in "${units[@]}"; do
    if ! service_unit_exists "$unit"; then
      printf '  %s: %s\n' "$unit" "$(t proto_not_installed)"
      failed=1
      continue
    fi
    if systemctl "$action" "$unit"; then
      printf '  %s: %s\n' "$unit" "$(t proto_action_done)"
    else
      printf '  %s: %s\n' "$unit" "$(t proto_action_fail)"
      failed=1
    fi
  done
  sleep 1
  line
  proto_overview "$id"
  (( failed )) && say proto_action_fail || say proto_action_done
  pause
}

proto_logs() {
  local id="$1" unit shown=0
  title
  ui_header "$(t proto_logs): $(t "proto_$id")"
  for unit in $(proto_units "$id"); do
    service_unit_exists "$unit" || continue
    printf '\n[%s]\n' "$unit"
    journalctl -u "$unit" --no-pager -n 50 2>&1 | sed 's/^/  /' | ui_fold
    shown=1
  done
  (( shown )) || say proto_not_installed
  pause
}

proto_connectivity() {
  local id="$1" port spec ok=1 rc
  title
  ui_header "$(t proto_test): $(t "proto_$id")"
  case "$id" in
    ssh)
      port="$(proto_port_value ssh)"
      if tcp_probe 127.0.0.1 "$port"; then sayf proto_test_ok "127.0.0.1:${port}/TCP"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    ws)
      port="$(proto_port_value ws)"
      if http_probe 127.0.0.1 "$port"; then sayf proto_test_ok "127.0.0.1:${port}/TCP-HTTP-WS"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    slowdns)
      for port in $(slowdns_ports); do
        if dns_probe 127.0.0.1 "$port" "$(env_get "$NANO_ETC_DIR/slowdns.env" SLOWDNS_DOMAIN 2>/dev/null || true)"; then
          sayf proto_test_ok "127.0.0.1:${port}/UDP"
        else
          sayf proto_test_fail "127.0.0.1:${port}/UDP"
          ok=0
        fi
      done
      ;;
    ssl)
      port="$(proto_port_value ssl)"
      tls_probe 127.0.0.1 "$port"
      rc=$?
      if [ "$rc" = "0" ]; then sayf proto_test_ok "127.0.0.1:${port}/TCP-TLS"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    hcr)
      port="$(proto_port_value hcr)"
      if tcp_probe 127.0.0.1 "$port"; then sayf proto_test_ok "127.0.0.1:${port}/TCP"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    bhttp)
      port="$(proto_port_value bhttp)"
      if tcp_probe 127.0.0.1 "$port"; then sayf proto_test_ok "127.0.0.1:${port}/TCP"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    hysteria)
      port="$(proto_port_value hysteria)"
      if [[ "$(port_state udp "$port")" == "yes" ]]; then sayf proto_test_ok "127.0.0.1:${port}/UDP"; else sayf proto_test_fail "127.0.0.1:${port}/UDP"; ok=0; fi
      ;;
    xray)
      for port in "$(xray_port_value XRAY_VMESS_PORT 10086)" "$(xray_port_value XRAY_VLESS_PORT 10087)" "$(xray_port_value XRAY_TROJAN_PORT 10088)"; do
        if [[ "$(port_state tcp "$port")" == yes ]]; then sayf proto_test_ok "127.0.0.1:${port}/TCP"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      done
      ;;
    dropbear)
      port="$(proto_port_value dropbear)"
      if [[ "$(port_state tcp "$port")" == yes ]]; then sayf proto_test_ok "127.0.0.1:${port}/TCP"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      ;;
    badvpn)
      for port in 7200 7300 7400; do
        if tcp_probe 127.0.0.1 "$port"; then sayf proto_test_ok "127.0.0.1:${port}/TCP-control-udpgw"; else sayf proto_test_fail "127.0.0.1:${port}/TCP"; ok=0; fi
      done
      ;;
    udp_custom)
      local range start
      range="$(env_get "$NANO_ETC_DIR/udp-custom.env" NANO_UDP_RANGE 2>/dev/null || true)"
      if [[ -z "$range" ]]; then
        say proto_not_configured
        pause
        return
      fi
      start="$(range_start "$range")"
      if [[ "$(port_state udp "$start")" == yes ]]; then
        sayf proto_test_ok "127.0.0.1:${start}/UDP"
      else
        sayf proto_test_fail "127.0.0.1:${start}/UDP"
        ok=0
      fi
      ;;
  esac
  line
  (( ok )) && say proto_action_done || say proto_action_fail
  pause
}

firewall_backend() {
  if have ufw && ufw status >/dev/null 2>&1; then
    printf 'ufw'
  elif have firewall-cmd && firewall-cmd --state >/dev/null 2>&1; then
    printf 'firewalld'
  elif have nft && nft list ruleset >/dev/null 2>&1; then
    printf 'nft'
  elif have iptables && iptables -S >/dev/null 2>&1; then
    printf 'iptables'
  fi
}

firewall_show() {
  local backend
  backend="$(firewall_backend)"
  if [[ -z "$backend" ]]; then
    say firewall_none
    return 1
  fi
  sayf firewall_tool "$backend"
  say firewall_readonly
  say firewall_rule_hint
  line
  case "$backend" in
    ufw) ufw status verbose 2>&1 | sed 's/^/  /' | ui_fold ;;
    firewalld)
      firewall-cmd --state 2>&1 | sed 's/^/  /' | ui_fold
      firewall-cmd --list-all 2>&1 | sed 's/^/  /' | ui_fold
      ;;
    nft) nft list ruleset 2>&1 | sed 's/^/  /' | ui_fold ;;
    iptables) iptables -S 2>&1 | sed 's/^/  /' | ui_fold ;;
  esac
  return 0
}

firewall_add_rule() {
  local proto="$1" ports="$2" backend ufw_spec ipt_spec
  is_root || { say modules_need_root; return 1; }
  backend="$(firewall_backend)"
  case "$backend" in
    ufw)
      ufw_spec="${ports}/${proto}"
      [[ "$ports" == *-* ]] && ufw_spec="${ports/-/:}/${proto}"
      ufw allow "$ufw_spec" >/dev/null 2>&1
      ;;
    firewalld)
      firewall-cmd --permanent --add-port="${ports}/${proto}" >/dev/null 2>&1 &&
        firewall-cmd --reload >/dev/null 2>&1
      ;;
    iptables)
      ipt_spec="${ports/-/:}"
      iptables -C INPUT -p "$proto" --dport "$ipt_spec" -j ACCEPT >/dev/null 2>&1 ||
        iptables -I INPUT -p "$proto" --dport "$ipt_spec" -j ACCEPT >/dev/null 2>&1
      ;;
    nft)
      say firewall_manual
      return 1
      ;;
    *)
      say firewall_none
      return 1
      ;;
  esac
}

firewall_remove_rule() {
  local proto="$1" ports="$2" backend ufw_spec ipt_spec
  is_root || { say modules_need_root; return 1; }
  backend="$(firewall_backend)"
  case "$backend" in
    ufw)
      ufw_spec="${ports}/${proto}"
      [[ "$ports" == *-* ]] && ufw_spec="${ports/-/:}/${proto}"
      ufw delete allow "$ufw_spec" >/dev/null 2>&1
      ;;
    firewalld)
      firewall-cmd --permanent --remove-port="${ports}/${proto}" >/dev/null 2>&1 &&
        firewall-cmd --reload >/dev/null 2>&1
      ;;
    iptables)
      ipt_spec="${ports/-/:}"
      iptables -D INPUT -p "$proto" --dport "$ipt_spec" -j ACCEPT >/dev/null 2>&1
      ;;
    nft)
      say firewall_manual
      return 1
      ;;
    *)
      say firewall_none
      return 1
      ;;
  esac
}

firewall_apply_specs() {
  local action="$1" id="$2" specs spec port proto list="" failed=0
  specs="$(proto_port_specs "$id")"
  if [[ -z "$specs" ]]; then
    say proto_not_configured
    pause
    return
  fi
  for spec in $specs; do
    port="${spec%/*}"
    proto="${spec#*/}"
    list="${list}${list:+, }${port}/${proto}"
  done
  if [[ "$action" == open ]]; then
    confirm "$(printf "$(t firewall_confirm_module_open)" "$list")" || { say cancelled; pause; return; }
  else
    confirm "$(printf "$(t firewall_confirm_module_close)" "$list")" || { say cancelled; pause; return; }
  fi
  for spec in $specs; do
    port="${spec%/*}"
    proto="${spec#*/}"
    if [[ "$action" == open ]]; then
      if firewall_add_rule "$proto" "$port"; then
        sayf firewall_added "$port" "$proto"
      else
        sayf firewall_failed
        failed=1
      fi
    else
      if firewall_remove_rule "$proto" "$port"; then
        sayf firewall_removed "$port" "$proto"
      else
        sayf firewall_failed
        failed=1
      fi
    fi
  done
  (( failed )) && say firewall_manual
  pause
}

firewall_manage_module() {
  local id="$1"
  while true; do
    title
    ui_header "$(t firewall_title)"
    say "proto_$id"
    sayf proto_ports "$(proto_ports_label "$id")"
    say firewall_intro
    line
    ui_menu "1|$(t firewall_open_module)" "2|$(t firewall_close_module)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) firewall_apply_specs open "$id" ;;
      2) firewall_apply_specs close "$id" ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

firewall_custom_udp() {
  local choice range start end span answer
  while true; do
    title
    ui_header "$(t firewall_udp_range_title)"
    sayf firewall_tool "$(firewall_backend)"
    say firewall_intro
    line
    ui_menu "1|$(t firewall_udp_range)" "2|$(t firewall_remove)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1)
        ui_prompt "$(t firewall_udp_range_prompt)"
        IFS= read -r range || range=""
        valid_udp_range "$range" || { say firewall_udp_bad; pause; continue; }
        start="$(range_start "$range")"
        end="$(range_end "$range")"
        span="$(range_span "$range")"
        if (( start == 1 && end == 65535 )); then
          say firewall_udp_full_warn
          ui_prompt "$(t firewall_udp_full_confirm)"
          IFS= read -r answer || answer=""
          case "${answer^^}" in
            TODOS|ALL) ;;
            *) say cancelled; pause; continue ;;
          esac
          sayf proto_udp_full_confirm "$span"
          confirm "$(t firewall_udp_range)" || { say cancelled; pause; continue; }
        else
          if (( span > NANO_UDP_FIREWALL_MAX_SPAN )); then
            sayf firewall_udp_max "$NANO_UDP_FIREWALL_MAX_SPAN"
            pause
            continue
          fi
          (( span > 256 )) && sayf firewall_udp_span_warn "$span"
          confirm "$(printf "$(t firewall_confirm_add)" "$range" "udp")" || { say cancelled; pause; continue; }
        fi
        if firewall_add_rule udp "$range"; then
          sayf firewall_udp_added "$range"
        else
          say firewall_failed
        fi
        pause
        ;;
      2)
        ui_prompt "$(t firewall_udp_range_prompt)"
        IFS= read -r range || range=""
        valid_udp_range "$range" || { say firewall_udp_bad; pause; continue; }
        confirm "$(printf "$(t firewall_confirm_remove)" "$range" "udp")" || { say cancelled; pause; continue; }
        if firewall_remove_rule udp "$range"; then
          sayf firewall_udp_removed "$range"
        else
          say firewall_failed
        fi
        pause
        ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

firewall_menu() {
  local port proto backend
  while true; do
    title
    ui_header "$(t firewall_title)"
    say firewall_intro
    backend="$(firewall_backend)"
    [[ -n "$backend" ]] || backend="$(t firewall_none)"
    sayf firewall_tool "$backend"
    line
    ui_menu "1|$(t firewall_list)" "2|$(t firewall_add)" "3|$(t firewall_remove)" \
      "4|$(t firewall_udp_range_title)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) firewall_show; pause ;;
      2)
        ui_prompt "$(t firewall_port_prompt)"
        IFS= read -r port || port=""
        valid_port "$port" || { say proto_bad_port; pause; continue; }
        ui_prompt "$(t firewall_proto_prompt)"
        IFS= read -r proto || proto=""
        [[ -n "$proto" ]] || proto=tcp
        proto="${proto,,}"
        [[ "$proto" == tcp || "$proto" == udp ]] || { say firewall_bad_proto; pause; continue; }
        confirm "$(printf "$(t firewall_confirm_add)" "$port" "$proto")" || { say cancelled; pause; continue; }
        if firewall_add_rule "$proto" "$port"; then sayf firewall_added "$port" "$proto"; else say firewall_failed; fi
        pause
        ;;
      3)
        ui_prompt "$(t firewall_port_prompt)"
        IFS= read -r port || port=""
        valid_port "$port" || { say proto_bad_port; pause; continue; }
        ui_prompt "$(t firewall_proto_prompt)"
        IFS= read -r proto || proto=""
        [[ -n "$proto" ]] || proto=tcp
        proto="${proto,,}"
        [[ "$proto" == tcp || "$proto" == udp ]] || { say firewall_bad_proto; pause; continue; }
        confirm "$(printf "$(t firewall_confirm_remove)" "$port" "$proto")" || { say cancelled; pause; continue; }
        if firewall_remove_rule "$proto" "$port"; then sayf firewall_removed "$port" "$proto"; else say firewall_failed; fi
        pause
        ;;
      4) firewall_custom_udp ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

proto_install_dispatch() {
  local id="$1"
  case "$id" in ssh|ws|slowdns|ssl|hcr|bhttp|hysteria|xray|dropbear|badvpn|udp_custom) ;; *) say invalid; return 1 ;; esac
  if (( IS_TERMUX )) || [[ "$(uname -s 2>/dev/null)" != Linux ]]; then
    say modules_linux_root; pause; return 1
  fi
  # Si el usuario entra desde una cuenta normal, elevar y reanudar exactamente
  # la instalación elegida; nunca instalar dependencias antes de obtener root.
  if ! is_root; then
    if have sudo; then
      NANO_ORIGINAL_ARGS=(--lang "${LANGUAGE:-es}" --install-protocol "$id")
      root_relaunch
    else
      say modules_need_root
      pause
    fi
    return 1
  fi
  if ! systemd_available; then say services_no_systemd; pause; return 1; fi
  if ! proto_install_preflight "$id"; then pause; return 1; fi
  if ! proto_selected_dependencies_ensure "$id"; then pause; return 1; fi
  case "$id" in
    ssh) proto_ssh_install ;;
    ws) proto_ws_install ;;
    slowdns) proto_slowdns_install ;;
    ssl) proto_ssl_install ;;
    hcr) modules_la_casita_install ;;
    bhttp) proto_bhttp_install ;;
    hysteria) proto_hysteria_install ;;
    xray) proto_xray_install ;;
    dropbear) proto_dropbear_install ;;
    badvpn) proto_badvpn_install ;;
    udp_custom) proto_udp_custom_install ;;
  esac
}

proto_uninstall_dispatch() {
  local id="$1" units
  if [[ "$id" == ssh ]]; then
    say proto_ssh_uninstall_denied
    pause
    return
  fi
  if [[ "$id" == hcr ]]; then
    modules_la_casita_uninstall
    return
  fi
  if [[ "$id" == xray ]]; then
    require_vps_root_systemd || { pause; return; }
    confirm "Stop Xray, remove its service and binary, and keep its configuration/credentials?" || { say cancelled; pause; return; }
    systemctl disable --now "$NANO_XRAY_UNIT" >/dev/null 2>&1 || true
    rm -f -- "$NANO_SYSTEMD_DIR/$NANO_XRAY_UNIT" "$NANO_XRAY_BIN"
    systemctl daemon-reload >/dev/null 2>&1 || true
    say proto_uninstalled
    sayf proto_keep_files "$NANO_XRAY_DIR"
    pause
    return
  fi
  require_vps_root_systemd || { pause; return; }
  confirm "$(printf "$(t proto_uninstall_confirm)" "$(t "proto_$id")")" || { say cancelled; pause; return; }
  units="$(proto_units "$id")"
  if [[ -z "$units" ]]; then
    say proto_not_installed
    pause
    return
  fi
  # shellcheck disable=SC2086
  remove_units $units
  sayf proto_keep_files "$NANO_OPT_DIR"
  pause
}

protocol_menu() {
  local id="$1"
  while true; do
    title
    ui_header "$(t "proto_$id")"
    say "proto_${id}_desc"
    line
    proto_overview "$id"
    line
    ui_menu "1|$(t proto_status)" "2|$(t proto_install)" "3|$(t proto_start)" \
      "4|$(t proto_stop)" "5|$(t proto_restart)" "6|$(t proto_test)" \
      "7|$(t proto_logs)" "8|$(t proto_firewall)" "9|$(t proto_uninstall)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) proto_status "$id" ;;
      2) proto_install_dispatch "$id" ;;
      3) proto_service_action "$id" start ;;
      4) proto_service_action "$id" stop ;;
      5) proto_service_action "$id" restart ;;
      6) proto_connectivity "$id" ;;
      7) proto_logs "$id" ;;
      8) firewall_manage_module "$id" ;;
      9) proto_uninstall_dispatch "$id" ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

proto_ssh_install() {
  local port=22 current_port target_unit answer config tmp backend need_firewall=0 ssh_pkg
  title
  ui_header "$(t proto_ssh)"
  say proto_ssh_desc
  line
  require_vps_root_systemd || { pause; return; }
  current_port="$(proto_port_value ssh)"
  if ! have sshd; then
    ssh_pkg="$(pm_map_package "$(detect_pm)" openssh-server)"
    sayf proto_dep_missing "$ssh_pkg"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages openssh-server || { sayf proto_install_fail "$(t proto_ssh)"; pause; return; }
  fi
  ui_prompt "$(printf "$(t proto_port_prompt2)" "$port")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && port="$answer"
  valid_port "$port" || { say proto_bad_port; pause; return; }
  if [[ "$port" != "$current_port" ]]; then
    sayf proto_ssh_remote_warn "$current_port" "$port"
    confirm "$(t proto_ssh_remote_confirm)" || { say cancelled; pause; return; }
    need_firewall=1
  fi
  target_unit="$(ssh_unit_name)"
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active "${target_unit}.service"; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  config="/etc/ssh/sshd_config"
  if [[ ! -f "$config" ]]; then
    say proto_config_fail
    pause
    return
  fi
  sayf proto_install_plan_generic "sshd_config: Port $port; systemctl restart ${target_unit}.service"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_ssh)")" || { say cancelled; pause; return; }
  if (( need_firewall )); then
    backend="$(firewall_backend)"
    if [[ -n "$backend" ]]; then
      sayf proto_ssh_firewall_auto "$port"
      if firewall_add_rule tcp "$port"; then
        sayf firewall_added "$port" tcp
      else
        sayf proto_ssh_firewall_manual "$port"
        confirm "$(t proto_ssh_firewall_confirm)" || { say cancelled; pause; return; }
      fi
    else
      sayf proto_ssh_firewall_manual "$port"
      confirm "$(t proto_ssh_firewall_confirm)" || { say cancelled; pause; return; }
    fi
  fi
  backup_file "$config" || { say proto_config_fail; pause; return; }
  tmp="$(mktemp /etc/ssh/.nano-sshd.XXXXXX)" || { say proto_config_fail; pause; return; }
  awk -v port="$port" '
    BEGIN { written = 0 }
    /^[[:space:]]*#?[[:space:]]*Port[[:space:]]+/ {
      if (!written) { print "Port " port; written = 1 }
      next
    }
    { print }
    END { if (!written) print "Port " port }
  ' "$config" > "$tmp"
  chmod 0644 -- "$tmp" 2>/dev/null || true
  if have sshd && ! sshd -t -f "$tmp" 2>/dev/null; then
    rm -f -- "$tmp"
    say proto_config_fail
    pause
    return
  fi
  mv -f -- "$tmp" "$config" || { rm -f -- "$tmp"; say proto_config_fail; pause; return; }
  sayf proto_config_ok "$config"
  systemctl enable "${target_unit}.service" >/dev/null 2>&1 || true
  if ! systemctl restart "${target_unit}.service"; then
    sayf proto_install_fail "$(t proto_ssh)"
    pause
    return
  fi
  sleep 1
  if service_active "${target_unit}.service" && tcp_probe 127.0.0.1 "$port"; then
    sayf proto_install_ok "$(t proto_ssh)"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_ssh)"
  fi
  pause
}

ws_tunnel_source() {
  cat <<'NANO_WS_PY'
#!/usr/bin/env python3
"""Nano Panel - WebSocket to TCP tunnel stdlib only."""
import argparse
import asyncio
import base64
import hashlib
import os
import signal
import struct
import sys

GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
MAX_FRAME = 8 * 1024 * 1024
MAX_HEADER = 16384


def log(message):
    print("nano-ws: %s" % message, file=sys.stderr, flush=True)


def parse_addr(value, default_port):
    value = (value or "").strip()
    if not value:
        raise ValueError("empty address")
    if value.startswith("["):
        host, sep, rest = value[1:].partition("]")
        if not sep:
            raise ValueError("invalid IPv6 address")
        port = rest[1:] if rest.startswith(":") else str(default_port)
    elif value.count(":") == 1:
        host, port = value.rsplit(":", 1)
    elif ":" in value:
        host, port = value, str(default_port)
    else:
        host, port = value, str(default_port)
    if not host:
        host = "0.0.0.0"
    port_num = int(port)
    if port_num < 1 or port_num > 65535:
        raise ValueError("invalid port")
    return host, port_num


async def send_http(writer, status, body=b""):
    headers = [
        "HTTP/1.1 %s" % status,
        "Connection: close",
        "Content-Type: text/plain; charset=utf-8",
        "Content-Length: %d" % len(body),
        "",
        "",
    ]
    writer.write(("\r\n".join(headers)).encode("ascii") + body)
    try:
        await writer.drain()
    except Exception:
        pass


async def read_frame(reader):
    head = await reader.readexactly(2)
    first, second = head[0], head[1]
    fin = bool(first & 0x80)
    opcode = first & 0x0F
    masked = bool(second & 0x80)
    length = second & 0x7F
    if length == 126:
        length = struct.unpack("!H", await reader.readexactly(2))[0]
    elif length == 127:
        length = struct.unpack("!Q", await reader.readexactly(8))[0]
    if length > MAX_FRAME:
        raise ValueError("frame too large")
    mask = await reader.readexactly(4) if masked else b""
    payload = await reader.readexactly(length) if length else b""
    if masked:
        payload = bytes(value ^ mask[index % 4] for index, value in enumerate(payload))
    return fin, opcode, masked, payload


def frame_bytes(opcode, payload):
    length = len(payload)
    if length < 126:
        header = bytes([0x80 | opcode, length])
    elif length < 65536:
        header = bytes([0x80 | opcode, 126]) + struct.pack("!H", length)
    else:
        header = bytes([0x80 | opcode, 127]) + struct.pack("!Q", length)
    return header + payload


async def send_frame(writer, opcode, payload=b""):
    writer.write(frame_bytes(opcode, payload))
    await writer.drain()


async def handle_client(reader, writer, target_host, target_port):
    target_writer = None
    try:
        try:
            request = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout=10)
        except (asyncio.IncompleteReadError, asyncio.LimitOverrunError, asyncio.TimeoutError):
            await send_http(writer, "400 Bad Request", b"bad request\n")
            writer.close()
            return
        if len(request) > MAX_HEADER:
            await send_http(writer, "431 Request Header Fields Too Large")
            writer.close()
            return
        lines = request.decode("latin-1", "replace").split("\r\n")
        headers = {}
        for line in lines[1:]:
            if not line:
                continue
            name, sep, value = line.partition(":")
            if sep:
                headers[name.strip().lower()] = value.strip()
        upgrade = headers.get("upgrade", "").lower()
        connection = headers.get("connection", "").lower()
        key = headers.get("sec-websocket-key", "")
        if upgrade != "websocket" or "upgrade" not in connection or not key:
            await send_http(writer, "426 Upgrade Required", b"websocket required\n")
            writer.close()
            return
        target_reader, target_writer = await asyncio.wait_for(
            asyncio.open_connection(target_host, target_port), timeout=10
        )
        accept = base64.b64encode(hashlib.sha1((key + GUID).encode("ascii")).digest()).decode("ascii")
        response = (
            "HTTP/1.1 101 Switching Protocols\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Accept: %s\r\n"
            "\r\n" % accept
        )
        writer.write(response.encode("ascii"))
        await writer.drain()
    except Exception as exc:
        log("handshake/target error: %s" % exc)
        await send_http(writer, "502 Bad Gateway", b"upstream unavailable\n")
        writer.close()
        return

    async def client_to_target():
        fragmented_opcode = None
        fragment = bytearray()
        while True:
            fin, opcode, masked, payload = await read_frame(reader)
            if not masked:
                raise ValueError("client frame is not masked")
            if opcode == 0x8:
                try:
                    await send_frame(writer, 0x8, payload[:125])
                except Exception:
                    pass
                return
            if opcode == 0x9:
                await send_frame(writer, 0xA, payload[:125])
                continue
            if opcode == 0xA:
                continue
            if opcode in (0x1, 0x2):
                if fragmented_opcode is not None:
                    raise ValueError("nested data frame")
                fragmented_opcode = opcode
                fragment = bytearray(payload)
            elif opcode == 0x0:
                if fragmented_opcode is None:
                    raise ValueError("unexpected continuation")
                fragment.extend(payload)
            else:
                raise ValueError("unsupported opcode")
            if fin:
                if fragment:
                    target_writer.write(fragment)
                    await target_writer.drain()
                fragment = bytearray()
                fragmented_opcode = None

    async def target_to_client():
        while True:
            data = await target_reader.read(65536)
            if not data:
                try:
                    await send_frame(writer, 0x8, b"\x03\xe8")
                except Exception:
                    pass
                return
            await send_frame(writer, 0x2, data)

    tasks = [asyncio.create_task(client_to_target()), asyncio.create_task(target_to_client())]
    try:
        done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
        for task in pending:
            task.cancel()
        for task in done:
            exc = task.exception()
            if exc and not isinstance(exc, (asyncio.IncompleteReadError, ConnectionError, ValueError)):
                log("tunnel error: %s" % exc)
    finally:
        for task in tasks:
            if not task.done():
                task.cancel()
        try:
            target_writer.close()
            await target_writer.wait_closed()
        except Exception:
            pass
        try:
            writer.close()
            await writer.wait_closed()
        except Exception:
            pass


async def main_async(args):
    listen_host, listen_port = parse_addr(
        args.listen or os.environ.get("NANO_WS_LISTEN", "0.0.0.0:80"), 80
    )
    target_host, target_port = parse_addr(
        args.target or os.environ.get("NANO_WS_TARGET", "127.0.0.1:22"), 22
    )
    server = await asyncio.start_server(
        lambda r, w: handle_client(r, w, target_host, target_port),
        host=listen_host,
        port=listen_port,
        limit=MAX_HEADER,
    )
    log("listening on %s:%d, target %s:%d" % (listen_host, listen_port, target_host, target_port))
    stop = asyncio.Event()
    loop = asyncio.get_running_loop()
    for sig in (signal.SIGTERM, signal.SIGINT):
        try:
            loop.add_signal_handler(sig, stop.set)
        except (NotImplementedError, RuntimeError):
            pass
    async with server:
        await stop.wait()
    log("stopped")


def main():
    parser = argparse.ArgumentParser(description="WebSocket to TCP tunnel")
    parser.add_argument("--listen")
    parser.add_argument("--target")
    args = parser.parse_args()
    try:
        asyncio.run(main_async(args))
    except KeyboardInterrupt:
        return 0
    except Exception as exc:
        log("fatal: %s" % exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

NANO_WS_PY
}

proto_ws_install() {
  local port=80 target="127.0.0.1:22" answer python_bin dest dir tmp unit_content
  title
  ui_header "$(t proto_ws)"
  say proto_ws_desc
  line
  require_vps_root_systemd || { pause; return; }
  if ! have python3; then
    sayf proto_dep_missing "python3"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages python3 || { say proto_requires_python; pause; return; }
  fi
  python_bin="$(command -v python3)"
  ui_prompt "$(printf "$(t proto_port_prompt2)" "$port")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && port="$answer"
  valid_port "$port" || { say proto_bad_port; pause; return; }
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active nano-ws.service; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  ui_prompt "$(printf "$(t proto_target_prompt)" "$target")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && target="$answer"
  valid_target "$target" || { say proto_bad_target; pause; return; }
  sayf proto_install_plan_generic "python3 ws_tunnel.py listen 0.0.0.0:${port} target ${target}"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_ws)")" || { say cancelled; pause; return; }
  dir="$NANO_OPT_DIR/ws"
  dest="$dir/ws_tunnel.py"
  install -d -m 0755 -- "$dir" || { sayf proto_install_fail "$(t proto_ws)"; pause; return; }
  tmp="$(mktemp "${dir}/.ws.XXXXXX")" || { sayf proto_install_fail "$(t proto_ws)"; pause; return; }
  ws_tunnel_source > "$tmp"
  if ! "$python_bin" -m py_compile "$tmp" >/dev/null 2>&1; then
    rm -f -- "$tmp"
    sayf proto_install_fail "$(t proto_ws)"
    pause
    return
  fi
  install -m 0755 -- "$tmp" "$dest"
  rm -f -- "$tmp"
  write_config_file "$NANO_ETC_DIR/ws.env" 0640 "NANO_WS_LISTEN=0.0.0.0:${port}
NANO_WS_TARGET=${target}" || { say proto_config_fail; pause; return; }
  unit_content="$(cat <<UNIT
[Unit]
Description=Nano VPS WebSocket tunnel
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=-$NANO_ETC_DIR/ws.env
ExecStart=$python_bin $dest
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=4096
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content nano-ws.service "$unit_content" || { sayf proto_install_fail "$(t proto_ws)"; pause; return; }
  systemctl enable --now nano-ws.service >/dev/null 2>&1 || true
  systemctl restart nano-ws.service >/dev/null 2>&1 || true
  sleep 1
  if service_active nano-ws.service && [[ "$(port_state tcp "$port")" == yes ]]; then
    sayf proto_install_ok "$(t proto_ws)"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_ws)"
  fi
  pause
}

proto_slowdns_install() {
  local source_binary binary_arch_name ports="53 5300" answer domain upstream
  local dir port key pub unit_content
  title
  ui_header "$(t proto_slowdns)"
  say proto_slowdns_desc
  line
  require_vps_root_systemd || { pause; return; }
  if [[ -z "${NANO_SOURCE_DIR:-}" ]]; then
    payload_ensure || { pause; return; }
  fi
  source_binary="$(nano_source_dir)/SLOWDNS/dns-server"
  if [[ ! -f "$source_binary" ]]; then
    sayf proto_source_missing "$source_binary"
    pause
    return
  fi
  binary_arch_name="$(binary_arch "$source_binary" 2>/dev/null || true)"
  if [[ "$binary_arch_name" != "$(host_arch_family)" ]]; then
    sayf proto_arch_bad "${binary_arch_name:-$(t unknown)}" "$(host_arch)"
    pause
    return
  fi
  sayf proto_source "$source_binary"
  verify_hash "$source_binary" "$NANO_SLOWDNS_SHA256" || { pause; return; }
  ui_prompt "$(printf "$(t proto_ports_prompt)" "$ports")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && ports="$answer"
  for port in $ports; do
    valid_port "$port" || { say proto_bad_ports; pause; return; }
    if [[ "$(port_state udp "$port")" == yes ]]; then
      sayf proto_port_in_use "$port" udp
      pause
      return
    fi
  done
  ui_prompt "$(t proto_domain_prompt)"
  IFS= read -r domain || domain=""
  valid_domain "$domain" || { say proto_bad_domain; pause; return; }
  ui_prompt "$(printf "$(t proto_upstream_prompt)" "127.0.0.1:22")"
  IFS= read -r upstream || upstream=""
  [[ -n "$upstream" ]] || upstream="127.0.0.1:22"
  valid_target "$upstream" || { say proto_bad_target; pause; return; }
  sayf proto_install_plan_generic "dnstt-server -udp 0.0.0.0:PORT -privkey-file server.key ${domain} ${upstream}"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_slowdns)")" || { say cancelled; pause; return; }
  dir="$NANO_OPT_DIR/slowdns"
  install -d -m 0755 -- "$dir" || { sayf proto_install_fail "$(t proto_slowdns)"; pause; return; }
  install -m 0755 -- "$source_binary" "$dir/dns-server" || { sayf proto_install_fail "$(t proto_slowdns)"; pause; return; }
  key="$dir/server.key"
  pub="$dir/server.pub"
  if [[ ! -s "$key" || ! -s "$pub" ]]; then
    if ! "$dir/dns-server" -gen-key -privkey-file "$key" -pubkey-file "$pub" >/dev/null 2>&1; then
      sayf proto_install_fail "$(t proto_slowdns)"
      pause
      return
    fi
    chmod 0600 -- "$key" 2>/dev/null || true
    chmod 0644 -- "$pub" 2>/dev/null || true
  fi
  write_config_file "$NANO_ETC_DIR/slowdns.env" 0640 "SLOWDNS_DOMAIN=${domain}
SLOWDNS_UPSTREAM=${upstream}
SLOWDNS_PORTS=${ports}
SLOWDNS_KEY=${key}" || { say proto_config_fail; pause; return; }
  unit_content="$(cat <<'UNIT'
[Unit]
Description=Nano VPS SlowDNS %i
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=/etc/nano-vps/slowdns.env
ExecStart=/opt/nano-vps/slowdns/dns-server -udp 0.0.0.0:%i -privkey-file ${SLOWDNS_KEY} ${SLOWDNS_DOMAIN} ${SLOWDNS_UPSTREAM}
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6
LimitNOFILE=4096
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content 'nano-slowdns@.service' "$unit_content" || { sayf proto_install_fail "$(t proto_slowdns)"; pause; return; }
  for port in $ports; do
    systemctl enable --now "nano-slowdns@${port}.service" >/dev/null 2>&1 || true
  done
  sleep 1
  if service_active "nano-slowdns@$(echo $ports | awk '{print $1}').service"; then
    sayf proto_install_ok "$(t proto_slowdns)"
    sayf proto_public_key "$(tr -d '\n' < "$pub" 2>/dev/null)"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_slowdns)"
  fi
  pause
}

proto_ssl_install() {
  local port=443 target="127.0.0.1:22" answer stunnel_bin cert key dir config unit_content
  title
  ui_header "$(t proto_ssl)"
  say proto_ssl_desc
  line
  require_vps_root_systemd || { pause; return; }
  if ! have stunnel && ! have stunnel4; then
    sayf proto_dep_missing "stunnel"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages stunnel4 || pm_install_packages stunnel || { say proto_requires_stunnel; pause; return; }
  fi
  stunnel_bin="$(command -v stunnel 2>/dev/null || command -v stunnel4 2>/dev/null)"
  [[ -n "$stunnel_bin" ]] || { say proto_requires_stunnel; pause; return; }
  if ! have openssl; then
    sayf proto_dep_missing "openssl"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages openssl || { say proto_cert_fail; pause; return; }
  fi
  ui_prompt "$(printf "$(t proto_port_prompt2)" "$port")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && port="$answer"
  valid_port "$port" || { say proto_bad_port; pause; return; }
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active nano-ssl.service; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  ui_prompt "$(printf "$(t proto_target_prompt)" "$target")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && target="$answer"
  valid_target "$target" || { say proto_bad_target; pause; return; }
  dir="$NANO_ETC_DIR/ssl"
  cert="$dir/fullchain.pem"
  key="$dir/privkey.pem"
  sayf proto_install_plan_generic "${stunnel_bin} TLS 0.0.0.0:${port} -> ${target}"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_ssl)")" || { say cancelled; pause; return; }
  install -d -m 0755 -- "$dir" "$NANO_ETC_DIR" || { sayf proto_install_fail "$(t proto_ssl)"; pause; return; }
  if [[ ! -s "$cert" || ! -s "$key" ]]; then
    say proto_generate_cert_q
    confirm "$(t proto_generate_cert_q)" || { say cancelled; pause; return; }
    if ! openssl req -x509 -newkey rsa:2048 -sha256 -nodes -days 825 \
      -subj "/CN=nano-vps" -keyout "$key" -out "$cert" >/dev/null 2>&1; then
      say proto_cert_fail
      pause
      return
    fi
    chmod 0644 -- "$cert" 2>/dev/null || true
    chmod 0600 -- "$key" 2>/dev/null || true
    sayf proto_cert_created "$dir"
  fi
  config="$NANO_ETC_DIR/stunnel.conf"
  backup_file "$config" || true
  write_config_file "$config" 0640 "foreground = yes
syslog = no
debug = 4

[nano-ssl]
accept = 0.0.0.0:${port}
connect = ${target}
cert = ${cert}
key = ${key}" || { say proto_config_fail; pause; return; }
  unit_content="$(cat <<UNIT
[Unit]
Description=Nano VPS SSL tunnel
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$stunnel_bin $config
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=4096
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content nano-ssl.service "$unit_content" || { sayf proto_install_fail "$(t proto_ssl)"; pause; return; }
  systemctl enable --now nano-ssl.service >/dev/null 2>&1 || true
  systemctl restart nano-ssl.service >/dev/null 2>&1 || true
  sleep 1
  if service_active nano-ssl.service && tls_probe 127.0.0.1 "$port"; then
    sayf proto_install_ok "$(t proto_ssl)"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_ssl)"
  fi
  pause
}

read_secret() {
  local var="$1" rc
  if [[ -t 0 ]] && command -v stty >/dev/null 2>&1; then
    stty -echo 2>/dev/null || true
    ui_read_line "$var"
    rc=$?
    stty echo 2>/dev/null || true
    printf '\n'
  else
    ui_read_line "$var"
    rc=$?
  fi
  return "$rc"
}

bhttp_proxy_source() {
  cat <<'NANO_BHTTP_PY'
#!/usr/bin/env python3
"""Nano Panel - HTTP CONNECT tunnel -stdlib-only."""
import argparse
import asyncio
import base64
import os
import signal
import sys

MAX_HEADER = 16384


def log(message):
    print("nano-bhttp: %s" % message, file=sys.stderr, flush=True)


def parse_addr(value, default_port):
    value = (value or "").strip()
    if not value:
        raise ValueError("empty address")
    if value.startswith("["):
        host, sep, rest = value[1:].partition("]")
        if not sep:
            raise ValueError("invalid IPv6 address")
        port = rest[1:] if rest.startswith(":") else str(default_port)
    elif value.count(":") == 1:
        host, port = value.rsplit(":", 1)
    elif ":" in value:
        host, port = value, str(default_port)
    else:
        host, port = value, str(default_port)
    if not host:
        raise ValueError("missing host")
    port_num = int(port)
    if port_num < 1 or port_num > 65535:
        raise ValueError("invalid port")
    return host, port_num


def parse_target(value):
    if value.startswith("["):
        host, sep, rest = value[1:].partition("]")
        if not sep or not rest.startswith(":"):
            raise ValueError("invalid IPv6 target")
        port = int(rest[1:])
    else:
        host, sep, port_text = value.rpartition(":")
        if not sep:
            raise ValueError("missing target port")
        port = int(port_text)
    if not host or port < 1 or port > 65535:
        raise ValueError("invalid target")
    return host, port


async def send_response(writer, status, extra_headers=None, body=b""):
    headers = ["HTTP/1.1 %s" % status, "Connection: close"]
    if extra_headers:
        headers.extend(extra_headers)
    headers.extend([
        "Content-Type: text/plain; charset=utf-8",
        "Content-Length: %d" % len(body),
        "",
        "",
    ])
    try:
        writer.write(("\r\n".join(headers)).encode("ascii") + body)
        await writer.drain()
    except Exception:
        pass


async def relay(reader, writer):
    try:
        while True:
            data = await reader.read(65536)
            if not data:
                break
            writer.write(data)
            await writer.drain()
    except (ConnectionError, asyncio.IncompleteReadError):
        pass
    finally:
        try:
            writer.write_eof()
        except Exception:
            pass


async def handle_client(reader, writer, required_auth):
    target_writer = None
    try:
        try:
            raw = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout=15)
        except (asyncio.IncompleteReadError, asyncio.LimitOverrunError, asyncio.TimeoutError):
            await send_response(writer, "400 Bad Request", body=b"bad request\n")
            writer.close()
            return
        if len(raw) > MAX_HEADER:
            await send_response(writer, "431 Request Header Fields Too Large")
            writer.close()
            return
        lines = raw.decode("latin-1", "replace").split("\r\n")
        request_line = lines[0].split()
        if len(request_line) < 2 or request_line[0].upper() != "CONNECT":
            await send_response(writer, "405 Method Not Allowed", body=b"CONNECT only\n")
            writer.close()
            return
        headers = {}
        for line in lines[1:]:
            if not line:
                continue
            name, sep, value = line.partition(":")
            if sep:
                headers[name.strip().lower()] = value.strip()
        if required_auth:
            provided = headers.get("proxy-authorization", "")
            expected = "Basic " + required_auth
            if provided != expected:
                await send_response(
                    writer,
                    "407 Proxy Authentication Required",
                    ["Proxy-Authenticate: Basic realm=\"Nano VPS\""],
                    b"authentication required\n",
                )
                writer.close()
                return
        host, port = parse_target(request_line[1])
        target_reader, target_writer = await asyncio.wait_for(
            asyncio.open_connection(host, port), timeout=15
        )
        writer.write(b"HTTP/1.1 200 Connection Established\r\n\r\n")
        await writer.drain()
    except Exception as exc:
        log("connect error: %s" % exc)
        await send_response(writer, "502 Bad Gateway", body=b"upstream unavailable\n")
        writer.close()
        return

    tasks = [
        asyncio.create_task(relay(reader, target_writer)),
        asyncio.create_task(relay(target_reader, writer)),
    ]
    try:
        await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
    finally:
        for task in tasks:
            if not task.done():
                task.cancel()
        for stream in (target_writer, writer):
            try:
                stream.close()
                await stream.wait_closed()
            except Exception:
                pass


async def main_async(args):
    listen_host, listen_port = parse_addr(
        args.listen or os.environ.get("NANO_BHTTP_LISTEN", "0.0.0.0:8880"), 8880
    )
    user = args.user if args.user is not None else os.environ.get("NANO_BHTTP_USER", "")
    password = args.password if args.password is not None else os.environ.get("NANO_BHTTP_PASSWORD", "")
    if bool(user) != bool(password):
        raise ValueError("user and password must be set together")
    required_auth = ""
    if user:
        required_auth = base64.b64encode(("%s:%s" % (user, password)).encode("utf-8")).decode("ascii")
    server = await asyncio.start_server(
        lambda r, w: handle_client(r, w, required_auth),
        host=listen_host,
        port=listen_port,
        limit=MAX_HEADER,
    )
    log("listening on %s:%d, auth %s" % (listen_host, listen_port, "on" if required_auth else "off"))
    stop = asyncio.Event()
    loop = asyncio.get_running_loop()
    for sig in (signal.SIGTERM, signal.SIGINT):
        try:
            loop.add_signal_handler(sig, stop.set)
        except (NotImplementedError, RuntimeError):
            pass
    async with server:
        await stop.wait()
    log("stopped")


def main():
    parser = argparse.ArgumentParser(description="HTTP CONNECT tunnel")
    parser.add_argument("--listen")
    parser.add_argument("--user")
    parser.add_argument("--password")
    args = parser.parse_args()
    try:
        asyncio.run(main_async(args))
    except KeyboardInterrupt:
        return 0
    except Exception as exc:
        log("fatal: %s" % exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

NANO_BHTTP_PY
}

proto_bhttp_install() {
  local port=8880 answer user pass python_bin dir dest tmp unit_content
  title
  ui_header "$(t proto_bhttp)"
  say proto_bhttp_desc
  line
  require_vps_root_systemd || { pause; return; }
  if ! have python3; then
    sayf proto_dep_missing "python3"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages python3 || { say proto_requires_python; pause; return; }
  fi
  python_bin="$(command -v python3)"
  ui_prompt "$(printf "$(t proto_port_prompt2)" "$port")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && port="$answer"
  valid_port "$port" || { say proto_bad_port; pause; return; }
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active nano-bhttp.service; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  ui_prompt "$(t proto_bhttp_user_prompt)"
  IFS= read -r user || user=""
  pass=""
  if [[ -n "$user" ]]; then
    if [[ ! "$user" =~ ^[A-Za-z0-9._~!@%+=:-]{1,64}$ ]]; then
      say proto_bhttp_bad_auth
      pause
      return
    fi
    ui_prompt "$(t proto_bhttp_pass_prompt)"
    read_secret pass || pass=""
    if [[ ! "$pass" =~ ^[A-Za-z0-9._~!@%+=:-]{1,128}$ ]]; then
      say proto_bhttp_bad_auth
      pause
      return
    fi
  else
    sayf proto_bhttp_no_auth_warn "$port"
  fi
  sayf proto_install_plan_generic "python3 bhttp_proxy.py listen 0.0.0.0:${port}"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_bhttp)")" || { say cancelled; pause; return; }
  dir="$NANO_OPT_DIR/bhttp"
  dest="$dir/bhttp_proxy.py"
  install -d -m 0755 -- "$dir" || { sayf proto_install_fail "$(t proto_bhttp)"; pause; return; }
  tmp="$(mktemp "${dir}/.bhttp.XXXXXX")" || { sayf proto_install_fail "$(t proto_bhttp)"; pause; return; }
  bhttp_proxy_source > "$tmp"
  if ! "$python_bin" -m py_compile "$tmp" >/dev/null 2>&1; then
    rm -f -- "$tmp"
    sayf proto_install_fail "$(t proto_bhttp)"
    pause
    return
  fi
  install -m 0755 -- "$tmp" "$dest"
  rm -f -- "$tmp"
  write_config_file "$NANO_ETC_DIR/bhttp.env" 0600 "NANO_BHTTP_LISTEN=0.0.0.0:${port}
NANO_BHTTP_USER=${user}
NANO_BHTTP_PASSWORD=${pass}" || { say proto_config_fail; pause; return; }
  unit_content="$(cat <<UNIT
[Unit]
Description=Nano VPS BHTTP CONNECT proxy
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=-$NANO_ETC_DIR/bhttp.env
ExecStart=$python_bin $dest
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=4096
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content nano-bhttp.service "$unit_content" || { sayf proto_install_fail "$(t proto_bhttp)"; pause; return; }
  systemctl enable --now nano-bhttp.service >/dev/null 2>&1 || true
  systemctl restart nano-bhttp.service >/dev/null 2>&1 || true
  sleep 1
  if service_active nano-bhttp.service && [[ "$(port_state tcp "$port")" == yes ]]; then
    sayf proto_install_ok "$(t proto_bhttp)"
    [[ -z "$user" ]] && sayf proto_bhttp_no_auth_warn "$port"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_bhttp)"
  fi
  pause
}

proto_badvpn_install() {
  local source_zip source_root build_dir byteorder port udpgw unit_content package_list
  title
  ui_header "$(t proto_badvpn)"
  say proto_badvpn_desc
  line
  require_vps_root_systemd || { pause; return; }
  if [[ -z "${NANO_SOURCE_DIR:-}" ]]; then
    payload_ensure || { pause; return; }
  fi
  if ! have getconf || ! getconf GNU_LIBC_VERSION 2>/dev/null | grep -q 'glibc'; then
    say proto_badvpn_glibc
    pause
    return
  fi
  source_zip="$(nano_source_dir)/test/badvpn-master.zip"
  if [[ ! -f "$source_zip" ]]; then
    sayf proto_source_missing "$source_zip"
    pause
    return
  fi
  sayf proto_source "$source_zip"
  verify_hash "$source_zip" "$NANO_BADVPN_ZIP_SHA256" || { pause; return; }
  if ! have gcc || ! have make || ! have unzip; then
    case "$(detect_pm)" in
      apt) package_list="build-essential unzip" ;;
      dnf|yum|zypper) package_list="gcc make cmake unzip" ;;
      pacman) package_list="base-devel cmake unzip" ;;
      apk) package_list="build-base cmake unzip" ;;
      *) package_list="gcc make cmake unzip" ;;
    esac
    sayf proto_dep_missing "$package_list"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    local -a build_packages=()
    read -r -a build_packages <<< "$package_list"
    pm_install_packages "${build_packages[@]}" || { say proto_badvpn_build_fail; pause; return; }
  fi
  say proto_badvpn_build_plan
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_badvpn)")" || { say cancelled; pause; return; }
  install -d -m 0755 -- "$NANO_OPT_DIR/badvpn/src" "$NANO_OPT_DIR/badvpn/build" "$NANO_LOG_DIR" || { say proto_badvpn_build_fail; pause; return; }
  source_root="$NANO_OPT_DIR/badvpn/src/badvpn-master"
  if [[ ! -f "$source_root/compile-udpgw.sh" ]]; then
    if ! unzip -q -o "$source_zip" -d "$NANO_OPT_DIR/badvpn/src" >/dev/null 2>&1; then
      say proto_badvpn_build_fail
      pause
      return
    fi
  fi
  byteorder="$(python3 -c 'import sys; print(sys.byteorder)' 2>/dev/null || printf 'little')"
  build_dir="$NANO_OPT_DIR/badvpn/build"
  if ! ( cd "$build_dir" && SRCDIR="$source_root" CC=gcc CFLAGS="-O2" LDFLAGS="" ENDIAN="$byteorder" KERNEL=2.6 bash "$source_root/compile-udpgw.sh" ) >"$NANO_LOG_DIR/badvpn-build.log" 2>&1; then
    say proto_badvpn_build_fail
    tail -n 25 "$NANO_LOG_DIR/badvpn-build.log" 2>/dev/null | sed 's/^/  /' | ui_fold
    pause
    return
  fi
  if [[ ! -x "$build_dir/udpgw" ]]; then
    say proto_badvpn_build_fail
    pause
    return
  fi
  install -m 0755 -- "$build_dir/udpgw" "$NANO_OPT_DIR/badvpn/udpgw" || { say proto_badvpn_build_fail; pause; return; }
  say proto_badvpn_build_ok
  unit_content="$(cat <<UNIT
[Unit]
Description=Nano VPS BadVPN UDPGW %i
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$NANO_OPT_DIR/badvpn/udpgw --listen-addr 0.0.0.0:%i --max-clients 512 --max-connections-for-client 512 --loglevel warning
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=8192
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content 'nano-udpgw@.service' "$unit_content" || { sayf proto_install_fail "$(t proto_badvpn)"; pause; return; }
  for port in 7200 7300 7400; do
    systemctl enable --now "nano-udpgw@${port}.service" >/dev/null 2>&1 || true
  done
  sleep 1
  if service_active nano-udpgw@7200.service; then
    sayf proto_install_ok "$(t proto_badvpn)"
    say proto_badvpn_tcp_note
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_badvpn)"
  fi
  pause
}

udp_forwarder_source() {
  cat <<'NANO_UDP_PY'
#!/usr/bin/env python3
"""Nano Panel - bounded UDP port range forwarder."""
import argparse
import asyncio
import os
import signal
import sys
import time

MAX_PORTS = 4096
IDLE_SECONDS = 120


def log(message):
    print("nano-udp: %s" % message, file=sys.stderr, flush=True)


def parse_range(value):
    text = (value or "").strip()
    if "-" in text:
        start_text, end_text = text.split("-", 1)
    else:
        start_text = end_text = text
    try:
        start = int(start_text)
        end = int(end_text)
    except ValueError:
        raise ValueError("invalid range")
    if start < 1 or end > 65535 or start > end:
        raise ValueError("invalid range")
    return start, end


def parse_target(value):
    text = (value or "").strip()
    if not text:
        raise ValueError("empty target")
    if text.startswith("["):
        host, sep, rest = text[1:].partition("]")
        if not sep or not rest.startswith(":"):
            raise ValueError("invalid target")
        port = int(rest[1:])
    else:
        host, sep, port_text = text.rpartition(":")
        if not sep:
            raise ValueError("target must be host:port")
        port = int(port_text)
    if not host or port < 1 or port > 65535:
        raise ValueError("invalid target")
    return host, port


class TargetProtocol(asyncio.DatagramProtocol):
    def __init__(self, listener, client_addr, client_key):
        self.listener = listener
        self.client_addr = client_addr
        self.client_key = client_key
        self.transport = None
        self.last_seen = time.monotonic()

    def connection_made(self, transport):
        self.transport = transport

    def datagram_received(self, data, addr):
        self.last_seen = time.monotonic()
        try:
            self.listener.transport.sendto(data, self.client_addr)
        except Exception:
            self.listener.drop_client(self.client_key)

    def error_received(self, exc):
        log("target error: %s" % exc)

    def connection_lost(self, exc):
        if exc:
            log("target connection lost: %s" % exc)


class ListenerProtocol(asyncio.DatagramProtocol):
    def __init__(self, local_port, target_host, target_port):
        self.local_port = local_port
        self.target_host = target_host
        self.target_port = target_port
        self.transport = None
        self.clients = {}

    def connection_made(self, transport):
        self.transport = transport

    def datagram_received(self, data, addr):
        key = (addr[0], addr[1])
        entry = self.clients.get(key)
        if entry is None:
            entry = {"task": None, "protocol": None, "pending": [data]}
            self.clients[key] = entry
            entry["task"] = asyncio.create_task(self._connect(key))
            return
        proto = entry["protocol"]
        if proto is not None and proto.transport is not None:
            proto.last_seen = time.monotonic()
            try:
                proto.transport.sendto(data)
            except Exception:
                self.drop_client(key)
        else:
            entry.setdefault("pending", []).append(data)

    async def _connect(self, key):
        try:
            transport, proto = await asyncio.get_running_loop().create_datagram_endpoint(
                lambda: TargetProtocol(self, key, key),
                remote_addr=(self.target_host, self.target_port),
            )
        except Exception as exc:
            log("cannot open target for %s:%d: %s" % (key[0], key[1], exc))
            self.clients.pop(key, None)
            return
        entry = self.clients.get(key)
        if entry is None:
            transport.close()
            return
        entry["protocol"] = proto
        proto.transport = transport
        for data in entry.pop("pending", []):
            try:
                proto.transport.sendto(data)
            except Exception:
                self.drop_client(key)
                return

    def drop_client(self, key):
        entry = self.clients.pop(key, None)
        if not entry:
            return
        proto = entry.get("protocol")
        if proto is not None and proto.transport is not None:
            proto.transport.close()

    def error_received(self, exc):
        log("listener error: %s" % exc)


async def main_async(args):
    range_value = args.range or os.environ.get("NANO_UDP_RANGE", "")
    target_value = args.target or os.environ.get("NANO_UDP_TARGET", "127.0.0.1")
    start, end = parse_range(range_value)
    if start == 1 and end == 65535 and not args.allow_full:
        raise ValueError("refusing full 1-65535 range without --allow-full")
    span = end - start + 1
    max_ports = args.max_ports
    if max_ports < 1 or max_ports > MAX_PORTS:
        raise ValueError("max-ports must be between 1 and %d" % MAX_PORTS)
    if span > max_ports:
        raise ValueError("range has %d ports, maximum is %d" % (span, max_ports))
    if ":" in target_value and not target_value.startswith("["):
        target_host, target_port = parse_target(target_value)
    else:
        target_host, target_port = target_value, start
        if not target_host:
            raise ValueError("empty target host")

    loop = asyncio.get_running_loop()
    listeners = []
    for port in range(start, end + 1):
        try:
            transport, proto = await loop.create_datagram_endpoint(
                lambda p=port: ListenerProtocol(p, target_host, target_port + (p - start)),
                local_addr=("0.0.0.0", port),
            )
        except OSError as exc:
            log("cannot bind UDP %d: %s" % (port, exc))
            for item in listeners:
                item[0].close()
            raise
        listeners.append((transport, proto))

    log("forwarding UDP %d-%d to %s:%d" % (start, end, target_host, target_port))
    stop = asyncio.Event()
    for sig in (signal.SIGTERM, signal.SIGINT):
        try:
            loop.add_signal_handler(sig, stop.set)
        except (NotImplementedError, RuntimeError):
            pass

    async def reaper():
        while True:
            await asyncio.sleep(30)
            now = time.monotonic()
            for transport, proto in listeners:
                for key, entry in list(proto.clients.items()):
                    target = entry.get("protocol")
                    if target is not None and now - target.last_seen > IDLE_SECONDS:
                        proto.drop_client(key)

    reaper_task = asyncio.create_task(reaper())
    try:
        await stop.wait()
    finally:
        reaper_task.cancel()
        for transport, proto in listeners:
            for key in list(proto.clients):
                proto.drop_client(key)
            transport.close()
    log("stopped")


def main():
    parser = argparse.ArgumentParser(description="Bounded UDP range forwarder")
    parser.add_argument("--range")
    parser.add_argument("--target")
    parser.add_argument("--max-ports", type=int, default=int(os.environ.get("NANO_UDP_MAX_PORTS", "128")))
    parser.add_argument("--allow-full", action="store_true")
    args = parser.parse_args()
    try:
        asyncio.run(main_async(args))
    except KeyboardInterrupt:
        return 0
    except Exception as exc:
        log("fatal: %s" % exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

NANO_UDP_PY
}

proto_udp_custom_install() {
  local range="27000-27010" answer target="127.0.0.1" start end span port python_bin
  local dir dest tmp unit_content allow_full=0 max_ports check_ports=1 extra_args="" limit_nofile=8192
  title
  ui_header "$(t proto_udp_custom)"
  say proto_udp_custom_desc
  line
  require_vps_root_systemd || { pause; return; }
  if ! have python3; then
    sayf proto_dep_missing "python3"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages python3 || { say proto_requires_python; pause; return; }
  fi
  python_bin="$(command -v python3)"
  ui_prompt "$(printf "$(t proto_udp_range_prompt)" "$range")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && range="$answer"
  valid_udp_range "$range" || { say proto_udp_bad_range; pause; return; }
  start="$(range_start "$range")"
  end="$(range_end "$range")"
  span="$(range_span "$range")"
  if (( start == 1 && end == 65535 )); then
    say proto_udp_full
    ui_prompt "$(t proto_udp_full)"
    IFS= read -r answer || answer=""
    case "${answer^^}" in
      TODOS|ALL) ;;
      *) say cancelled; pause; return ;;
    esac
    sayf proto_udp_full_confirm "$span"
    confirm "$(t proto_udp_custom)" || { say cancelled; pause; return; }
    allow_full=1
    max_ports=65535
    check_ports=0
    extra_args="--allow-full"
    limit_nofile=131072
  else
    if (( span > NANO_UDP_CUSTOM_MAX_SPAN )); then
      sayf proto_udp_span "$NANO_UDP_CUSTOM_MAX_SPAN"
      pause
      return
    fi
    max_ports="$NANO_UDP_CUSTOM_MAX_SPAN"
    (( span > 32 )) && sayf firewall_udp_span_warn "$span"
  fi
  if (( check_ports )); then
    for (( port = start; port <= end; port++ )); do
      if [[ "$(port_state udp "$port")" == yes ]]; then
        sayf proto_port_in_use "$port" udp
        pause
        return
      fi
    done
  fi
  ui_prompt "$(printf "$(t proto_target_prompt)" "$target")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && target="$answer"
  [[ "$target" =~ ^[A-Za-z0-9._-]+$ ]] || { say proto_bad_target; pause; return; }
  sayf proto_install_plan_generic "python3 udp_forwarder.py range ${range} target ${target}:${start}"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_udp_custom)")" || { say cancelled; pause; return; }
  dir="$NANO_OPT_DIR/udp"
  dest="$dir/udp_forwarder.py"
  install -d -m 0755 -- "$dir" || { sayf proto_install_fail "$(t proto_udp_custom)"; pause; return; }
  tmp="$(mktemp "${dir}/.udp.XXXXXX")" || { sayf proto_install_fail "$(t proto_udp_custom)"; pause; return; }
  udp_forwarder_source > "$tmp"
  if ! "$python_bin" -m py_compile "$tmp" >/dev/null 2>&1; then
    rm -f -- "$tmp"
    sayf proto_install_fail "$(t proto_udp_custom)"
    pause
    return
  fi
  install -m 0755 -- "$tmp" "$dest"
  rm -f -- "$tmp"
  write_config_file "$NANO_ETC_DIR/udp-custom.env" 0640 "NANO_UDP_RANGE=${range}
NANO_UDP_TARGET=${target}
NANO_UDP_MAX_PORTS=${max_ports}
NANO_UDP_ALLOW_FULL=${allow_full}" || { say proto_config_fail; pause; return; }
  unit_content="$(cat <<UNIT
[Unit]
Description=Nano VPS custom UDP forwarder
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=-$NANO_ETC_DIR/udp-custom.env
ExecStart=$python_bin $dest --max-ports $max_ports $extra_args
Restart=on-failure
RestartSec=3s
User=root
Group=root
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=$limit_nofile
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT
)"
  install_unit_content nano-udp-custom.service "$unit_content" || { sayf proto_install_fail "$(t proto_udp_custom)"; pause; return; }
  systemctl enable --now nano-udp-custom.service >/dev/null 2>&1 || true
  systemctl restart nano-udp-custom.service >/dev/null 2>&1 || true
  sleep 1
  if service_active nano-udp-custom.service && [[ "$(port_state udp "$start")" == yes ]]; then
    sayf proto_udp_install_ok "$range"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_udp_custom)"
  fi
  pause
}

hcr_script_dir() {
  dirname -- "$(abspath "${BASH_SOURCE[0]:-$0}")"
}

hcr_default_bundle() {
  local candidate
  for candidate in "${NANO_HCR_BUNDLE:-}" \
    "$(nano_source_dir)" \
    "$NANO_HCR_BUNDLE_DIR"; do
    [[ -n "$candidate" ]] || continue
    if [[ -f "$candidate/install.sh" && -f "$candidate/hcr-server" ]]; then
      printf '%s' "$candidate"
      return 0
    fi
  done
  printf '%s' "${HOME:-/tmp}/nano-vps-sources/SCRIPTMOD-LACASITA"
}

hcr_bundle_valid() {
  local bundle="$1"
  [[ -n "$bundle" && -f "$bundle/install.sh" && ! -L "$bundle/install.sh" &&
     -f "$bundle/hcr-server" && ! -L "$bundle/hcr-server" ]]
}

hcr_source_trusted() {
  local directory="$1" path mode
  [[ -d "$directory" && ! -L "$directory" ]] || return 1
  for path in "$directory" "$directory/install.sh" "$directory/hcr-server"; do
    [[ -e "$path" ]] || return 1
    [[ "$(stat -c '%u' -- "$path" 2>/dev/null)" == "0" ]] || return 1
    mode="$(stat -c '%a' -- "$path" 2>/dev/null)" || return 1
    (( (8#$mode & 8#022) == 0 )) || return 1
  done
  return 0
}

hcr_prepare_bundle() {
  local source="$1" destination="$NANO_HCR_BUNDLE_DIR" stamp file_path
  hcr_bundle_valid "$source" || { say modules_bundle_invalid; return 1; }
  is_root || { say modules_need_root; return 1; }
  hcr_source_trusted "$source" || { say modules_source_untrusted; return 1; }
  if [[ -e "$destination" ]]; then
    stamp="$(date +%Y%m%d-%H%M%S)"
    if cp -a -- "$destination" "$destination.bak.$stamp" 2>/dev/null; then
      sayf modules_backup "$destination.bak.$stamp"
    else
      say modules_prepare_fail
      return 1
    fi
  fi
  install -d -m 0755 -o root -g root -- "$destination" || {
    say modules_prepare_fail
    return 1
  }
  for file_path in install.sh hcr-server README.md LICENSE fullchain.pem privkey.pem; do
    [[ -f "$source/$file_path" ]] || continue
    cp -p -- "$source/$file_path" "$destination/$file_path" || {
      say modules_prepare_fail
      return 1
    }
    chown root:root -- "$destination/$file_path" 2>/dev/null || true
  done
  chmod 0755 "$destination/install.sh" "$destination/hcr-server" 2>/dev/null || true
  chmod 0644 "$destination/README.md" "$destination/LICENSE" 2>/dev/null || true
  [[ -f "$destination/fullchain.pem" ]] && chmod 0644 "$destination/fullchain.pem"
  [[ -f "$destination/privkey.pem" ]] && chmod 0600 "$destination/privkey.pem"
  sayf modules_prepare_ok "$destination"
  return 0
}

hcr_ensure_certificates() {
  local bundle="$1" transport="$2" cert key
  [[ "$transport" == "tls" || "$transport" == "auto" ]] || return 0
  cert="$bundle/fullchain.pem"
  key="$bundle/privkey.pem"
  [[ -s "$cert" && -s "$key" ]] && return 0
  say proto_hcr_cert_note
  if ! have openssl; then
    sayf proto_dep_missing "openssl"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || return 1
    pm_install_packages openssl || { say proto_cert_fail; return 1; }
  fi
  confirm "$(t proto_generate_cert_q)" || return 1
  if ! openssl req -x509 -newkey rsa:2048 -sha256 -nodes -days 825 \
    -subj "/CN=nano-vps-hcr" -keyout "$key" -out "$cert" >/dev/null 2>&1; then
    say proto_cert_fail
    return 1
  fi
  chmod 0644 -- "$cert" 2>/dev/null || true
  chmod 0600 -- "$key" 2>/dev/null || true
  chown root:root -- "$cert" "$key" 2>/dev/null || true
  sayf proto_cert_created "$bundle"
  return 0
}

modules_diagnostics() {
  local bundle binary arch compatibility root_state systemd_state
  bundle="$(hcr_default_bundle)"
  binary="$(binary_arch "$bundle/hcr-server" 2>/dev/null || true)"
  arch="${binary:-$(t modules_binary_absent)}"
  if [[ -n "$binary" && "$binary" == "$(host_arch_family)" ]]; then
    compatibility="$(t modules_compatible)"
  else
    compatibility="$(t modules_incompatible)"
  fi
  if is_root; then root_state="$(t yes)"; else root_state="$(t no)"; fi
  if systemd_available; then systemd_state="$(t yes)"; else systemd_state="$(t no)"; fi
  title
  say modules_diag
  line
  sayf modules_arch "$(host_arch)"
  sayf modules_arch_host "$(host_arch_family)"
  sayf modules_root "$root_state"
  sayf modules_systemd "$systemd_state"
  if [[ -f "$bundle/install.sh" ]]; then
    sayf modules_bundle "$bundle"
    if have sha256sum; then
      printf '  hcr-server sha256: %s\n' "$(sha256_file "$bundle/hcr-server" 2>/dev/null)"
    fi
    if [[ -f "$bundle/fullchain.pem" && -f "$bundle/privkey.pem" ]]; then
      printf '  TLS: fullchain.pem + privkey.pem\n'
    else
      printf '  TLS: %s\n' "$(t proto_missing)"
    fi
  else
    sayf modules_bundle "$(t modules_bundle_missing)"
  fi
  sayf modules_arch_compat "$arch" "$compatibility"
  line
  say modules_casita_note
  say modules_source_note
  pause
}

modules_la_casita_prepare() {
  local bundle answer
  title
  say modules_casita
  line
  say modules_prepare
  is_root || { say modules_need_root; pause; return; }
  if [[ -z "${NANO_HCR_BUNDLE:-}" && -z "${NANO_SOURCE_DIR:-}" ]]; then
    payload_ensure || { pause; return; }
  fi
  bundle="$(hcr_default_bundle)"
  sayf modules_bundle "$bundle"
  ui_prompt "$(t modules_bundle_prompt)"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && bundle="$(abspath "$(expand_path "$answer")")"
  bundle="$(abspath "$(expand_path "$bundle")")"
  hcr_bundle_valid "$bundle" || { say modules_bundle_invalid; pause; return; }
  if [[ "$bundle" == "$NANO_PAYLOAD_DIR/SCRIPTMOD-LACASITA" ]]; then
    verify_hash "$bundle/hcr-server" "$NANO_HCR_SHA256" || { pause; return; }
    verify_hash "$bundle/install.sh" "$NANO_HCR_INSTALL_SHA256" || { pause; return; }
  fi
  confirm "$(t modules_prepare_q)" || { say cancelled; pause; return; }
  hcr_prepare_bundle "$bundle" || true
  pause
}

modules_la_casita_install() {
  local bundle answer port transport version
  title
  say modules_casita
  line
  if (( IS_TERMUX )) || [[ "$(uname -s 2>/dev/null)" != "Linux" ]] || ! systemd_available; then
    say modules_linux_root
    pause
    return
  fi
  if ! is_root; then
    say modules_linux_root
    say modules_need_root
    pause
    return
  fi
  if [[ -z "${NANO_HCR_BUNDLE:-}" && -z "${NANO_SOURCE_DIR:-}" ]]; then
    payload_ensure || { pause; return; }
  fi
  bundle="$(hcr_default_bundle)"
  sayf modules_bundle "$bundle"
  ui_prompt "$(t modules_bundle_prompt)"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && bundle="$(abspath "$(expand_path "$answer")")"
  bundle="$(abspath "$(expand_path "$bundle")")"
  hcr_bundle_valid "$bundle" || { say modules_bundle_invalid; pause; return; }
  hcr_source_trusted "$bundle" || { say modules_source_untrusted; pause; return; }
  if [[ "$bundle" == "$NANO_PAYLOAD_DIR/SCRIPTMOD-LACASITA" ]]; then
    verify_hash "$bundle/hcr-server" "$NANO_HCR_SHA256" || { pause; return; }
    verify_hash "$bundle/install.sh" "$NANO_HCR_INSTALL_SHA256" || { pause; return; }
  fi
  if [[ "$(binary_arch "$bundle/hcr-server" 2>/dev/null || true)" != "$(host_arch_family)" ]]; then
    sayf modules_bad_arch "$(binary_arch "$bundle/hcr-server" 2>/dev/null || t modules_binary_absent)" "$(host_arch)"
    pause
    return
  fi
  version="$("$bundle/hcr-server" -version 2>/dev/null)" || version=""
  [[ "$version" =~ ^hcr-server\ version\ [0-9]+\.[0-9]+\.[0-9]+(\ -\ Patch\ [1-9][0-9]*)?$ ]] || {
    say modules_binary_check_fail
    pause
    return
  }
  if [[ "$bundle" != "$NANO_HCR_BUNDLE_DIR" ]]; then
    confirm "$(t modules_prepare_q)" || { say cancelled; pause; return; }
    hcr_prepare_bundle "$bundle" || { pause; return; }
    bundle="$NANO_HCR_BUNDLE_DIR"
  fi
  ui_prompt "$(t modules_port_prompt)"
  IFS= read -r port || port=""
  [[ -n "$port" ]] || port="8080"
  if [[ ! "$port" =~ ^[0-9]+$ ]] || (( 10#$port < 1 || 10#$port > 65535 )); then
    say modules_bad_port
    pause
    return
  fi
  port="$((10#$port))"
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active hcr-server.service; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  ui_prompt "$(t modules_transport_prompt)"
  IFS= read -r transport || transport=""
  [[ -n "$transport" ]] || transport="auto"
  case "$transport" in
    tls|plain|auto) ;;
    *) say modules_bad_transport; pause; return ;;
  esac
  hcr_ensure_certificates "$bundle" "$transport" || { pause; return; }
  sayf modules_install_plan "bash $bundle/install.sh --port $port --transport $transport"
  confirm "$(t modules_confirm_install)" || { say cancelled; pause; return; }
  if bash "$bundle/install.sh" --port "$port" --transport "$transport"; then
    say modules_install_ok
    say proto_firewall_hint
  else
    say modules_install_fail
  fi
  pause
}

modules_la_casita_uninstall() {
  local bundle
  title
  say modules_casita
  line
  if (( IS_TERMUX )) || ! systemd_available || ! is_root; then
    say modules_linux_root
    pause
    return
  fi
  if [[ -f "$NANO_HCR_BUNDLE_DIR/install.sh" ]]; then
    bundle="$NANO_HCR_BUNDLE_DIR"
  else
    bundle="$(hcr_default_bundle)"
  fi
  hcr_bundle_valid "$bundle" || { say modules_bundle_invalid; pause; return; }
  hcr_source_trusted "$bundle" || { say modules_source_untrusted; pause; return; }
  confirm "$(t modules_confirm_uninstall)" || { say cancelled; pause; return; }
  if bash "$bundle/install.sh" --uninstall; then
    say modules_uninstall_ok
  else
    say modules_uninstall_fail
  fi
  pause
}

modules_la_casita_status() {
  title
  say modules_status
  line
  say modules_status_hint
  if ! systemd_available; then
    say modules_linux_root
    pause
    return
  fi
  if systemctl list-unit-files hcr-server.service >/dev/null 2>&1 &&
     systemctl cat hcr-server.service >/dev/null 2>&1; then
    systemctl status --no-pager --full hcr-server.service 2>&1 | sed 's/^/  /' | ui_fold
  else
    say modules_status_missing
  fi
  pause
}

modules_darnix_info() {
  title
  say modules_darnix
  line
  say modules_darnix_l1
  say modules_darnix_l2
  say modules_darnix_l3
  say modules_darnix_l4
  line
  say modules_source_note
  pause
}

