profile_os_name() {
  local name=""
  if [[ -r /etc/os-release ]]; then
    name="$(. /etc/os-release 2>/dev/null; printf '%s' "${PRETTY_NAME:-Linux}")"
  elif (( IS_TERMUX )); then
    name="Android / Termux"
  else
    name="$(uname -s 2>/dev/null || true)"
  fi
  printf '%s' "${name:-$(t diag_os_unknown)}"
}

mem_total_mb() {
  awk '/^MemTotal:/ {printf "%d", $2 / 1024}' /proc/meminfo 2>/dev/null || printf '0'
}

cpu_cores() {
  if have nproc; then
    nproc 2>/dev/null
  elif have getconf; then
    getconf _NPROCESSORS_ONLN 2>/dev/null
  else
    printf '0'
  fi
}

disk_avail_mb() {
  local path="${1:-/}"
  df -Pk -- "$path" 2>/dev/null | awk 'NR == 2 {printf "%d", $4 / 1024}'
}

human_bytes() {
  local bytes="${1:-0}"
  awk -v b="$bytes" 'BEGIN {
    split("B KiB MiB GiB TiB PiB", u, " ")
    i = 1
    while (b >= 1024 && i < 6) { b /= 1024; i++ }
    if (i == 1) printf "%.0f %s", b, u[i]
    else printf "%.2f %s", b, u[i]
  }'
}

profile_need_ram() {
  case "$1" in
    hcr|xray) printf '512' ;;
    badvpn) printf '512' ;;
    slowdns|hysteria) printf '256' ;;
    ssl|bhttp|ws|dropbear) printf '128' ;;
    udp_custom|ssh) printf '64' ;;
    *) printf '64' ;;
  esac
}

profile_need_disk() {
  case "$1" in
    hcr|badvpn|hysteria|xray) printf '1024' ;;
    slowdns) printf '512' ;;
    *) printf '128' ;;
  esac
}

profile_load() {
  PROFILE_OS="$(profile_os_name)"
  PROFILE_ARCH="$(host_arch_family)"
  PROFILE_CPU="$(cpu_cores)"
  PROFILE_RAM_MB="$(mem_total_mb)"
  PROFILE_DISK_MB="$(disk_avail_mb /)"
  PROFILE_DISK_USABLE_MB=$(( ${PROFILE_DISK_MB:-0} - 1024 ))
  (( PROFILE_DISK_USABLE_MB < 0 )) && PROFILE_DISK_USABLE_MB=0
}

profile_status() {
  local id="$1" need_ram need_disk reason=""
  profile_load
  case "$id" in
    hcr|slowdns)
      [[ "$PROFILE_ARCH" == "x86-64" ]] || reason="arch:x86-64"
      ;;
    hysteria|xray)
      [[ "$PROFILE_ARCH" == "x86-64" || "$PROFILE_ARCH" == "arm64" ]] || reason="arch:x86-64/arm64"
      ;;
  esac
  need_ram="$(profile_need_ram "$id")"
  need_disk="$(profile_need_disk "$id")"
  if [[ -z "$reason" ]] && (( ${PROFILE_RAM_MB:-0} < need_ram )); then
    reason="ram:${need_ram}"
  fi
  if [[ -z "$reason" ]] && (( ${PROFILE_DISK_USABLE_MB:-0} < need_disk )); then
    reason="disk:${need_disk}"
  fi
  if [[ -n "$reason" ]]; then
    printf '%s' "$reason"
  else
    printf 'ok'
  fi
}

profile_available_count() {
  local id n=0
  for id in ssh ws slowdns ssl hcr bhttp badvpn udp_custom hysteria xray dropbear; do
    [[ "$(profile_status "$id")" == "ok" ]] && ((n++))
  done
  printf '%s' "$n"
}

profile_capacity_class() {
  local ram disk cpu
  profile_load
  ram="${PROFILE_RAM_MB:-0}"
  disk="${PROFILE_DISK_USABLE_MB:-0}"
  cpu="${PROFILE_CPU:-0}"
  if (( ram < 1536 || disk < 4096 || cpu < 2 )); then
    printf 'small'
  elif (( ram >= 4096 && disk >= 10240 && cpu >= 4 )); then
    printf 'large'
  else
    printf 'medium'
  fi
}

profile_recommended_count() {
  local avail="${1:-0}" class="${2:-medium}" max=0
  case "$class" in
    small) max=3 ;;
    medium) max=6 ;;
    large) max=11 ;;
  esac
  (( avail < max )) && max="$avail"
  printf '%s' "$max"
}

profile_line() {
  local id="$1" status reason detail
  status="$(profile_status "$id")"
  if [[ "$status" == "ok" ]]; then
    printf '  %-16s %-14s\n' "$(t "proto_$id")" "$(t profile_available)"
    return 0
  fi
  case "$status" in
    arch:*) detail="$(printf "$(t profile_reason_arch)" "${status#arch:}")" ;;
    ram:*) detail="$(printf "$(t profile_reason_ram)" "${status#ram:}")" ;;
    disk:*) detail="$(printf "$(t profile_reason_disk)" "${status#disk:}")" ;;
    *) detail="$status" ;;
  esac
  printf '  %-16s %-14s %s\n' "$(t "proto_$id")" "$(t profile_unavailable)" "$detail"
}

capacity_report() {
  local verdict id class avail recommended
  profile_load
  ui_header "$(t profile_title)"
  sayf profile_os "$PROFILE_OS"
  sayf profile_arch "$PROFILE_ARCH"
  sayf profile_cpu "$PROFILE_CPU"
  sayf profile_ram "$(human_bytes $(( PROFILE_RAM_MB * 1024 * 1024 )))"
  sayf profile_disk "$(human_bytes $(( PROFILE_DISK_MB * 1024 * 1024 )))"
  if (( ${PROFILE_RAM_MB:-0} >= 1024 && ${PROFILE_DISK_USABLE_MB:-0} >= 3072 )); then
    verdict="$(t profile_capacity_ok)"
  else
    verdict="$(t profile_capacity_low)"
  fi
  sayf profile_verdict "$verdict"
  class="$(profile_capacity_class)"
  avail="$(profile_available_count)"
  recommended="$(profile_recommended_count "$avail" "$class")"
  sayf profile_size "$(t "profile_size_$class")"
  sayf profile_methods_avail "$avail" 11
  sayf profile_recommend "$recommended"
  say profile_size_note
  line
  say profile_mandatory
  for id in bhttp hcr udp_custom hysteria xray; do
    profile_line "$id"
  done
  line
  say profile_optional
  for id in ssh ws slowdns ssl badvpn dropbear; do
    profile_line "$id"
  done
  line
  say profile_reserve_note
  say profile_hysteria_udp
  (( IS_TERMUX )) && say profile_no_root
}

first_run_marker() {
  printf '%s/first_run.done' "$NANO_STATE_DIR"
}

first_run_mark() {
  mkdir -p -- "$NANO_STATE_DIR" 2>/dev/null &&
    date '+%Y-%m-%d %H:%M:%S' > "$(first_run_marker)" 2>/dev/null
}

guided_dependencies() {
  local pm old_auto
  pm="$(detect_pm)"
  if [[ -z "$pm" ]]; then
    say install_no_manager
    return 1
  fi
  title
  ui_header "$(t onboard_deps_title)"
  say onboard_deps_intro
  line
  old_auto="${NANO_ASSUME_YES:-0}"
  NANO_ASSUME_YES=1
  install_group "$pm" basic
  install_group "$pm" network
  install_group "$pm" ssh
  NANO_ASSUME_YES="$old_auto"
  say onboard_deps_done
  sleep 1
  return 0
}

guided_protocols() {
  local choice id old_auto
  while true; do
    title
    ui_header "$(t onboard_proto_title)"
    say onboard_proto_intro
    line
    ui_menu "1|$(t proto_ssh)" "2|$(t proto_ws)" "3|$(t proto_slowdns)" \
      "4|$(t proto_ssl)" "5|$(t proto_hcr)" "6|$(t proto_bhttp)" \
      "7|$(t proto_badvpn)" "8|$(t proto_udp_custom)" "9|$(t proto_hysteria)" \
      "10|$(t proto_xray)" "11|$(t proto_dropbear)" "12|$(t onboard_proto_done)" "0|$(t onboard_proto_skip)"
    ask || continue
    case "$REPLY" in
      1) id=ssh ;;
      2) id=ws ;;
      3) id=slowdns ;;
      4) id=ssl ;;
      5) id=hcr ;;
      6) id=bhttp ;;
      7) id=badvpn ;;
      8) id=udp_custom ;;
      9) id=hysteria ;;
      10) id=xray ;;
      11) id=dropbear ;;
      12|0) return 0 ;;
      *) say invalid; sleep 1; continue ;;
    esac
    old_auto="${NANO_ASSUME_YES:-0}"
    NANO_ASSUME_YES=1
    proto_install_dispatch "$id"
    NANO_ASSUME_YES="$old_auto"
  done
}

guided_quota() {
  local tb answer
  traffic_load
  title
  ui_header "$(t onboard_quota_title)"
  say onboard_quota_intro
  line
  while true; do
    ui_prompt "$(t onboard_quota_prompt)"
    if ! IFS= read -r answer; then
      say cancelled
      return 1
    fi
    if [[ ! "$answer" =~ ^[0-9]+([.][0-9]+)?$ ]]; then
      say quota_bad_tb
      continue
    fi
    tb="$answer"
    break
  done
  QUOTA_TB="$tb"
  QUOTA_WARN=80
  QUOTA_RESET_DAY=1
  QUOTA_ACCUM_RX=0
  QUOTA_ACCUM_TX=0
  QUOTA_LAST_RX=0
  QUOTA_LAST_TX=0
  QUOTA_SEEN=0
  QUOTA_LAST_ALERT=""
  QUOTA_PERIOD_START="$(date +%Y-%m-%d)"
  QUOTA_NEXT_RESET="$(traffic_next_reset_from "$QUOTA_PERIOD_START")"
  traffic_save
  if [[ "$QUOTA_TB" == "0" ]]; then
    say quota_disabled
  else
    say quota_saved
  fi
  sleep 1
  return 0
}

startup_prepare_check() {
  local bash_version distro arch pm missing cmd
  title
  ui_header "$(t startup_prepare_title)"
  say startup_prepare_intro
  bash_version="${BASH_VERSION%%(*}"
  distro="${NANO_DISTRO:-unknown}"
  arch="$(uname -m 2>/dev/null || printf 'unknown')"
  sayf startup_prepare_bash "$bash_version"
  sayf startup_prepare_arch "$arch"
  sayf startup_prepare_distro "$distro"
  pm="$(detect_pm 2>/dev/null || true)"
  sayf startup_prepare_pm "${pm:-$(t not_available)}"
  missing=""
  for cmd in curl wget tar sha256sum ss; do
    have "$cmd" || missing+="${missing:+ }$cmd"
  done
  sayf startup_prepare_commands "${missing:-$(t dash_ready)}"
  if systemd_available; then
    say startup_prepare_systemd
  else
    say startup_prepare_no_systemd
  fi
  if ! is_root; then
    say startup_prepare_root
  fi
  line
  say startup_prepare_ready
  pause
}

first_run_wizard() {
  local marker choice
  (( IS_TERMUX )) && return 0
  marker="$(first_run_marker)"
  [[ -f "$marker" ]] && return 0

  title
  ui_header "$(t startup_diag_title)"
  print_diag
  line
  capacity_report
  line
  startup_prepare_check

  while true; do
    title
    ui_header "$(t onboard_title)"
    say startup_choose_mode
    line
    ui_menu "1|$(t onboard_guided)" "2|$(t onboard_manual)" "0|$(t menu_exit)"
    ask || return 0
    choice="$REPLY"
    case "$choice" in
      0) exit 0 ;;
      1)
        if ! is_root; then
          say startup_guided_root
          root_relaunch || true
          continue
        fi
        if systemd_available; then
          guided_dependencies || true
          guided_protocols
        else
          say services_no_systemd
          pause
        fi
        guided_quota
        break
        ;;
      2)
        say onboard_manual_note
        break
        ;;
      *) say invalid; sleep 1 ;;
    esac
  done

  if first_run_mark; then
    say onboard_done
    say onboard_panel_now
    sleep 1
  else
    say first_run_no_state
    pause
  fi
}

traffic_defaults() {
  QUOTA_TB="0"
  QUOTA_WARN="80"
  QUOTA_RESET_DAY="1"
  QUOTA_PERIOD_START=""
  QUOTA_NEXT_RESET=""
  QUOTA_ACCUM_RX="0"
  QUOTA_ACCUM_TX="0"
  QUOTA_LAST_RX="0"
  QUOTA_LAST_TX="0"
  QUOTA_SEEN="0"
  QUOTA_LAST_ALERT=""
}

traffic_load() {
  traffic_defaults
  if [[ -r "$NANO_TRAFFIC_FILE" ]]; then
    . "$NANO_TRAFFIC_FILE" 2>/dev/null || traffic_defaults
  fi
}

traffic_save() {
  write_config_file "$NANO_TRAFFIC_FILE" 0600 "QUOTA_TB=$QUOTA_TB
QUOTA_WARN=$QUOTA_WARN
QUOTA_RESET_DAY=$QUOTA_RESET_DAY
QUOTA_PERIOD_START=$QUOTA_PERIOD_START
QUOTA_NEXT_RESET=$QUOTA_NEXT_RESET
QUOTA_ACCUM_RX=$QUOTA_ACCUM_RX
QUOTA_ACCUM_TX=$QUOTA_ACCUM_TX
QUOTA_LAST_RX=$QUOTA_LAST_RX
QUOTA_LAST_TX=$QUOTA_LAST_TX
QUOTA_SEEN=$QUOTA_SEEN
QUOTA_LAST_ALERT=$QUOTA_LAST_ALERT" 2>/dev/null || true
}

traffic_iface() {
  local iface=""
  if have ip; then
    iface="$(ip route get 1.1.1.1 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i == "dev") {print $(i + 1); exit}}')"
    if [[ -z "$iface" ]]; then
      iface="$(ip route 2>/dev/null | awk '/^default/ {for (i = 1; i <= NF; i++) if ($i == "dev") {print $(i + 1); exit}}')"
    fi
  fi
  printf '%s' "${iface:-all}"
}

traffic_sample() {
  local iface="$1" rx="" tx=""
  if [[ "$iface" != "all" && -r "/sys/class/net/$iface/statistics/rx_bytes" ]]; then
    rx="$(cat "/sys/class/net/$iface/statistics/rx_bytes" 2>/dev/null || true)"
    tx="$(cat "/sys/class/net/$iface/statistics/tx_bytes" 2>/dev/null || true)"
  fi
  if [[ ! "$rx" =~ ^[0-9]+$ || ! "$tx" =~ ^[0-9]+$ ]]; then
    if [[ -r /proc/net/dev ]]; then
      read -r rx tx < <(awk -v target="$iface" '
        NR > 2 {
          gsub(/:/, "", $1)
          if ((target == "all" && $1 != "lo") || (target != "all" && $1 == target)) {
            rx += $2
            tx += $10
          }
        }
        END { printf "%0.f %0.f\n", rx, tx }
      ' /proc/net/dev)
    fi
  fi
  [[ "$rx" =~ ^[0-9]+$ ]] || rx=0
  [[ "$tx" =~ ^[0-9]+$ ]] || tx=0
  printf '%s %s\n' "$rx" "$tx"
}

traffic_next_reset_from() {
  local base="$1" year month day candidate today
  year="$(date -d "$base" +%Y 2>/dev/null || date +%Y)"
  month="$(date -d "$base" +%m 2>/dev/null || date +%m)"
  day="$(printf '%02d' "${QUOTA_RESET_DAY:-1}")"
  candidate="${year}-${month}-${day}"
  today="$(date +%Y-%m-%d)"
  if [[ "$today" < "$candidate" ]]; then
    printf '%s' "$candidate"
  else
    date -d "$candidate +1 month" +%Y-%m-%d 2>/dev/null || printf '%s' "$candidate"
  fi
}

traffic_refresh() {
  local iface rx tx drx dtx today guard=0
  traffic_load
  today="$(date +%Y-%m-%d)"
  if [[ -z "${QUOTA_PERIOD_START:-}" ]]; then
    QUOTA_PERIOD_START="$today"
  fi
  if [[ -z "${QUOTA_NEXT_RESET:-}" ]]; then
    QUOTA_NEXT_RESET="$(traffic_next_reset_from "$today")"
  fi
  while [[ "$today" > "${QUOTA_NEXT_RESET:-}" || "$today" == "${QUOTA_NEXT_RESET:-}" ]]; do
    QUOTA_PERIOD_START="$today"
    QUOTA_ACCUM_RX="0"
    QUOTA_ACCUM_TX="0"
    QUOTA_LAST_ALERT=""
    QUOTA_NEXT_RESET="$(date -d "$QUOTA_NEXT_RESET +1 month" +%Y-%m-%d 2>/dev/null || true)"
    [[ -n "$QUOTA_NEXT_RESET" ]] || break
    (( guard++ >= 24 )) && break
  done
  iface="$(traffic_iface)"
  read -r rx tx < <(traffic_sample "$iface")
  if [[ "${QUOTA_SEEN:-0}" != "1" ]]; then
    QUOTA_LAST_RX="$rx"
    QUOTA_LAST_TX="$tx"
    QUOTA_ACCUM_RX="0"
    QUOTA_ACCUM_TX="0"
    QUOTA_SEEN="1"
  else
    if (( rx >= ${QUOTA_LAST_RX:-0} && tx >= ${QUOTA_LAST_TX:-0} )); then
      drx=$(( rx - ${QUOTA_LAST_RX:-0} ))
      dtx=$(( tx - ${QUOTA_LAST_TX:-0} ))
    else
      drx="$rx"
      dtx="$tx"
    fi
    QUOTA_ACCUM_RX=$(( ${QUOTA_ACCUM_RX:-0} + drx ))
    QUOTA_ACCUM_TX=$(( ${QUOTA_ACCUM_TX:-0} + dtx ))
  fi
  QUOTA_LAST_RX="$rx"
  QUOTA_LAST_TX="$tx"
  TRAFFIC_IFACE="$iface"
  TRAFFIC_USED_BYTES=$(( ${QUOTA_ACCUM_RX:-0} + ${QUOTA_ACCUM_TX:-0} ))
  TRAFFIC_LIMIT_BYTES="$(awk -v tb="${QUOTA_TB:-0}" 'BEGIN {printf "%.0f", tb * 1099511627776}')"
  if (( TRAFFIC_LIMIT_BYTES > 0 )); then
    TRAFFIC_PERCENT=$(( TRAFFIC_USED_BYTES * 100 / TRAFFIC_LIMIT_BYTES ))
  else
    TRAFFIC_PERCENT=0
  fi
  traffic_save
}

traffic_report() {
  traffic_refresh
  ui_header "$(t quota_usage_title)"
  if [[ "${QUOTA_TB:-0}" == "0" ]]; then
    say quota_disabled
  else
    sayf quota_limit "$(human_bytes "$TRAFFIC_LIMIT_BYTES")"
    sayf quota_remaining "$(human_bytes $(( TRAFFIC_LIMIT_BYTES > TRAFFIC_USED_BYTES ? TRAFFIC_LIMIT_BYTES - TRAFFIC_USED_BYTES : 0 )))"
    sayf quota_percent "$TRAFFIC_PERCENT"
  fi
  sayf quota_used "$(human_bytes "$TRAFFIC_USED_BYTES")"
  sayf quota_period "${QUOTA_PERIOD_START:-$(t diag_no_data)} -> ${QUOTA_NEXT_RESET:-$(t diag_no_data)}"
  sayf quota_iface "$TRAFFIC_IFACE"
  line
  say quota_total_note
  say quota_note
}

traffic_config() {
  local answer tb warn day marker
  traffic_load
  ui_prompt "$(printf "$(t quota_tb_prompt)" "${QUOTA_TB:-0}")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] || answer="${QUOTA_TB:-0}"
  if [[ ! "$answer" =~ ^[0-9]+([.][0-9]+)?$ ]]; then
    say quota_bad_tb
    return 1
  fi
  tb="$answer"
  ui_prompt "$(printf "$(t quota_warn_prompt)" "${QUOTA_WARN:-80}")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] || answer="${QUOTA_WARN:-80}"
  if [[ ! "$answer" =~ ^[0-9]+$ ]] || (( 10#$answer < 1 || 10#$answer > 100 )); then
    say quota_bad_warn
    return 1
  fi
  warn="$((10#$answer))"
  ui_prompt "$(printf "$(t quota_reset_prompt)" "${QUOTA_RESET_DAY:-1}")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] || answer="${QUOTA_RESET_DAY:-1}"
  if [[ ! "$answer" =~ ^[0-9]+$ ]] || (( 10#$answer < 1 || 10#$answer > 28 )); then
    say quota_bad_day
    return 1
  fi
  day="$((10#$answer))"
  QUOTA_TB="$tb"
  QUOTA_WARN="$warn"
  QUOTA_RESET_DAY="$day"
  QUOTA_ACCUM_RX="0"
  QUOTA_ACCUM_TX="0"
  QUOTA_LAST_RX="0"
  QUOTA_LAST_TX="0"
  QUOTA_SEEN="0"
  QUOTA_LAST_ALERT=""
  QUOTA_PERIOD_START="$(date +%Y-%m-%d)"
  QUOTA_NEXT_RESET="$(traffic_next_reset_from "$QUOTA_PERIOD_START")"
  traffic_save
  if [[ "$QUOTA_TB" == "0" ]]; then
    say quota_disabled
  else
    say quota_saved
  fi
}

traffic_reset() {
  local iface rx tx
  confirm "$(t quota_reset_confirm)" || { say cancelled; return 1; }
  traffic_load
  iface="$(traffic_iface)"
  read -r rx tx < <(traffic_sample "$iface")
  QUOTA_ACCUM_RX="0"
  QUOTA_ACCUM_TX="0"
  QUOTA_LAST_RX="$rx"
  QUOTA_LAST_TX="$tx"
  QUOTA_SEEN="1"
  QUOTA_PERIOD_START="$(date +%Y-%m-%d)"
  QUOTA_NEXT_RESET="$(traffic_next_reset_from "$QUOTA_PERIOD_START")"
  QUOTA_LAST_ALERT=""
  traffic_save
  say quota_reset_ok
}

traffic_alert_check() {
  local key level=0
  [[ -r "$NANO_TRAFFIC_FILE" ]] || return 0
  traffic_refresh
  [[ "${QUOTA_TB:-0}" == "0" ]] && return 0
  if (( TRAFFIC_LIMIT_BYTES > 0 && TRAFFIC_USED_BYTES >= TRAFFIC_LIMIT_BYTES )); then
    level=100
  elif (( TRAFFIC_PERCENT >= 90 )); then
    level=90
  elif (( TRAFFIC_PERCENT >= ${QUOTA_WARN:-80} )); then
    level="${QUOTA_WARN:-80}"
  fi
  (( level == 0 )) && return 0
  key="${level}:${QUOTA_PERIOD_START:-}"
  [[ "${QUOTA_LAST_ALERT:-}" == "$key" ]] && return 0
  QUOTA_LAST_ALERT="$key"
  traffic_save
  if (( level == 100 )); then
    say quota_exceeded
  else
    sayf quota_warn "$TRAFFIC_PERCENT"
  fi
}

port_registry_has() {
  local transport="$1" port="$2"
  [[ -r "$NANO_PORT_REGISTRY" ]] || return 1
  awk -F '\t' -v t="$transport" -v p="$port" '$3 == t && $4 == p {found = 1} END {exit !found}' "$NANO_PORT_REGISTRY" 2>/dev/null
}

port_registry_add() {
  local id="$1" transport="$2" port="$3" note="$4"
  mkdir -p -- "$(dirname -- "$NANO_PORT_REGISTRY")" 2>/dev/null || return 1
  printf '%s\t%s\t%s\t%s\t%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$id" "$transport" "$port" "$note" >> "$NANO_PORT_REGISTRY" 2>/dev/null || return 1
  chmod 600 "$NANO_PORT_REGISTRY" 2>/dev/null || true
}

port_suggest_free() {
  local transport="$1" start="$2" candidate i
  candidate="$((10#$start))"
  for (( i = 0; i < 64; i++ )); do
    candidate=$(( candidate + 1 ))
    (( candidate > 65535 )) && candidate=1024
    valid_port "$candidate" || continue
    [[ "$(port_state "$transport" "$candidate")" == "yes" ]] && continue
    port_registry_has "$transport" "$candidate" && continue
    printf '%s' "$candidate"
    return 0
  done
  return 1
}

port_planner() {
  local answer port transport next id spec p proto state
  title
  ui_header "$(t planner_title)"
  say planner_intro
  line
  say planner_current
  for id in ssh ws slowdns ssl hcr bhttp badvpn udp_custom hysteria xray dropbear; do
    [[ "$id" == "udp_custom" && -z "$(udp_custom_range)" ]] && continue
    printf '  %s\n' "$(proto_label_ports "$id")"
  done
  line
  ui_prompt "$(printf "$(t planner_prompt)" "8443")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] || answer="8443"
  if [[ ! "$answer" =~ ^[0-9]+$ ]] || ! valid_port "$answer"; then
    say ports_invalid_port
    pause
    return
  fi
  port="$((10#$answer))"
  for transport in tcp udp; do
    if [[ "$(port_state "$transport" "$port")" == "yes" ]]; then
      if [[ "$transport" == "tcp" ]]; then sayf planner_tcp_used "$port"; else sayf planner_udp_used "$port"; fi
      next="$(port_suggest_free "$transport" "$port" 2>/dev/null || true)"
      [[ -n "$next" ]] && sayf planner_suggest "$next"
      pause
      return
    fi
  done
  if port_registry_has tcp "$port" || port_registry_has udp "$port"; then
    sayf planner_conflict "$port"
    next="$(port_suggest_free tcp "$port" 2>/dev/null || true)"
    [[ -n "$next" ]] && sayf planner_suggest "$next"
    pause
    return
  fi
  sayf planner_free "$port"
  if confirm "$(t planner_reserve_q)"; then
    ui_prompt "$(t planner_transport_prompt)"
    IFS= read -r answer || answer=""
    transport="${answer:-tcp}"
    if [[ "$transport" != "tcp" && "$transport" != "udp" ]]; then
      say planner_bad_transport
      pause
      return
    fi
    if port_registry_add planner "$transport" "$port" "reserved"; then
      say planner_reserved
      sayf planner_registry "$NANO_PORT_REGISTRY"
    else
      say proto_config_fail
    fi
  fi
  pause
}

hysteria_arch_info() {
  case "$(host_arch_family)" in
    x86-64) printf 'amd64 %s' "$NANO_HYSTERIA_SHA_AMD64" ;;
    arm64) printf 'arm64 %s' "$NANO_HYSTERIA_SHA_ARM64" ;;
    *) return 1 ;;
  esac
}

hysteria_generate_password() {
  head -c 32 /dev/urandom 2>/dev/null | base64 2>/dev/null | tr -dc 'A-Za-z0-9' | head -c 32
}

hysteria_make_self_signed() {
  local cert="$1" key="$2" cn
  if ! have openssl; then
    sayf proto_dep_missing "openssl"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || return 1
    pm_install_packages openssl || return 1
  fi
  cn="$(hostname -f 2>/dev/null || hostname 2>/dev/null || printf 'nano-vps')"
  mkdir -p -- "$(dirname -- "$cert")" "$(dirname -- "$key")" || return 1
  openssl req -x509 -newkey rsa:2048 -sha256 -nodes -days 3650 \
    -keyout "$key" -out "$cert" -subj "/CN=$cn" >/dev/null 2>&1 || return 1
  chmod 0600 "$key" 2>/dev/null || true
  chmod 0644 "$cert" 2>/dev/null || true
  return 0
}

download_file() {
  local url="$1" dest="$2"
  if have curl; then
    curl -fsSL --connect-timeout 15 --max-time 180 --retry 3 --retry-delay 2 --retry-max-time 120 -o "$dest" "$url"
  elif have wget; then
    wget -q --timeout=30 --tries=3 -O "$dest" "$url"
  else
    return 1
  fi
}

hysteria_public_ip() {
  local ip=""
  if have ip; then
    ip="$(ip route get 1.1.1.1 2>/dev/null | awk '{for (i = 1; i <= NF; i++) if ($i == "src") {print $(i + 1); exit}}')"
  fi
  if [[ -z "$ip" ]] && have hostname; then
    ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
  fi
  printf '%s' "${ip:-$(t diag_no_data)}"
}

proto_hysteria_install() {
  local port=8443 answer pass cert key self_signed=0 arch_name expected_sha local_bin tmp unit_content config_content cn public_ip client_file
  title
  ui_header "$(t proto_hysteria)"
  say proto_hysteria_desc
  line
  say proto_hysteria_udp_note
  line
  require_vps_root_systemd || { pause; return; }
  if ! hysteria_arch_info >/dev/null 2>&1; then
    say proto_hysteria_arch
    pause
    return
  fi
  read -r arch_name expected_sha < <(hysteria_arch_info)
  port="$(proto_port_value hysteria)"
  [[ -n "$port" ]] || port=8443
  ui_prompt "$(printf "$(t proto_port_prompt2)" "$port")"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && port="$answer"
  valid_port "$port" || { say proto_bad_port; pause; return; }
  if [[ "$(port_state udp "$port")" == "yes" ]] && ! service_active "$NANO_HYSTERIA_UNIT"; then
    sayf proto_port_in_use "$port" udp
    pause
    return
  fi
  ui_prompt "$(t proto_hysteria_pass_prompt)"
  read_secret pass || pass=""
  if [[ -z "$pass" ]]; then
    pass="$(hysteria_generate_password)"
  fi
  if [[ ! "$pass" =~ ^[A-Za-z0-9._-]{8,128}$ ]]; then
    say proto_hysteria_bad_pass
    pause
    return
  fi
  cert="$NANO_ETC_DIR/ssl/fullchain.pem"
  key="$NANO_ETC_DIR/ssl/privkey.pem"
  ui_prompt "$(t proto_hysteria_cert_prompt)"
  IFS= read -r answer || answer=""
  if [[ -n "$answer" && "$answer" != "auto" ]]; then
    cert="$(abspath "$(expand_path "$answer")")"
    ui_prompt "$(t proto_hysteria_key_prompt)"
    IFS= read -r answer || answer=""
    [[ -n "$answer" ]] || { say cancelled; pause; return; }
    key="$(abspath "$(expand_path "$answer")")"
    if [[ ! -s "$cert" || ! -s "$key" ]]; then
      say proto_hysteria_cert_missing
      pause
      return
    fi
  elif [[ -s "$cert" && -s "$key" ]]; then
    self_signed=0
  else
    cert="$NANO_HYSTERIA_DIR/fullchain.pem"
    key="$NANO_HYSTERIA_DIR/privkey.pem"
    say proto_hysteria_selfsigned
    hysteria_make_self_signed "$cert" "$key" || { say proto_install_fail "$(t proto_hysteria)"; pause; return; }
    self_signed=1
  fi
  cn="$(hostname -f 2>/dev/null || hostname 2>/dev/null || printf 'nano-vps')"
  local_bin=""
  ui_prompt "$(t proto_hysteria_local_prompt)"
  IFS= read -r answer || answer=""
  [[ -n "$answer" ]] && local_bin="$(abspath "$(expand_path "$answer")")"
  if [[ -n "$local_bin" ]]; then
    if [[ ! -f "$local_bin" ]]; then
      say proto_source_missing
      pause
      return
    fi
  else
    if ! have curl && ! have wget; then
      sayf proto_dep_missing "curl"
      confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
      pm_install_packages curl || { say proto_hysteria_download_fail; pause; return; }
    fi
    sayf proto_hysteria_download_plan "$NANO_HYSTERIA_VERSION" "$arch_name"
  fi
  sayf proto_install_plan_generic "hysteria server --config $NANO_HYSTERIA_CONFIG; UDP/$port"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_hysteria)")" || { say cancelled; pause; return; }
  install -d -m 0755 -- "$NANO_HYSTERIA_DIR" || { say proto_install_fail "$(t proto_hysteria)"; pause; return; }
  tmp="$(mktemp "$NANO_HYSTERIA_DIR/.hysteria.XXXXXX")" || { say proto_install_fail "$(t proto_hysteria)"; pause; return; }
  if [[ -n "$local_bin" ]]; then
    cp -f -- "$local_bin" "$tmp" || { rm -f -- "$tmp"; say proto_install_fail "$(t proto_hysteria)"; pause; return; }
  else
    if ! download_file "https://github.com/apernet/hysteria/releases/download/app/${NANO_HYSTERIA_VERSION}/hysteria-linux-${arch_name}" "$tmp"; then
      rm -f -- "$tmp"
      say proto_hysteria_download_fail
      pause
      return
    fi
  fi
  if ! verify_hash "$tmp" "$expected_sha"; then
    rm -f -- "$tmp"
    pause
    return
  fi
  install -m 0755 -- "$tmp" "$NANO_HYSTERIA_BIN" || { rm -f -- "$tmp"; say proto_install_fail "$(t proto_hysteria)"; pause; return; }
  rm -f -- "$tmp"
  write_config_file "$NANO_HYSTERIA_ENV" 0600 "NANO_HYSTERIA_PORT=$port
NANO_HYSTERIA_CERT=$cert
NANO_HYSTERIA_KEY=$key
NANO_HYSTERIA_SELF_SIGNED=$self_signed
NANO_HYSTERIA_VERSION=$NANO_HYSTERIA_VERSION" || { say proto_config_fail; pause; return; }
  config_content="listen: :$port
tls:
  cert: "$cert"
  key: "$key"
auth:
  type: password
  password: $pass
masquerade:
  type: proxy
  proxy:
    url: https://news.ycombinator.com/
    rewriteHost: true"
  write_config_file "$NANO_HYSTERIA_CONFIG" 0600 "$config_content" || { say proto_config_fail; pause; return; }
  unit_content="[Unit]
Description=Nano VPS Hysteria 2
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$NANO_HYSTERIA_BIN server --config $NANO_HYSTERIA_CONFIG
Restart=on-failure
RestartSec=3s
User=root
Group=root
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
ProtectHome=read-only
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LimitNOFILE=1048576
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target"
  install_unit_content "$NANO_HYSTERIA_UNIT" "$unit_content" || { say proto_install_fail "$(t proto_hysteria)"; pause; return; }
  systemctl enable --now "$NANO_HYSTERIA_UNIT" >/dev/null 2>&1 || true
  systemctl restart "$NANO_HYSTERIA_UNIT" >/dev/null 2>&1 || true
  sleep 1
  public_ip="$(hysteria_public_ip)"
  client_file="$NANO_HYSTERIA_DIR/client.txt"
  write_config_file "$client_file" 0600 "server: $public_ip
port: $port
password: $pass
sni: $cn
insecure: $self_signed
version: $NANO_HYSTERIA_VERSION" || true
  if service_active "$NANO_HYSTERIA_UNIT" && [[ "$(port_state udp "$port")" == "yes" ]]; then
    sayf proto_install_ok "$(t proto_hysteria)"
    sayf proto_hysteria_client_info "$client_file"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_hysteria)"
    journalctl -u "$NANO_HYSTERIA_UNIT" --no-pager -n 20 2>&1 | sed 's/^/  /' | ui_fold
  fi
  pause
}

banner_require_root() {
  if (( IS_TERMUX )) || [[ "$(uname -s 2>/dev/null)" != "Linux" ]]; then
    say banner_termux
    return 1
  fi
  if ! is_root; then
    say banner_need_root
    return 1
  fi
  return 0
}

banner_state_read() {
  BANNER_SSH_ENABLED="$(env_get "$NANO_BANNER_STATE" SSH_ENABLED 2>/dev/null || true)"
  BANNER_MOTD_ENABLED="$(env_get "$NANO_BANNER_STATE" MOTD_ENABLED 2>/dev/null || true)"
  BANNER_MOTD_MODE="$(env_get "$NANO_BANNER_STATE" MOTD_MODE 2>/dev/null || true)"
  BANNER_MOTD_BACKUP="$(env_get "$NANO_BANNER_STATE" MOTD_BACKUP 2>/dev/null || true)"
  BANNER_MOTD_CREATED="$(env_get "$NANO_BANNER_STATE" MOTD_CREATED 2>/dev/null || true)"
  [[ "$BANNER_SSH_ENABLED" == "1" ]] || BANNER_SSH_ENABLED=0
  [[ "$BANNER_MOTD_ENABLED" == "1" ]] || BANNER_MOTD_ENABLED=0
  case "$BANNER_MOTD_MODE" in
    static|update-motd) ;;
    *) BANNER_MOTD_MODE="none" ;;
  esac
  [[ "$BANNER_MOTD_BACKUP" == "1" ]] || BANNER_MOTD_BACKUP=0
  [[ "$BANNER_MOTD_CREATED" == "1" ]] || BANNER_MOTD_CREATED=0
}

banner_state_save() {
  write_config_file "$NANO_BANNER_STATE" 0600 "SSH_ENABLED=$BANNER_SSH_ENABLED
MOTD_ENABLED=$BANNER_MOTD_ENABLED
MOTD_MODE=$BANNER_MOTD_MODE
MOTD_BACKUP=$BANNER_MOTD_BACKUP
MOTD_CREATED=$BANNER_MOTD_CREATED"
}



proto_dropbear_install() {
  local port=2222 binary unit_content
  title
  ui_header "$(t proto_dropbear)"
  say proto_dropbear_desc
  line
  require_vps_root_systemd || { pause; return; }
  binary="$(command -v dropbear 2>/dev/null || true)"
  if [[ -z "$binary" ]]; then
    sayf proto_dep_missing "dropbear"
    confirm "$(printf "$(t proto_dep_install_q)" "$(detect_pm)")" || { say cancelled; pause; return; }
    pm_install_packages dropbear || { sayf proto_install_fail "$(t proto_dropbear)"; pause; return; }
    binary="$(command -v dropbear 2>/dev/null || true)"
  fi
  if [[ -z "$binary" || ! -x "$binary" ]]; then
    sayf proto_install_fail "$(t proto_dropbear)"
    pause
    return
  fi
  if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active "$NANO_DROPBEAR_UNIT"; then
    sayf proto_port_in_use "$port" tcp
    pause
    return
  fi
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_dropbear)")" || { say cancelled; pause; return; }
  install -d -m 0755 -- "$NANO_ETC_DIR" || { say proto_install_fail; pause; return; }
  write_config_file "$NANO_DROPBEAR_ENV" 0600 "DROPBEAR_PORT=$port" || { say proto_install_fail; pause; return; }
  unit_content="[Unit]
Description=Nano VPS Dropbear SSH on TCP $port
After=network.target

[Service]
Type=simple
ExecStart=$binary -F -E -R -p $port
Restart=on-failure
RestartSec=3
UMask=0077
PrivateTmp=true

[Install]
WantedBy=multi-user.target"
  install_unit_content "$NANO_DROPBEAR_UNIT" "$unit_content" || { say proto_install_fail; pause; return; }
  systemctl enable --now "$NANO_DROPBEAR_UNIT" >/dev/null 2>&1
  if systemctl is-active --quiet "$NANO_DROPBEAR_UNIT" && [[ "$(port_state tcp "$port")" == yes ]]; then
    sayf proto_install_ok "$(t proto_dropbear)"
    say proto_firewall_hint
  else
    sayf proto_install_fail "$(t proto_dropbear)"
    systemctl status --no-pager --full "$NANO_DROPBEAR_UNIT" 2>&1 | sed 's/^/  /' | ui_fold
  fi
  pause
}

# Xray Core: VMess, VLESS and Trojan share one hardened systemd service.
xray_asset_for_arch() {
  case "$(uname -m 2>/dev/null)" in
    x86_64|amd64) printf '64' ;;
    aarch64|arm64) printf 'arm64-v8a' ;;
    *) return 1 ;;
  esac
}

proto_xray_install() {
  local asset url tmpdir archive digest_file expected actual xray_src
  local vmess_port=10086 vless_port=10087 trojan_port=10088 port
  local vmess_uuid vless_uuid trojan_password nologin
  local cert_tmp key_tmp config_tmp unit_content client_file
  title
  ui_header "$(t proto_xray)"
  say proto_xray_desc
  say proto_xray_tls_note
  line
  require_vps_root_systemd || { pause; return; }
  asset="$(xray_asset_for_arch 2>/dev/null || true)"
  if [[ -z "$asset" ]]; then
    say proto_hysteria_arch
    pause
    return
  fi
  for port in "$vmess_port" "$vless_port" "$trojan_port"; do
    if [[ "$(port_state tcp "$port")" == yes ]] && ! service_active "$NANO_XRAY_UNIT"; then
      sayf proto_port_in_use "$port" tcp
      pause
      return
    fi
  done
  if ! have curl || ! have unzip || ! have openssl; then
    sayf proto_dep_missing "curl, unzip, openssl"
    confirm "$(t install_confirm)" || { say cancelled; pause; return; }
    pm_install_packages curl unzip openssl || { say proto_install_fail; pause; return; }
  fi
  if ! have useradd || ! have groupadd || ! have getent; then
    sayf proto_dep_missing "useradd, groupadd, getent (shadow/passwd tools)"
    pause
    return
  fi
  sayf proto_install_plan_generic "Xray Core official release; TCP $vmess_port/$vless_port/$trojan_port"
  confirm "$(printf "$(t proto_install_confirm)" "$(t proto_xray)")" || { say cancelled; pause; return; }
  if service_active "$NANO_XRAY_UNIT"; then
    confirm "Xray is already active. Stop it and replace its configuration?" || { say cancelled; pause; return; }
    systemctl stop "$NANO_XRAY_UNIT" || { say proto_action_fail; pause; return; }
  fi
  tmpdir="$(mktemp -d "${TMPDIR:-/tmp}/nano-xray.XXXXXX")" || { say proto_install_fail; pause; return; }
  archive="$tmpdir/xray.zip"
  digest_file="$tmpdir/xray.zip.dgst"
  url="https://github.com/XTLS/Xray-core/releases/latest/download/Xray-linux-${asset}.zip"
  if ! curl -fL --retry 2 --connect-timeout 15 --max-time 300 -o "$archive" "$url" ||
     ! curl -fL --retry 2 --connect-timeout 15 --max-time 60 -o "$digest_file" "${url}.dgst"; then
    rm -rf -- "$tmpdir"
    say proto_hysteria_download_fail
    pause
    return
  fi
  expected="$(sed -nE 's/^[[:space:]]*SHA256[[:space:]]*=[[:space:]]*([0-9A-Fa-f]{64}).*/\1/p' "$digest_file" | head -n1 | tr 'A-F' 'a-f')"
  actual="$(sha256_file "$archive" 2>/dev/null || true)"
  if [[ ! "$expected" =~ ^[0-9a-f]{64}$ || "$actual" != "$expected" ]]; then
    rm -rf -- "$tmpdir"
    say proto_payload_integrity
    pause
    return
  fi
  if ! unzip -q "$archive" -d "$tmpdir/unpacked"; then
    rm -rf -- "$tmpdir"
    say proto_install_fail
    pause
    return
  fi
  xray_src="$tmpdir/unpacked/xray"
  if [[ ! -s "$xray_src" ]] || ! chmod 0755 "$xray_src" || ! "$xray_src" -version >/dev/null 2>&1; then
    rm -rf -- "$tmpdir"
    say proto_install_fail
    pause
    return
  fi
  if ! getent group nano-xray >/dev/null 2>&1; then
    groupadd --system nano-xray || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  fi
  if ! id -u nano-xray >/dev/null 2>&1; then
    nologin="$(command -v nologin 2>/dev/null || printf '/usr/sbin/nologin')"
    useradd --system --gid nano-xray --no-create-home --home-dir /nonexistent --shell "$nologin" nano-xray || {
      rm -rf -- "$tmpdir"; say proto_install_fail; pause; return;
    }
  fi
  if [[ "$(id -u nano-xray 2>/dev/null || printf '0')" == 0 ]]; then
    rm -rf -- "$tmpdir"
    say proto_install_fail
    pause
    return
  fi
  vmess_uuid="$(cat /proc/sys/kernel/random/uuid 2>/dev/null || true)"
  vless_uuid="$(cat /proc/sys/kernel/random/uuid 2>/dev/null || true)"
  trojan_password="$(openssl rand -hex 24 2>/dev/null || true)"
  if [[ ! "$vmess_uuid" =~ ^[0-9a-fA-F-]{36}$ || ! "$vless_uuid" =~ ^[0-9a-fA-F-]{36}$ || ${#trojan_password} -lt 32 ]]; then
    rm -rf -- "$tmpdir"; say proto_install_fail; pause; return
  fi
  cert_tmp="$tmpdir/fullchain.pem"
  key_tmp="$tmpdir/privkey.pem"
  if ! openssl req -x509 -nodes -newkey rsa:2048 -days 825 -keyout "$key_tmp" -out "$cert_tmp" -subj "/CN=Nano Panel" >/dev/null 2>&1; then
    rm -rf -- "$tmpdir"; say proto_install_fail; pause; return
  fi
  config_tmp="$tmpdir/config.json"
  cat > "$config_tmp" <<XRAY_JSON
{
  "log": {"loglevel": "warning"},
  "inbounds": [
    {"tag":"vmess-in","listen":"0.0.0.0","port":${vmess_port},"protocol":"vmess","settings":{"clients":[{"id":"${vmess_uuid}","alterId":0}]},"streamSettings":{"network":"tcp","security":"tls","tlsSettings":{"certificates":[{"certificateFile":"${NANO_XRAY_DIR}/fullchain.pem","keyFile":"${NANO_XRAY_DIR}/privkey.pem"}]}}},
    {"tag":"vless-in","listen":"0.0.0.0","port":${vless_port},"protocol":"vless","settings":{"decryption":"none","clients":[{"id":"${vless_uuid}"}]},"streamSettings":{"network":"tcp","security":"tls","tlsSettings":{"certificates":[{"certificateFile":"${NANO_XRAY_DIR}/fullchain.pem","keyFile":"${NANO_XRAY_DIR}/privkey.pem"}]}}},
    {"tag":"trojan-in","listen":"0.0.0.0","port":${trojan_port},"protocol":"trojan","settings":{"clients":[{"password":"${trojan_password}"}]},"streamSettings":{"network":"tcp","security":"tls","tlsSettings":{"certificates":[{"certificateFile":"${NANO_XRAY_DIR}/fullchain.pem","keyFile":"${NANO_XRAY_DIR}/privkey.pem"}]}}}
  ],
  "outbounds": [{"protocol":"freedom","settings":{}}]
}
XRAY_JSON
  if ! "$xray_src" run -test -config "$config_tmp" >/dev/null 2>&1; then
    rm -rf -- "$tmpdir"; say proto_install_fail; pause; return
  fi
  install -d -m 0750 -- "$NANO_XRAY_DIR" || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  chown root:nano-xray "$NANO_XRAY_DIR" || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  [[ -e "$NANO_XRAY_BIN" ]] && backup_file "$NANO_XRAY_BIN"
  [[ -e "$NANO_XRAY_CONFIG" ]] && backup_file "$NANO_XRAY_CONFIG"
  [[ -e "$NANO_XRAY_DIR/fullchain.pem" ]] && backup_file "$NANO_XRAY_DIR/fullchain.pem"
  [[ -e "$NANO_XRAY_DIR/privkey.pem" ]] && backup_file "$NANO_XRAY_DIR/privkey.pem"
  if ! install -m 0755 -- "$xray_src" "$NANO_XRAY_BIN" ||
     ! install -m 0640 -o root -g nano-xray -- "$config_tmp" "$NANO_XRAY_CONFIG" ||
     ! install -m 0640 -o root -g nano-xray -- "$cert_tmp" "$NANO_XRAY_DIR/fullchain.pem" ||
     ! install -m 0640 -o root -g nano-xray -- "$key_tmp" "$NANO_XRAY_DIR/privkey.pem"; then
    rm -rf -- "$tmpdir"; say proto_install_fail; pause; return
  fi
  write_config_file "$NANO_XRAY_ENV" 0600 "XRAY_VMESS_PORT=$vmess_port
XRAY_VLESS_PORT=$vless_port
XRAY_TROJAN_PORT=$trojan_port" || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  client_file="$NANO_XRAY_DIR/client-details.txt"
  write_config_file "$client_file" 0600 "Xray Core client details
TLS certificate: self-signed (client must allow insecure or replace certificate)
VMess: port=$vmess_port uuid=$vmess_uuid alterId=0 network=tcp security=tls
VLESS: port=$vless_port uuid=$vless_uuid encryption=none network=tcp security=tls
Trojan: port=$trojan_port password=$trojan_password network=tcp security=tls" || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  unit_content="[Unit]
Description=Nano VPS Xray Core (VMess VLESS Trojan)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=nano-xray
Group=nano-xray
ExecStartPre=$NANO_XRAY_BIN run -test -config $NANO_XRAY_CONFIG
ExecStart=$NANO_XRAY_BIN run -config $NANO_XRAY_CONFIG
Restart=on-failure
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true

[Install]
WantedBy=multi-user.target"
  install_unit_content "$NANO_XRAY_UNIT" "$unit_content" || { rm -rf -- "$tmpdir"; say proto_install_fail; pause; return; }
  systemctl enable --now "$NANO_XRAY_UNIT" >/dev/null 2>&1
  if systemctl is-active --quiet "$NANO_XRAY_UNIT"; then
    rm -rf -- "$tmpdir"
    sayf proto_install_ok "$(t proto_xray)"
    sayf proto_xray_client_info "$client_file"
    say proto_xray_tls_note
    say proto_firewall_hint
  else
    systemctl disable --now "$NANO_XRAY_UNIT" >/dev/null 2>&1 || true
    rm -rf -- "$tmpdir"
    sayf proto_install_fail "$(t proto_xray)"
  fi
  pause
}

banner_default_ssh() {
  printf '%s\n' \
    "============================================================" \
    "                    NANO VPS - SSH" \
    "     Acceso restringido. Solo personal autorizado." \
    "     Restricted access. Authorized users only." \
    "============================================================"
}

banner_default_motd() {
  printf '%s\n' \
    "============================================================" \
    "                    NANO VPS" \
    "      Bienvenido. Cierra la sesion al terminar." \
    "      Welcome. Close the session when finished." \
    "============================================================"
}

banner_ensure_content() {
  local kind="$1" target default
  case "$kind" in
    ssh) target="$NANO_SSH_BANNER_FILE"; default="$(banner_default_ssh)" ;;
    motd) target="$NANO_MOTD_FILE"; default="$(banner_default_motd)" ;;
    *) return 1 ;;
  esac
  if [[ -f "$target" ]] && grep -q '[^[:space:]]' "$target" 2>/dev/null; then
    return 0
  fi
  if ! write_config_file "$target" 0644 "$default"; then
    say banner_save_fail
    return 1
  fi
  sayf banner_default_created "$target"
  return 0
}

banner_sanitize_file() {
  local file="$1" dir raw clean
  [[ -f "$file" ]] || return 1
  dir="$(dirname -- "$file")"
  raw="$(mktemp "$dir/.nano-banner-raw.XXXXXX")" || return 1
  clean="$(mktemp "$dir/.nano-banner-clean.XXXXXX")" || { rm -f -- "$raw"; return 1; }
  if ! LC_ALL=C tr -d '\000-\010\013-\037\177' < "$file" > "$raw"; then
    rm -f -- "$raw" "$clean"
    return 1
  fi
  if ! awk '
    NF { if (!started) started = 1 }
    started { lines[++n] = $0 }
    END {
      while (n > 0 && lines[n] ~ /^[[:space:]]*$/) n--
      for (i = 1; i <= n; i++) print lines[i]
    }
  ' "$raw" > "$clean"; then
    rm -f -- "$raw" "$clean"
    return 1
  fi
  if ! mv -f -- "$clean" "$file"; then
    rm -f -- "$raw" "$clean"
    return 1
  fi
  rm -f -- "$raw"
  return 0
}

banner_capture_content() {
  local kind="$1" target current tmp editor candidate line count total
  case "$kind" in
    ssh) target="$NANO_SSH_BANNER_FILE" ;;
    motd) target="$NANO_MOTD_FILE" ;;
    *) return 1 ;;
  esac
  banner_require_root || return 1
  install -d -m 0755 -- "$(dirname -- "$target")" 2>/dev/null || {
    say banner_save_fail
    return 1
  }
  current=""
  if [[ -r "$target" ]]; then
    current="$(cat -- "$target" 2>/dev/null || true)"
  fi
  if [[ -z "$current" ]]; then
    case "$kind" in
      ssh) current="$(banner_default_ssh)" ;;
      motd) current="$(banner_default_motd)" ;;
    esac
  fi
  tmp="$(mktemp "${TMPDIR:-/tmp}/nano-banner.XXXXXX")" || {
    say banner_save_fail
    return 1
  }
  if ! printf '%s\n' "$current" > "$tmp"; then
    rm -f -- "$tmp"
    say banner_save_fail
    return 1
  fi
  say banner_edit_intro
  editor=""
  if [[ "${NANO_BANNER_EDITOR:-auto}" != "none" && -t 0 && -t 1 ]]; then
    for candidate in "${NANO_BANNER_EDITOR:-}" nano vi vim editor; do
      [[ -n "$candidate" ]] || continue
      command -v "$candidate" >/dev/null 2>&1 || continue
      editor="$candidate"
      break
    done
    if [[ -n "$editor" ]]; then
      sayf banner_editor_hint "$editor"
      if ! "$editor" "$tmp"; then
        rm -f -- "$tmp"
        say cancelled
        return 1
      fi
    fi
  fi
  if [[ -z "$editor" ]]; then
    say banner_editor_none
    say banner_custom_hint
    : > "$tmp" || {
      rm -f -- "$tmp"
      say banner_save_fail
      return 1
    }
    count=0
    while (( count < 20 )); do
      ui_prompt "$(printf "$(t banner_input_hint)" "$((count + 1))" 20)"
      IFS= read -r line || line=""
      [[ -z "$line" ]] && break
      printf '%s\n' "$line" >> "$tmp" || break
      ((count++))
    done
    if (( count == 0 )); then
      rm -f -- "$tmp"
      say cancelled
      return 1
    fi
  fi
  if ! banner_sanitize_file "$tmp"; then
    rm -f -- "$tmp"
    say banner_save_fail
    return 1
  fi
  if ! grep -q '[^[:space:]]' "$tmp" 2>/dev/null; then
    rm -f -- "$tmp"
    say banner_empty
    return 1
  fi
  total="$(wc -c < "$tmp" 2>/dev/null || printf '0')"
  count="$(awk 'END {print NR}' "$tmp" 2>/dev/null || printf '0')"
  if (( total > 4096 || count > 20 )); then
    rm -f -- "$tmp"
    say banner_too_large
    return 1
  fi
  say banner_preview
  line
  sed -n '1,20p' -- "$tmp" | sed 's/^/  /' | ui_fold
  line
  if ! confirm "$(t banner_confirm_save)"; then
    rm -f -- "$tmp"
    say cancelled
    return 1
  fi
  if ! write_config_file "$target" 0644 "$(cat -- "$tmp")"; then
    rm -f -- "$tmp"
    say banner_save_fail
    return 1
  fi
  rm -f -- "$tmp"
  sayf banner_saved "$target"
  if [[ "$kind" == "motd" ]]; then
    banner_motd_refresh || true
  elif banner_ssh_enabled; then
    banner_ssh_reload || say banner_ssh_reload_fail
  fi
  return 0
}

banner_preview_file() {
  local file="$1"
  if [[ ! -r "$file" ]]; then
    say banner_not_configured
    return 0
  fi
  if ! grep -q '[^[:space:]]' "$file" 2>/dev/null; then
    say banner_empty
    return 0
  fi
  say banner_preview
  sed -n '1,10p' -- "$file" | sed 's/^/  /' | ui_fold
}

banner_ssh_enabled() {
  [[ -r "$NANO_SSHD_CONFIG" ]] || return 1
  grep -Fqx -- "$NANO_SSH_BLOCK_BEGIN" "$NANO_SSHD_CONFIG" 2>/dev/null &&
    grep -Fqx -- "Banner $NANO_SSH_BANNER_FILE" "$NANO_SSHD_CONFIG" 2>/dev/null
}

banner_ssh_reload() {
  local unit
  unit="$(ssh_unit_name)"
  if systemctl reload "$unit" >/dev/null 2>&1; then
    return 0
  fi
  if have service && service "$unit" reload >/dev/null 2>&1; then
    return 0
  fi
  return 1
}

banner_ssh_apply() {
  local enable="$1" cfg="$NANO_SSHD_CONFIG" dir clean new err backup stamp
  banner_require_root || return 1
  require_vps_root_systemd || return 1
  if ! have sshd || [[ ! -r "$cfg" ]]; then
    say banner_ssh_missing
    return 1
  fi
  if [[ -L "$cfg" ]]; then
    cfg="$(readlink -f -- "$cfg" 2>/dev/null || printf '%s' "$cfg")"
  fi
  if [[ "$enable" == "1" ]]; then
    banner_ensure_content ssh || return 1
  fi
  dir="$(dirname -- "$cfg")"
  clean="$(mktemp "$dir/.nano-sshd-clean.XXXXXX")" || {
    say banner_ssh_fail
    return 1
  }
  new="$(mktemp "$dir/.nano-sshd-new.XXXXXX")" || {
    rm -f -- "$clean"
    say banner_ssh_fail
    return 1
  }
  err="$(mktemp "$dir/.nano-sshd-err.XXXXXX")" || {
    rm -f -- "$clean" "$new"
    say banner_ssh_fail
    return 1
  }
  if ! awk -v b="$NANO_SSH_BLOCK_BEGIN" -v e="$NANO_SSH_BLOCK_END" '
    $0 == b { skip = 1; next }
    $0 == e { skip = 0; next }
    !skip { print }
  ' "$cfg" > "$clean"; then
    rm -f -- "$clean" "$new" "$err"
    say banner_ssh_fail
    return 1
  fi
  if [[ "$enable" == "1" ]]; then
    if ! {
      printf '%s\n' "$NANO_SSH_BLOCK_BEGIN"
      printf 'Banner %s\n' "$NANO_SSH_BANNER_FILE"
      printf '%s\n' "$NANO_SSH_BLOCK_END"
      cat -- "$clean"
    } > "$new"; then
      rm -f -- "$clean" "$new" "$err"
      say banner_ssh_fail
      return 1
    fi
  elif ! cp -- "$clean" "$new"; then
    rm -f -- "$clean" "$new" "$err"
    say banner_ssh_fail
    return 1
  fi
  if ! sshd -t -f "$new" >"$err" 2>&1; then
    say banner_ssh_invalid
    sed -n '1,20p' -- "$err" | ui_fold
    rm -f -- "$clean" "$new" "$err"
    return 1
  fi
  if cmp -s -- "$cfg" "$new"; then
    banner_state_read
    BANNER_SSH_ENABLED="$enable"
    banner_state_save || true
    rm -f -- "$clean" "$new" "$err"
    if [[ "$enable" == "1" ]]; then say banner_ssh_on; else say banner_ssh_off; fi
    return 0
  fi
  stamp="$(date +%Y%m%d-%H%M%S)"
  backup="${cfg}.bak.${stamp}.$$"
  if ! cp -a -- "$cfg" "$backup"; then
    rm -f -- "$clean" "$new" "$err"
    say banner_ssh_fail
    return 1
  fi
  sayf banner_ssh_backup "$backup"
  chmod --reference="$cfg" "$new" 2>/dev/null || chmod 0644 -- "$new" 2>/dev/null || true
  chown --reference="$cfg" "$new" 2>/dev/null || true
  if ! mv -f -- "$new" "$cfg"; then
    rm -f -- "$clean" "$new" "$err"
    say banner_ssh_fail
    return 1
  fi
  if ! sshd -t >"$err" 2>&1; then
    say banner_ssh_invalid
    cp -a -- "$backup" "$cfg" 2>/dev/null || true
    sed -n '1,20p' -- "$err" | ui_fold
    rm -f -- "$clean" "$new" "$err"
    return 1
  fi
  if ! banner_ssh_reload; then
    say banner_ssh_reload_fail
    banner_state_read
    BANNER_SSH_ENABLED="$enable"
    banner_state_save || true
    rm -f -- "$clean" "$new" "$err"
    return 1
  fi
  banner_state_read
  BANNER_SSH_ENABLED="$enable"
  banner_state_save || true
  rm -f -- "$clean" "$new" "$err"
  if [[ "$enable" == "1" ]]; then say banner_ssh_on; else say banner_ssh_off; fi
  return 0
}

banner_motd_mode() {
  if [[ -L "$NANO_MOTD_SYSTEM" ]]; then
    if [[ -d "$NANO_UPDATE_MOTD_DIR" ]]; then
      printf 'update-motd'
    else
      printf 'symlink'
    fi
  elif [[ -d "$NANO_MOTD_SYSTEM" ]]; then
    printf 'invalid'
  else
    printf 'static'
  fi
}

banner_motd_enabled() {
  banner_state_read
  [[ "$BANNER_MOTD_ENABLED" == "1" ]] || return 1
  case "$BANNER_MOTD_MODE" in
    update-motd)
      [[ -x "$NANO_MOTD_SCRIPT" ]]
      ;;
    static)
      [[ -f "$NANO_MOTD_SYSTEM" ]] && cmp -s -- "$NANO_MOTD_FILE" "$NANO_MOTD_SYSTEM"
      ;;
    *)
      return 1
      ;;
  esac
}

banner_motd_apply() {
  local enable="$1" mode restored=0
  banner_require_root || return 1
  banner_state_read
  if [[ "$enable" == "1" ]]; then
    banner_ensure_content motd || return 1
    mode="$(banner_motd_mode)"
    case "$mode" in
      static)
        if [[ -e "$NANO_MOTD_BACKUP" ]]; then
          BANNER_MOTD_BACKUP=1
          BANNER_MOTD_CREATED=0
        elif [[ "$BANNER_MOTD_CREATED" == "1" ]]; then
          BANNER_MOTD_BACKUP=0
        elif [[ -e "$NANO_MOTD_SYSTEM" ]]; then
          if ! cp -a -- "$NANO_MOTD_SYSTEM" "$NANO_MOTD_BACKUP"; then
            say banner_motd_backup_fail
            return 1
          fi
          BANNER_MOTD_BACKUP=1
          BANNER_MOTD_CREATED=0
        else
          BANNER_MOTD_BACKUP=0
          BANNER_MOTD_CREATED=1
        fi
        if ! write_config_file "$NANO_MOTD_SYSTEM" 0644 "$(cat -- "$NANO_MOTD_FILE")"; then
          say banner_motd_fail
          return 1
        fi
        BANNER_MOTD_MODE="static"
        ;;
      update-motd)
        if ! write_config_file "$NANO_MOTD_SCRIPT" 0755 "#!/bin/sh
[ -r \"$NANO_MOTD_FILE\" ] && cat \"$NANO_MOTD_FILE\"
exit 0"; then
          say banner_motd_fail
          return 1
        fi
        BANNER_MOTD_MODE="update-motd"
        BANNER_MOTD_BACKUP=0
        BANNER_MOTD_CREATED=0
        rm -f -- "$NANO_MOTD_BACKUP" 2>/dev/null || true
        ;;
      *)
        say banner_motd_symlink
        return 1
        ;;
    esac
    BANNER_MOTD_ENABLED=1
    banner_state_save || say banner_save_fail
    say banner_motd_on
    return 0
  fi

  rm -f -- "$NANO_MOTD_SCRIPT" 2>/dev/null || true
  if [[ -e "$NANO_MOTD_BACKUP" && ! -L "$NANO_MOTD_SYSTEM" ]]; then
    if ! cp -a -- "$NANO_MOTD_BACKUP" "$NANO_MOTD_SYSTEM"; then
      say banner_motd_restore_fail
      return 1
    fi
    rm -f -- "$NANO_MOTD_BACKUP"
    restored=1
  elif [[ "$BANNER_MOTD_CREATED" == "1" && ! -L "$NANO_MOTD_SYSTEM" ]]; then
    rm -f -- "$NANO_MOTD_SYSTEM"
  fi
  BANNER_MOTD_ENABLED=0
  BANNER_MOTD_MODE="none"
  BANNER_MOTD_BACKUP=0
  BANNER_MOTD_CREATED=0
  banner_state_save || say banner_save_fail
  if (( restored )); then say banner_motd_restored; else say banner_motd_off; fi
  return 0
}

banner_motd_refresh() {
  banner_state_read
  [[ "$BANNER_MOTD_ENABLED" == "1" ]] || return 0
  if [[ "$BANNER_MOTD_MODE" == "static" ]]; then
    if ! write_config_file "$NANO_MOTD_SYSTEM" 0644 "$(cat -- "$NANO_MOTD_FILE")"; then
      say banner_motd_fail
      return 1
    fi
  fi
  return 0
}

banner_short_status() {
  local ssh_state motd_state
  if banner_ssh_enabled; then ssh_state="$(t banner_enabled)"; else ssh_state="$(t banner_disabled)"; fi
  if banner_motd_enabled; then motd_state="$(t banner_enabled)"; else motd_state="$(t banner_disabled)"; fi
  printf '  SSH: %s  |  MOTD: %s\n' "$ssh_state" "$motd_state"
}

banner_status_view() {
  local state
  ui_header "$(t banner_status_title)"
  if banner_ssh_enabled; then state="$(t banner_enabled)"; else state="$(t banner_disabled)"; fi
  printf '  %s: %s\n' "$(t banner_ssh)" "$state"
  sayf banner_file "$NANO_SSH_BANNER_FILE"
  banner_preview_file "$NANO_SSH_BANNER_FILE"
  say banner_ssh_hint
  line
  banner_state_read
  if banner_motd_enabled; then state="$(t banner_enabled)"; else state="$(t banner_disabled)"; fi
  printf '  %s: %s\n' "$(t banner_motd)" "$state"
  sayf banner_file "$NANO_MOTD_FILE"
  if [[ "$BANNER_MOTD_MODE" == "update-motd" ]]; then
    sayf banner_target "$NANO_MOTD_SCRIPT"
  else
    sayf banner_target "$NANO_MOTD_SYSTEM"
  fi
  banner_preview_file "$NANO_MOTD_FILE"
  say banner_motd_hint
}

banner_menu() {
  if (( IS_TERMUX )); then
    title
    ui_header "$(t banner_title)"
    say banner_termux
    pause
    return
  fi
  while true; do
    title
    ui_header "$(t banner_title)"
    say banner_intro
    line
    banner_short_status
    line
    ui_menu "1|$(t banner_view_status)" "2|$(t banner_edit_ssh)" \
      "3|$(t banner_edit_motd)" "4|$(t banner_toggle_ssh)" \
      "5|$(t banner_toggle_motd)" "6|$(t banner_restore_motd)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) banner_status_view; pause ;;
      2) banner_capture_content ssh; pause ;;
      3) banner_capture_content motd; pause ;;
      4)
        if banner_ssh_enabled; then
          if confirm "$(t banner_confirm_ssh_off)"; then
            banner_ssh_apply 0 || true
          else
            say cancelled
          fi
        else
          if confirm "$(t banner_confirm_ssh_on)"; then
            banner_ssh_apply 1 || true
          else
            say cancelled
          fi
        fi
        pause
        ;;
      5)
        if banner_motd_enabled; then
          if confirm "$(t banner_confirm_motd_off)"; then
            banner_motd_apply 0 || true
          else
            say cancelled
          fi
        else
          if confirm "$(t banner_confirm_motd_on)"; then
            banner_motd_apply 1 || true
          else
            say cancelled
          fi
        fi
        pause
        ;;
      6)
        banner_state_read
        if [[ "$BANNER_MOTD_MODE" == "static" && -e "$NANO_MOTD_BACKUP" ]]; then
          if confirm "$(t banner_confirm_motd_off)"; then
            banner_motd_apply 0 || true
          else
            say cancelled
          fi
        else
          say banner_no_backup
        fi
        pause
        ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

settings_menu() {
  while true; do
    title
    ui_header "$(t settings_title)"
    say settings_intro
    line
    ui_menu "1|$(t settings_profile)" "2|$(t settings_quota)" \
      "3|$(t settings_usage)" "4|$(t settings_reset)" \
      "5|$(t settings_ports)" "6|$(t menu_theme)" \
      "7|$(t settings_banner)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) title; capacity_report; pause ;;
      2)
        title
        ui_header "$(t quota_title)"
        say quota_intro
        line
        traffic_config || true
        pause
        ;;
      3) title; traffic_report; pause ;;
      4) title; traffic_reset || true; pause ;;
      5) port_planner ;;
      6) theme_menu ;;
      7) banner_menu ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

theme_label() {
  case "$1" in
    debian) t theme_debian ;;
    cyberpunk) t theme_cyberpunk ;;
    matrix) t theme_matrix ;;
    bluegold|boca) t theme_bluegold ;;
    inferno) t theme_inferno ;;
    *) t theme_debian ;;
  esac
}

theme_menu() {
  while true; do
    title
    ui_header "$(t theme_title)"
    say theme_intro
    line
    sayf theme_current "$(theme_label "$UI_THEME")"
    ui_text "$(t "theme_${UI_THEME}_desc")" "  "
    line
    ui_menu "1|$(t theme_debian)" "2|$(t theme_cyberpunk)" \
      "3|$(t theme_matrix)" "4|$(t theme_bluegold)" "5|$(t theme_inferno)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) UI_THEME="debian" ;;
      2) UI_THEME="cyberpunk" ;;
      3) UI_THEME="matrix" ;;
      4) UI_THEME="bluegold" ;;
      5) UI_THEME="inferno" ;;
      0) return ;;
      *) say invalid; sleep 1; continue ;;
    esac
    if theme_save; then say theme_saved; else say theme_save_fail; fi
    ui_apply_theme
    pause
  done
}


protocols_menu() {
  while true; do
    title
    ui_header "$(t menu_protocols)"
    say proto_intro
    line
    ui_menu "1|$(t proto_ssh)" "2|$(t proto_ws)" "3|$(t proto_slowdns)" \
      "4|$(t proto_ssl)" "5|$(t proto_hcr)" "6|$(t proto_bhttp)" \
      "7|$(t proto_badvpn)" "8|$(t proto_udp_custom)" "9|$(t proto_hysteria)" \
      "10|$(t proto_xray)" "11|$(t proto_dropbear)" "0|$(t back)"
    ask || continue
    case "$REPLY" in
      1) protocol_menu ssh ;;
      2) protocol_menu ws ;;
      3) protocol_menu slowdns ;;
      4) protocol_menu ssl ;;
      5) protocol_menu hcr ;;
      6) protocol_menu bhttp ;;
      7) protocol_menu badvpn ;;
      8) protocol_menu udp_custom ;;
      9) protocol_menu hysteria ;;
      10) protocol_menu xray ;;
      11) protocol_menu dropbear ;;
      0) return ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

print_help() {
  title
  ui_header "$(t help_title)"
  ui_text "$(t help_usage)" "  "
  ui_text "$(t help_options)" "  "
  ui_text "$(t help_lang)" "  "
  ui_text "$(t help_diag)" "  "
  ui_text "$(t help_version)" "  "
  ui_text "$(t help_help)" "  "
  line
  say help_modules
  say help_embedded
  say help_compat
  say help_note
}

dash_pad() {
  local text width pad
  width="$2"
  text="$(ui_fit "$1" "$width")"
  pad=$(( width - ${#text} ))
  (( pad < 0 )) && pad=0
  printf '%s%*s' "$text" "$pad" ''
}

dash_center() {
  local text="$1" width="$2" n left right
  n=$(( width - ${#text} ))
  (( n < 0 )) && n=0
  left=$(( n / 2 ))
  right=$(( n - left ))
  printf '%*s%s%*s' "$left" '' "$text" "$right" ''
}

dash_box_width() {
  local width=$(( UI_COLS - 4 ))
  (( width > 116 )) && width=116
  (( width < 16 )) && width=16
  printf '%s' "$width"
}

dash_cells3() {
  local width="$1" inner c1 c2 c3
  inner=$(( width - 2 ))
  c1=$(( inner * 33 / 100 ))
  c3=$(( inner * 33 / 100 ))
  (( c1 < 10 )) && c1=10
  (( c3 < 10 )) && c3=10
  c2=$(( inner - c1 - c3 ))
  if (( c2 < 10 )); then
    c2=10
    c1=$(( (inner - 10) / 2 ))
    c3=$(( inner - 10 - c1 ))
  fi
  printf '%s %s %s' "$c1" "$c2" "$c3"
}

dash_cells2() {
  local width="$1" inner c1 c2
  inner=$(( width - 1 ))
  c1=$(( inner / 2 ))
  c2=$(( inner - c1 ))
  printf '%s %s' "$c1" "$c2"
}

dash_top_cell() {
  local title="$1" cell="$2" shown fill
  shown="$(ui_fit "$title" $(( cell - 4 )))"
  fill=$(( cell - 4 - ${#shown} ))
  (( fill < 0 )) && fill=0
  printf '%s-- %s%s%s %s' "$UI_BORDER" "$UI_BOLD$UI_MAGENTA" "$shown" "$UI_BORDER" "$(ui_fill '-' "$fill")"
}

dash_plain_cell() {
  local text="$1" width="$2" color="$3"
  printf '%s%s%s' "$color" "$(dash_pad "$text" "$width")" "$UI_RESET"
}

dash_meter() {
  local pct="${1:-0}" width="${2:-8}" filled empty
  [[ "$pct" =~ ^[0-9]+$ ]] || pct=0
  (( pct < 0 )) && pct=0
  (( pct > 100 )) && pct=100
  filled=$(( pct * width / 100 ))
  empty=$(( width - filled ))
  printf '[%s%s]' "$(printf '%*s' "$filled" '' | tr ' ' '#')" "$(printf '%*s' "$empty" '' | tr ' ' '.')"
}

dash_cpu_percent() {
  local u1 n1 s1 i1 w1 q1 sq1 st1 _ u2 n2 s2 i2 w2 q2 sq2 st2 t1 t2 d1 d2 dt di
  [[ -r /proc/stat ]] || { printf 'n/a'; return 0; }
  read -r _ u1 n1 s1 i1 w1 q1 sq1 st1 _ < /proc/stat || { printf 'n/a'; return 0; }
  t1=$(( u1 + n1 + s1 + i1 + w1 + q1 + sq1 + st1 ))
  d1=$(( i1 + w1 ))
  sleep 0.2 2>/dev/null || sleep 1 2>/dev/null || true
  read -r _ u2 n2 s2 i2 w2 q2 sq2 st2 _ < /proc/stat || { printf 'n/a'; return 0; }
  t2=$(( u2 + n2 + s2 + i2 + w2 + q2 + sq2 + st2 ))
  d2=$(( i2 + w2 ))
  dt=$(( t2 - t1 ))
  di=$(( d2 - d1 ))
  if (( dt > 0 )); then printf '%d' "$(( (dt - di) * 100 / dt ))"; else printf '0'; fi
}

dash_mem_available_mb() {
  awk '/^MemAvailable:/ {printf "%d", $2 / 1024; found = 1; exit} END {if (!found) printf "0"}' /proc/meminfo 2>/dev/null
}

dash_mem_used_percent() {
  local total avail
  total="$(mem_total_mb)"
  avail="$(dash_mem_available_mb)"
  if [[ "$total" =~ ^[0-9]+$ ]] && [[ "$avail" =~ ^[0-9]+$ ]] && (( total > 0 && avail >= 0 && avail <= total )); then
    printf '%d' "$(( (total - avail) * 100 / total ))"
  else
    printf '0'
  fi
}

dash_disk_percent() {
  df -Pk / 2>/dev/null | awk 'NR == 2 {gsub(/%/, "", $5); print $5 + 0; found = 1; exit} END {if (!found) print 0}'
}

dash_uptime_text() {
  local text
  text="$(awk '{
    s = int($1)
    d = int(s / 86400)
    h = int((s % 86400) / 3600)
    m = int((s % 3600) / 60)
    if (d > 0) printf "%dd %02dh %02dm", d, h, m
    else printf "%02dh %02dm", h, m
  }' /proc/uptime 2>/dev/null)"
  if [[ -z "$text" ]]; then
    text="$(uptime -p 2>/dev/null | sed -e 's/^up //' -e 's/ days\?/d/' -e 's/ hours\?/h/' -e 's/ minutes\?/m/' -e 's/ seconds\?/s/' -e 's/,//g')"
  fi
  printf '%s' "${text:-$(t not_available)}"
}

dash_load_text() {
  local text
  text="$(awk '{printf "%.1f %.1f %.1f", $1, $2, $3}' /proc/loadavg 2>/dev/null)"
  if [[ -z "$text" ]]; then
    text="$(uptime 2>/dev/null | sed -n 's/.*load average[s]*: //p' | tr ',' ' ' | tr -s ' ' | awk '{printf "%.1f %.1f %.1f", $1, $2, $3}')"
  fi
  printf '%s' "${text:-$(t not_available)}"
}

dash_proto_on() {
  local unit
  for unit in $(proto_units "$1"); do
    service_active "$unit" && return 0
  done
  return 1
}

proto_label_ports() {
  local id="$1" label
  label="$(t "proto_$id")"
  if [[ "$label" != *"/"* ]]; then
    label+=" $(proto_ports_label "$id")"
  fi
  printf '%s' "$label"
}

dash_proto_name() {
  case "$1" in
    badvpn) printf 'BadVPN UDPGW' ;;
    *) t "proto_$1" ;;
  esac
}

dash_proto_cell() {
  local id="$1" width="$2" status color text
  if [[ -z "$id" ]]; then
    printf '%*s' "$width" ''
    return 0
  fi
  if dash_proto_on "$id"; then
    status="$(t dash_on)"
    color="$UI_ON"
  else
    status="$(t dash_off)"
    color="$UI_OFF"
  fi
  if (( UI_COLS >= 96 )); then
    text=" [$status] $(proto_label_ports "$id")"
  else
    text=" [$status] $(dash_proto_name "$id")"
  fi
  if (( ${#text} > width )); then
    text=" [$status] $(dash_proto_name "$id")"
  fi
  printf '%s%s%s' "$color" "$(dash_pad "$text" "$width")" "$UI_RESET"
}

dash_tool_cell() {
  local num="$1" label="$2" width="$3" prefix pad
  if [[ -z "$num" ]]; then
    printf '%*s' "$width" ''
    return 0
  fi
  prefix=" ${num} "
  label="$(ui_fit "$label" $(( width - ${#prefix} )))"
  pad=$(( width - ${#prefix} - ${#label} ))
  (( pad < 0 )) && pad=0
  printf '%s%s%s%s%s%s%*s' "$UI_MAGENTA" "$prefix" "$UI_RESET" "$UI_CYAN" "$label" "$UI_RESET" "$pad" ''
}

dash_rule() {
  local width="$1" char="${2:--}"
  printf '  %s+%s+%s\n' "$UI_BORDER" "$(ui_fill "$char" "$width")" "$UI_RESET"
}

dash_box_top() {
  local title="$1" width="$2" shown fill
  shown="$(ui_fit "$title" $(( width - 8 )))"
  fill=$(( width - ${#shown} - 6 ))
  (( fill < 0 )) && fill=0
  printf '  %s+--[ %s%s%s ]%s%s+%s\n' \
    "$UI_BORDER" "$UI_BOLD$UI_CYAN" "$shown" "$UI_BORDER" \
    "$(ui_fill '-' "$fill")" "$UI_BORDER" "$UI_RESET"
}

dash_box_row() {
  local text="$1" width="$2" color="${3:-$UI_WHITE}"
  text="$(ui_fit "$text" $(( width - 2 )))"
  printf '  %s|' "$UI_BORDER"
  printf '%s %s%s' "$color" "$text" "$UI_RESET"
  printf '%*s' "$(( width - ${#text} - 2 ))" ''
  printf '%s|%s\n' "$UI_BORDER" "$UI_RESET"
}

dash_section_row() {
  local text="$1" width="$2"
  text="$(ui_fit "$text" $(( width - 2 )))"
  printf '  %s|' "$UI_BORDER"
  printf '%s %s%s' "$UI_BOLD$UI_MAGENTA" "$text" "$UI_RESET"
  printf '%*s' "$(( width - ${#text} - 2 ))" ''
  printf '%s|%s\n' "$UI_BORDER" "$UI_RESET"
}

dash_plain_line() {
  local text="$1" color="${2:-$UI_WHITE}" max
  ui_init
  max=$(( UI_COLS - 2 ))
  (( max < 1 )) && max=1
  text="$(ui_fit "$text" "$max")"
  printf '  %s%s%s\n' "$color" "$text" "$UI_RESET"
}

dash_title_line() {
  local width="$1" theme_name host left right fill sub pad line2 up user
  theme_name="$(theme_label "${UI_THEME:-debian}")"
  host="$(hostname 2>/dev/null || t not_available)"
  up="$(dash_uptime_text)"
  user="$(id -un 2>/dev/null || t not_available)"
  left="NANO PANEL v${APP_VERSION}"
  fill=$(( width - ${#left} - 6 ))
  (( fill < 0 )) && fill=0
  printf '  %s+==[ %s%s%s ]%s%s+%s\n' \
    "$UI_BORDER" "$UI_BOLD$UI_CYAN" "$left" "$UI_BORDER" \
    "$(ui_fill '=' "$fill")" "$UI_BORDER" "$UI_RESET"
  sub="$(t main_title)"
  right="$theme_name"
  pad=$(( width - 2 - ${#sub} - ${#right} ))
  if (( pad < 1 )); then
    right="$(ui_fit "$right" $(( width - ${#sub} - 4 )))"
    pad=$(( width - 2 - ${#sub} - ${#right} ))
  fi
  (( pad < 0 )) && pad=0
  printf '  %s| %s%s%s%*s%s%s%s |%s\n' \
    "$UI_BORDER" "$UI_DIM" "$sub" "$UI_RESET" "$pad" '' \
    "$UI_MAGENTA" "$right" "$UI_BORDER" "$UI_RESET"
  if (( width >= 72 )); then
    line2="$(t dash_host): $host  |  $(t dash_uptime): $up  |  $(t dash_user): $user"
  else
    line2="$(t dash_host): $host  |  $(t dash_uptime): $up"
  fi
  line2="$(ui_fit "$line2" $(( width - 2 )))"
  printf '  %s| %s%s%s%*s%s|%s\n' \
    "$UI_BORDER" "$UI_CYAN" "$line2" "$UI_RESET" \
    "$(( width - ${#line2} - 1 ))" '' "$UI_BORDER" "$UI_RESET"
  printf '  %s+%s+%s\n' "$UI_BORDER" "$(ui_fill '=' "$width")" "$UI_RESET"
}

dash_stats_box() {
  local width="$1" c1 c2 c3 used limit remaining cpu ram disk netrow
  read -r c1 c2 c3 < <(dash_cells3 "$width")
  traffic_load
  if [[ -r "$NANO_TRAFFIC_FILE" ]]; then
    traffic_refresh
  else
    TRAFFIC_USED_BYTES=0
    TRAFFIC_LIMIT_BYTES=0
    TRAFFIC_PERCENT=0
    TRAFFIC_IFACE="$(traffic_iface)"
  fi
  cpu="$(dash_cpu_percent)"
  ram="$(dash_mem_used_percent)"
  disk="$(dash_disk_percent)"
  [[ "$cpu" =~ ^[0-9]+$ ]] || cpu=0
  [[ "$ram" =~ ^[0-9]+$ ]] || ram=0
  [[ "$disk" =~ ^[0-9]+$ ]] || disk=0
  used="$(human_bytes "${TRAFFIC_USED_BYTES:-0}")"
  limit="$(human_bytes "${TRAFFIC_LIMIT_BYTES:-0}")"
  dash_box_top "$(t dash_resources)" "$width"
  if (( width < 72 )); then
    dash_compact_stats_row "$width" "$cpu" "$ram" "$disk"
  else
    printf '  %s|' "$UI_BORDER"
    dash_plain_cell " $(t dash_cpu) $cpu% $(dash_meter "$cpu" 8)" "$c1" "$UI_CYAN"
    printf '%s|' "$UI_BORDER"
    dash_plain_cell " $(t dash_ram) $ram% $(dash_meter "$ram" 8)" "$c2" "$UI_LIME"
    printf '%s|' "$UI_BORDER"
    dash_plain_cell " $(t dash_disk) $disk% $(dash_meter "$disk" 8)" "$c3" "$UI_ORANGE"
    printf '%s|%s\n' "$UI_BORDER" "$UI_RESET"
  fi
  if (( ${TRAFFIC_LIMIT_BYTES:-0} > 0 )); then
    remaining="$(human_bytes $(( TRAFFIC_LIMIT_BYTES > TRAFFIC_USED_BYTES ? TRAFFIC_LIMIT_BYTES - TRAFFIC_USED_BYTES : 0 )))"
    netrow="$(t dash_network): ${TRAFFIC_IFACE:-$(t not_available)}  |  $(t dash_used) $used  |  $(t dash_limit) $limit  |  $(t dash_remaining) $remaining"
  else
    netrow="$(t dash_network): ${TRAFFIC_IFACE:-$(t not_available)}  |  $(t dash_used) $used  |  $(t dash_no_quota)"
  fi
  dash_box_row "$netrow" "$width" "$UI_DIM"
  dash_rule "$width" '-'
}

dash_protocol_summary() {
  local id count=0 total=0 names="" label
  for id in ssh ws slowdns ssl hcr bhttp badvpn udp_custom hysteria xray dropbear; do
    total=$(( total + 1 ))
    if dash_proto_on "$id"; then
      count=$(( count + 1 ))
      label="$(t "proto_$id")"
      names="${names:+$names, }$label"
    fi
  done
  printf '%s/%s' "$count" "$total"
  [[ -n "$names" ]] && printf '  (%s)' "$names"
}

dash_protocols_box() {
  local width="$1" c1 c2 i ids
  ids=(ssh ws slowdns ssl hcr bhttp badvpn udp_custom hysteria xray dropbear "")
  c1=$(( (width - 1) * 47 / 100 ))
  c2=$(( width - 1 - c1 ))
  dash_box_top "$(t dash_protocols)" "$width"
  for (( i = 0; i < 12; i += 2 )); do
    printf '  %s|' "$UI_BORDER"
    dash_proto_cell "${ids[$i]}" "$c1"
    printf '%s|' "$UI_BORDER"
    dash_proto_cell "${ids[$((i + 1))]}" "$c2"
    printf '%s|%s\n' "$UI_BORDER" "$UI_RESET"
  done
  dash_rule "$width" '-'
}

dash_tools_box() {
  local width="$1" tools="" c line="" avail
  for c in ss netstat ip ifconfig lsof dig ping curl wget git tar nano htop ssh systemctl ufw firewall-cmd; do
    have "$c" && tools+="$c "
  done
  tools="${tools% }"
  avail=$(( width - 4 ))
  dash_box_top "$(t dash_tools)" "$width"
  if [[ -z "$tools" ]]; then
    dash_box_row "$(t none)" "$width" "$UI_DIM"
  else
    for c in $tools; do
      if [[ -z "$line" ]]; then
        line="$c"
      elif (( ${#line} + ${#c} + 1 > avail )); then
        dash_box_row "$line" "$width" "$UI_DIM"
        line="$c"
      else
        line+=" $c"
      fi
    done
    dash_box_row "$line" "$width" "$UI_DIM"
  fi
  dash_rule "$width" '-'
}

dash_compact_stats_row() {
  local width="$1" cpu="$2" ram="$3" disk="$4" c1 c2 c3
  read -r c1 c2 c3 < <(dash_cells3 "$width")
  printf '  %s|' "$UI_BORDER"
  dash_plain_cell " $(t dash_cpu) $cpu%" "$c1" "$UI_CYAN"
  printf '%s|' "$UI_BORDER"
  dash_plain_cell " $(t dash_ram) $ram%" "$c2" "$UI_LIME"
  printf '%s|' "$UI_BORDER"
  dash_plain_cell " $(t dash_disk) $disk%" "$c3" "$UI_ORANGE"
  printf '%s|%s\n' "$UI_BORDER" "$UI_RESET"
}

dash_status_box() {
  local width="$1" host up user theme summary
  host="$(hostname 2>/dev/null || t not_available)"
  up="$(dash_uptime_text)"
  user="$(id -un 2>/dev/null || t not_available)"
  theme="$(theme_label "${UI_THEME:-debian}")"
  summary="$(dash_protocol_summary)"
  summary="${summary%% *}"
  dash_box_top "$(t dash_status)" "$width"
  dash_box_row " $(t dash_ready)  |  $(t dash_active): $summary" "$width" "$UI_LIME"
  dash_box_row " $(t dash_host): $host" "$width" "$UI_CYAN"
  dash_box_row " $(t dash_uptime): $up" "$width" "$UI_DIM"
  dash_box_row " $(t dash_user): $user" "$width" "$UI_CYAN"
  dash_box_row " $(t dash_theme): $theme" "$width" "$UI_MAGENTA"
  dash_box_row " $(t dash_language): ${LANGUAGE^^}" "$width" "$UI_LIME"
  dash_box_row " $(t dash_press)" "$width" "$UI_DIM"
  dash_box_row " 1-12 / 0" "$width" "$UI_BOLD$UI_MAGENTA"
  dash_rule "$width" '-'
}

dash_two_cols() {
  local width="$1" lw rw i n
  lw=$(( (width - 4) * 65 / 100 ))
  rw=$(( width - 4 - lw ))
  local -a left right
  mapfile -t left < <( dash_title_line "$lw"; dash_stats_box "$lw"; dash_protocols_box "$lw" )
  mapfile -t right < <( dash_tools_box "$rw"; dash_status_box "$rw" )
  n=${#left[@]}
  (( ${#right[@]} > n )) && n=${#right[@]}
  for (( i = 0; i < n; i++ )); do
    if (( i < ${#left[@]} )); then
      printf '%s' "${left[$i]}"
    else
      printf '%*s' $(( lw + 4 )) ''
    fi
    if (( i < ${#right[@]} )); then
      printf '%s\n' "${right[$i]}"
    else
      printf '\n'
    fi
  done
}

dash_footer_line() {
  local width="$1" user version lang theme
  version="v${APP_VERSION}"
  lang="${LANGUAGE^^}"
  theme="$(theme_label "${UI_THEME:-debian}")"
  printf '  %s%s%s %s|%s %s%s%s' \
    "$UI_BOLD$UI_CYAN" "$version" "$UI_RESET" \
    "$UI_DIM" "$UI_RESET" "$UI_LIME" "$lang" "$UI_RESET"
  if (( UI_COLS >= 96 )); then
    user="$(id -un 2>/dev/null || t not_available)"
    printf ' %s|%s %s%s: %s%s' \
      "$UI_DIM" "$UI_RESET" "$UI_DIM" "$(t dash_user)" "$user" "$UI_RESET"
  fi
  printf ' %s|%s %s%s%s\n' \
    "$UI_DIM" "$UI_RESET" "$UI_MAGENTA" "$theme" "$UI_RESET"
}

dash_compact_minimal() {
  local cpu ram disk host up width profile
  ui_frame_begin
  if (( UI_TTY )); then clear 2>/dev/null || true; fi
  cpu="$(dash_cpu_percent)"
  ram="$(dash_mem_used_percent)"
  disk="$(dash_disk_percent)"
  [[ "$cpu" =~ ^[0-9]+$ ]] || cpu=0
  [[ "$ram" =~ ^[0-9]+$ ]] || ram=0
  [[ "$disk" =~ ^[0-9]+$ ]] || disk=0
  host="$(hostname 2>/dev/null || t not_available)"
  up="$(dash_uptime_text)"
  width="$(dash_box_width)"
  profile="$(ui_profile)"
  dash_box_top "NANO PANEL v${APP_VERSION}" "$width"
  dash_box_row " $(t dash_host): $(ui_fit "$host" $(( width - 18 )))" "$width" "$UI_CYAN"
  dash_box_row " $(t dash_uptime): $up" "$width" "$UI_DIM"
  dash_rule "$width" '-'
  dash_box_top "$(t dash_resources)" "$width"
  dash_box_row " CPU  $(dash_meter "$cpu" 12)  ${cpu}%" "$width" "$UI_CYAN"
  dash_box_row " RAM  $(dash_meter "$ram" 12)  ${ram}%" "$width" "$UI_LIME"
  dash_box_row " DISK $(dash_meter "$disk" 12)  ${disk}%" "$width" "$UI_ORANGE"
  dash_rule "$width" '-'
  dash_box_top "$(t dash_protocols)" "$width"
  dash_box_row " $(dash_protocol_summary)" "$width" "$UI_MAGENTA"
  dash_rule "$width" '-'
  dash_plain_line "$(t dash_quick)" "$UI_BOLD$UI_MAGENTA"
  ui_menu "1|$(t menu_diag)" "2|$(t menu_ports)" "3|$(t menu_services)" \
    "4|$(t menu_ssh)" "5|$(t menu_backup)" "6|$(t menu_install)" \
    "7|$(t menu_protocols)" "8|$(t menu_firewall)" "9|$(t menu_settings)" \
    "10|$(t menu_language)" "11|$(t menu_theme)" "12|$(t menu_root)" "0|$(t menu_exit)"
  dash_footer_line "$width"
}

dash_compact() {
  local width cpu ram disk used limit host up netrow
  ui_frame_begin
  if (( UI_TTY )); then clear 2>/dev/null || true; fi
  width="$(dash_box_width)"
  traffic_load
  if [[ -r "$NANO_TRAFFIC_FILE" ]]; then
    traffic_refresh
  else
    TRAFFIC_USED_BYTES=0
    TRAFFIC_LIMIT_BYTES=0
    TRAFFIC_PERCENT=0
    TRAFFIC_IFACE="$(traffic_iface)"
  fi
  cpu="$(dash_cpu_percent)"
  ram="$(dash_mem_used_percent)"
  disk="$(dash_disk_percent)"
  [[ "$cpu" =~ ^[0-9]+$ ]] || cpu=0
  [[ "$ram" =~ ^[0-9]+$ ]] || ram=0
  [[ "$disk" =~ ^[0-9]+$ ]] || disk=0
  used="$(human_bytes "${TRAFFIC_USED_BYTES:-0}")"
  limit="$(human_bytes "${TRAFFIC_LIMIT_BYTES:-0}")"
  host="$(hostname 2>/dev/null || t not_available)"
  up="$(dash_uptime_text)"
  dash_title_line "$width"
  dash_box_top "$(t dash_resources)" "$width"
  dash_compact_stats_row "$width" "$cpu" "$ram" "$disk"
  if (( ${TRAFFIC_LIMIT_BYTES:-0} > 0 )); then
    netrow="$(t dash_network): ${TRAFFIC_IFACE:-$(t not_available)}  |  $(t dash_used) $used  |  $(t dash_limit) $limit"
  else
    netrow="$(t dash_network): ${TRAFFIC_IFACE:-$(t not_available)}  |  $(t dash_used) $used  |  $(t dash_no_quota)"
  fi
  dash_box_row " $netrow" "$width" "$UI_DIM"
  dash_rule "$width" '-'
  dash_plain_line "$(t dash_protocols): $(dash_protocol_summary)" "$UI_MAGENTA"
  dash_plain_line "$(t dash_status): $(t dash_ready)  |  $(t dash_language): ${LANGUAGE^^}" "$UI_LIME"
  dash_rule "$width" '-'
  dash_footer_line "$width"
  ui_menu "1|$(t menu_diag)" "2|$(t menu_ports)" "3|$(t menu_services)" \
    "4|$(t menu_ssh)" "5|$(t menu_backup)" "6|$(t menu_install)" \
    "7|$(t menu_protocols)" "8|$(t menu_firewall)" "9|$(t menu_settings)" \
    "10|$(t menu_language)" "11|$(t menu_theme)" "12|$(t menu_root)" "0|$(t menu_exit)"
}

dash_render() {
  local width
  ui_frame_begin
  if (( UI_COLS < 60 || UI_LINES < 22 )); then
    dash_compact_minimal
    return 0
  fi
  if (( UI_COLS < 92 || UI_LINES < 26 )); then
    dash_compact
    return 0
  fi
  width="$(dash_box_width)"
  if (( UI_COLS >= 92 && UI_LINES >= 26 )); then
    if (( UI_TTY )); then clear 2>/dev/null || true; fi
    dash_two_cols "$width"
    printf '\n'
    dash_plain_line "$(t dash_quick)" "$UI_BOLD$UI_MAGENTA"
    printf '\n'
    dash_footer_line "$width"
    ui_menu "1|$(t menu_diag)" "2|$(t menu_ports)" "3|$(t menu_services)" \
      "4|$(t menu_ssh)" "5|$(t menu_backup)" "6|$(t menu_install)" \
      "7|$(t menu_protocols)" "8|$(t menu_firewall)" "9|$(t menu_settings)" \
      "10|$(t menu_language)" "11|$(t menu_theme)" "12|$(t menu_root)" "0|$(t menu_exit)"
    return 0
  fi
  if (( UI_TTY )); then clear 2>/dev/null || true; fi
  dash_title_line "$width"
  dash_stats_box "$width"
  dash_protocols_box "$width"
  dash_tools_box "$width"
  printf '\n'
  dash_plain_line "$(t dash_quick)" "$UI_BOLD$UI_MAGENTA"
  printf '\n'
  dash_footer_line "$width"
  ui_menu "1|$(t menu_diag)" "2|$(t menu_ports)" "3|$(t menu_services)" \
    "4|$(t menu_ssh)" "5|$(t menu_backup)" "6|$(t menu_install)" \
    "7|$(t menu_protocols)" "8|$(t menu_firewall)" "9|$(t menu_settings)" \
    "10|$(t menu_language)" "11|$(t menu_theme)" "12|$(t menu_root)" "0|$(t menu_exit)"
}


main_menu() {
  while true; do
    dash_render
    traffic_alert_check || true
    ask || continue
    case "$REPLY" in
      1) system_summary ;;
      2) ports_menu ;;
      3) services_menu ;;
      4) ssh_users_menu ;;
      5) backup_menu ;;
      6) install_menu ;;
      7) protocols_menu ;;
      8) firewall_menu ;;
      9) settings_menu ;;
      10) choose_language || true ;;
      11) theme_menu ;;
      12) root_relaunch || true ;;
      0) say bye; exit 0 ;;
      *) say invalid; sleep 1 ;;
    esac
  done
}

main() {
  local mode="menu" override="" arg protocol_install=""
  NANO_ORIGINAL_ARGS=("$@")

  load_i18n
  load_language
  ui_install_resize_trap
  ui_init

  while (( $# )); do
    arg="$1"
    case "$arg" in
      --lang)
        shift
        if (( $# == 0 )); then
          say cli_missing_lang
          exit 2
        fi
        override="$1"
        ;;
      --lang=*) override="${arg#*=}" ;;
      --install-protocol)
        shift
        if (( $# == 0 )); then sayf cli_unknown "--install-protocol"; exit 2; fi
        protocol_install="$1"
        mode="protocol-install"
        ;;
      --diagnose) mode="diagnose" ;;
      --version|-v) printf '%s v %s\n' "$APP_NAME" "$APP_VERSION"; exit 0 ;;
      --help|-h) mode="help" ;;
      *)
        sayf cli_unknown "$arg"
        exit 2
        ;;
    esac
    shift
  done

  if [[ -n "$override" ]]; then
    case "$override" in
      es|en|pt|fr) LANGUAGE="$override" ;;
      *) say language_invalid; exit 2 ;;
    esac
  fi

  if [[ "$mode" == "menu" ]]; then
    if [[ ! -f "$(first_run_marker)" ]]; then
      if ! choose_language; then exit 0; fi
    elif [[ -z "$LANGUAGE" ]]; then
      LANGUAGE="$(detect_lang)"
      if ! choose_language; then exit 0; fi
    fi
  elif [[ -z "$LANGUAGE" ]]; then
    LANGUAGE="$(detect_lang)"
  fi

  case "$mode" in
    help) print_help; exit 0 ;;
    diagnose) print_diag; exit 0 ;;
    protocol-install)
      case "$protocol_install" in ssh|ws|slowdns|ssl|hcr|bhttp|hysteria|xray|dropbear|badvpn|udp_custom) ;;
        *) sayf cli_unknown "--install-protocol $protocol_install"; exit 2 ;;
      esac
      proto_install_dispatch "$protocol_install"
      exit $? ;;
  esac

  if [[ "$mode" == "menu" ]] && (( UI_TTY )) && (( ! UI_BANNER_SHOWN )); then
    title
    sleep 1
  fi

  first_run_wizard
  main_menu
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  main "$@"
fi